INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教小朋友学东西，让他们变聪明。", "primary_collocate": null, "pronunciation": "jiào yù", "ipa": "tɕjɑʊ̯˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "老师在教育孩子要爱干净。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母应该好好教育自己的孩子。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小被爸妈好好教育，懂得很多道理。", "target_word": "教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教育了弟弟，不能打人。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师会用心教育学生，让他们变聪明。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校应该从小就教育学生懂道理。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子做错了事，我们要耐心教育他。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师很会教育小朋友。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候爸妈常常教育我，这对我影响很大。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸常用故事教育我们做人要诚实。", "target_word": "教育", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "教育了", "label": "体标"}, {"form": "教育过", "label": "体标"}], "register": "中性", "sense_fingerprint": "教导孩子，让他们学知识、懂道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "正确：“教育孩子”指教导孩子养成好习惯，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间或场所，不能说“打扫孩子”。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给吃的，与“让孩子爱干净”的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱孩子”。"}], "explanations": {"教育": "正确：“教育孩子”指教导孩子养成好习惯，符合语境。", "打扫": "搭配：“打扫”的对象是房间或场所，不能说“打扫孩子”。", "喂": "语义：“喂”指给吃的，与“让孩子爱干净”的意思不符。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱孩子”。"}, "sentence_index": 0, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天下午教育三只小狗跑步。", "explanation": "这里应该用〈训练〉。“教育”针对人的品德和知识，训练动物要用〈训练〉。"}, {"text": "我们要教育孩子的阅读兴趣。", "explanation": "这里应该用〈培养〉。“教育”侧重品行和道理，不说“教育兴趣”；兴趣要用〈培养〉。"}, {"text": "农民每天教育田里的庄稼。", "explanation": "这里应该用〈照料〉。“教育”的对象是人，庄稼是植物，照料田里的庄稼要用〈照料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教育", "is_correct": true, "explanation": "正确：“教育”指耐心教导犯错的孩子，符合“做错了事”的语境。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”的对象是物品，不能用于人。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱和赞美，与“做错了事”的语境不符。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”指探究事物，不能用来表示对犯错孩子的管教。"}], "explanations": {"教育": "正确：“教育”指耐心教导犯错的孩子，符合“做错了事”的语境。", "包装": "搭配：“包装”的对象是物品，不能用于人。", "欣赏": "语义：“欣赏”是喜爱和赞美，与“做错了事”的语境不符。", "研究": "语义：“研究”指探究事物，不能用来表示对犯错孩子的管教。"}, "sentence_index": 6, "correct_answer": "教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都教育厨房里的锅碗。", "explanation": "这里应该用〈洗〉。〈教育〉的对象是人，锅碗是物品，不能教育；洗锅碗要用〈洗〉。"}, {"text": "他认真地教育了那辆自行车。", "explanation": "这里应该用〈修理〉。〈教育〉的对象是人，自行车是物品，不能教育；修车要用〈修理〉。"}, {"text": "老师教育了黑板上的这些字。", "explanation": "这里应该用〈擦〉。〈教育〉的对象是人，字不能被教育；擦黑板上的字要用〈擦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师经常的教育学生要诚实。", "corrected_sentence": "老师经常教育学生要诚实。", "error_description": "副词“经常”修饰动词“教育”时，中间不能加“的”，应说“经常教育”，不能说“经常的教育”，否则“教育”会被误认为名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸把我们教育了成诚实的人。", "corrected_sentence": "爸爸把我们教育成了诚实的人。", "error_description": "“教育成”是动补结构，“了”应放在“成”之后，应说“教育成了”，不能插在“教育”和“成”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
