INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类很久以前到现在的生活和事情，加在一起就是文明史。", "primary_collocate": null, "pronunciation": "wén míng shǐ", "ipa": "wən˧˥ miŋ˧˥ ʂɻ̩˨˩˦", "syllable_count": 3, "sentences": [{"text": "这本书讲的是人类文明史。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对中国文明史很感兴趣。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学了世界文明史。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文明史告诉我们过去发生了什么。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师研究文明史已经二十年了。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆的展览介绍了古代文明史。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于文明史的书，讲的是古代埃及。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学文明史，可以知道人类怎样生活。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多文明史的书。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文明史里有很多有名的故事。", "target_word": "文明史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人类文明史", "label": "复合"}, {"form": "世界文明史", "label": "复合"}], "register": "中性", "sense_fingerprint": "人类从很久以前到现在的生活和发展的历史", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文明史", "is_correct": true, "explanation": "正确：“讲的是人类文明史”，文明史是可以被讲述的历史主题，符合句意。"}, {"text": "植物", "is_correct": false, "explanation": "语义：“人类植物”不是书所讲的主题，书讲的是人类的发展历史。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人类历史的主题，说“讲的是人类天气”不通。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“人类夜晚”不成词，夜晚不是这本书讲述的人类历史主题。"}], "explanations": {"文明史": "正确：“讲的是人类文明史”，文明史是可以被讲述的历史主题，符合句意。", "植物": "语义：“人类植物”不是书所讲的主题，书讲的是人类的发展历史。", "天气": "语义：天气不是人类历史的主题，说“讲的是人类天气”不通。", "夜晚": "搭配：“人类夜晚”不成词，夜晚不是这本书讲述的人类历史主题。"}, "sentence_index": 0, "correct_answer": "文明史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的哥哥是一位文明史。", "explanation": "这里应该用〈历史学家〉。文明史是学科或书，不是人，不能作人的身份。"}, {"text": "这位老人有一段很长的文明史。", "explanation": "这里应该用〈经历〉。文明史指人类社会的发展，个人的经历不能说“文明史”。"}, {"text": "周末我们去文明史参观。", "explanation": "这里应该用〈博物馆〉。文明史是学科或书，不是场所，不能去它参观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文明史", "is_correct": true, "explanation": "正确：“写了一本关于……的书”，文明史可以作书的主题，符合句意。"}, {"text": "问号", "is_correct": false, "explanation": "语义：这本书讲的是古代埃及，问号与此无关，句意不通。"}, {"text": "句号", "is_correct": false, "explanation": "语义：这本书讲的是古代埃及，句号与此无关，句意不通。"}, {"text": "括号", "is_correct": false, "explanation": "语义：这本书讲的是古代埃及，括号与此无关，句意不通。"}], "explanations": {"文明史": "正确：“写了一本关于……的书”，文明史可以作书的主题，符合句意。", "问号": "语义：这本书讲的是古代埃及，问号与此无关，句意不通。", "句号": "语义：这本书讲的是古代埃及，句号与此无关，句意不通。", "括号": "语义：这本书讲的是古代埃及，括号与此无关，句意不通。"}, "sentence_index": 6, "correct_answer": "文明史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位文明史带我们参观博物馆。", "explanation": "这里应该用〈导游〉。文明史是学科或书，不能带人参观。"}, {"text": "这位文明史写了很多书。", "explanation": "这里应该用〈作家〉。文明史不是人，不能作“写书”的主语。"}, {"text": "这次比赛的文明史很精彩。", "explanation": "这里应该用〈历史〉。文明史指人类社会的发展，单场比赛的经过要说“历史”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一把文明史。", "corrected_sentence": "他学了一门文明史。", "error_description": "作学科用的“文明史”，量词应用“门”；“把”用于有柄的物品，不能修饰学科。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前读着文明史。", "corrected_sentence": "我以前读过文明史。", "error_description": "“着”表示动作进行或状态持续，与“以前”表示的经历不合，经历要用“过”，应说“读过文明史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
