INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "到处都有。", "primary_collocate": null, "pronunciation": "pǔ biàn cún zài", "ipa": "pʰu˨˩˦ pjɛn˥˩ tsʰwən˧˥ tsaɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这种小虫子在南方普遍存在，到处都能看到。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低头看手机的现象，在地铁里普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很常见，在北方普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路看手机的问题，在城市里普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这种错误在学生中普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里的灰尘普遍存在，家里也不例外。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋太多的问题，在很多地方普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种想法在年轻人中普遍存在着。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乱扔垃圾的现象，在这个城市普遍存在。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小店到处都是，普遍存在于各个街区。", "target_word": "普遍存在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍存在着", "label": "体标"}, {"form": "普遍存在于", "label": "搭配"}], "register": "中性", "sense_fingerprint": "某种东西或现象在各处都能见到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍存在", "is_correct": true, "explanation": "普遍存在：到处都有，与后句“到处都能看到”相合。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”与后句“到处都能看到”意思相反。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于影音内容，不用于小虫子。"}, {"text": "绝迹", "is_correct": false, "explanation": "语义：“绝迹”指一个也没有了，与“到处都能看到”矛盾。"}], "explanations": {"普遍存在": "普遍存在：到处都有，与后句“到处都能看到”相合。", "消失": "语义：“消失”与后句“到处都能看到”意思相反。", "播放": "搭配：“播放”用于影音内容，不用于小虫子。", "绝迹": "语义：“绝迹”指一个也没有了，与“到处都能看到”矛盾。"}, "sentence_index": 0, "correct_answer": "普遍存在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种花只在这个山谷普遍存在，别处都没有。", "explanation": "这里应该用〈独有〉。“普遍存在”指到处都有，与“只在这个山谷、别处都没有”相矛盾。"}, {"text": "我家那只小狗普遍存在于屋子里。", "explanation": "这里应该用〈待〉。“普遍存在”指同类现象到处都有，不能用来说一只具体的小狗待在哪里。"}, {"text": "这种鸟已经普遍存在了，却早已绝迹。", "explanation": "这里应该用〈稀少〉。“普遍存在”指到处都有，与后半句所说的“一个也不剩”正相反，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍存在", "is_correct": true, "explanation": "普遍存在：问题在很多地方都有，与句中“很多地方”相合。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”的对象是人，“问题”不能报名。"}, {"text": "下载", "is_correct": false, "explanation": "搭配：“下载”的对象是文件或软件，不能用于“问题”。"}, {"text": "开幕", "is_correct": false, "explanation": "语义：“开幕”用于活动、展览，不能说问题在各地“开幕”。"}], "explanations": {"普遍存在": "普遍存在：问题在很多地方都有，与句中“很多地方”相合。", "报名": "搭配：“报名”的对象是人，“问题”不能报名。", "下载": "搭配：“下载”的对象是文件或软件，不能用于“问题”。", "开幕": "语义：“开幕”用于活动、展览，不能说问题在各地“开幕”。"}, "sentence_index": 6, "correct_answer": "普遍存在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门手艺早已失传，却普遍存在于民间。", "explanation": "这里应该用〈残存〉。“普遍存在”指到处都有，与前半句所说的“不再流传”正相反，前后矛盾。"}, {"text": "这座古镇的老钟楼普遍存在于各个街区。", "explanation": "这里应该用〈屹立〉。老钟楼只有一座，“普遍存在”指同类事物到处都有，不能用来说它分布在各个街区。"}, {"text": "这种小店偶尔才能看到，却普遍存在。", "explanation": "这里应该用〈罕见〉。“普遍存在”指到处都有，与前半句所说的“很少见到”正相反，句子不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种小鱼普遍存在在河里，随处可见。", "corrected_sentence": "这种小鱼普遍存在于河里，随处可见。", "error_description": "错误形式：“普遍存在在河里”；正确形式：“普遍存在于河里”。“存在”后面引出处所要用介词“于”，不能再用“在”，“在”和“于”不能重复使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种小虫在树林里被普遍存在。", "corrected_sentence": "这种小虫在树林里普遍存在。", "error_description": "错误形式：“被普遍存在”；正确形式：“普遍存在”。“存在”是表示有无的动词，不能用于被字句，句中多出的“被”去掉即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
