INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "力量小的人。", "primary_collocate": null, "pronunciation": "ruò zhě", "ipa": "ʐuɔ˥˩ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大个子欺负弱者，真让人生气。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子小，一打架就成了弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在动物世界里，弱者很难活下去。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气小，在比赛里是弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥个子大，从不欺负弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们这一队人少力小，是比赛里的弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有人打人，他不能看着弱者挨打。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弱者打不过强者，只好跑开。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大孩子应该让着弱者，别抢小孩的玩具。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗太小了，是狗群里的弱者。", "target_word": "弱者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个弱者", "label": "量词"}], "register": "中性", "sense_fingerprint": "力气小、实力小的人，在对抗中处于下风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f17d8f4-7240-4fff-bcf3-3b883044363e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弱者", "is_correct": true, "explanation": "正确：指力气小、在对抗中处于下风的人，与“欺负”“真让人生气”的语境相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“欺负”的对象须是有生命的人或动物，不能说欺负桌子。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不能被欺负，“欺负空气”不成话。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“欺负”的对象须是人或动物，玻璃不能被欺负。"}], "explanations": {"弱者": "正确：指力气小、在对抗中处于下风的人，与“欺负”“真让人生气”的语境相合。", "桌子": "搭配：“欺负”的对象须是有生命的人或动物，不能说欺负桌子。", "空气": "搭配：空气不能被欺负，“欺负空气”不成话。", "玻璃": "搭配：“欺负”的对象须是人或动物，玻璃不能被欺负。"}, "sentence_index": 0, "correct_answer": "弱者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的弱者很高，比哥哥还高半个头。", "explanation": "这里应该用〈个子〉。弱者指力量小的人，不能用来形容身高。"}, {"text": "他的弱者很多，应该多锻炼身体。", "explanation": "这里应该用〈弱点〉。弱者指力量小的人，不指身体或性格上的缺陷。"}, {"text": "数学是他的弱者，但他很努力。", "explanation": "这里应该用〈弱项〉。弱者指人，不指某门学科上的薄弱之处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弱者", "is_correct": true, "explanation": "正确：力量小、容易挨打的人，与“路上有人打人”的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“挨打”的主语须是人或动物，石头不会挨打。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不会挨打，“看着窗户挨打”不成话。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军通常是胜者，与“挨打”的情境不合。"}], "explanations": {"弱者": "正确：力量小、容易挨打的人，与“路上有人打人”的语境相合。", "石头": "搭配：“挨打”的主语须是人或动物，石头不会挨打。", "窗户": "搭配：窗户不会挨打，“看着窗户挨打”不成话。", "冠军": "语义：冠军通常是胜者，与“挨打”的情境不合。"}, "sentence_index": 6, "correct_answer": "弱者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我最好的弱者。", "explanation": "这里应该用〈伙伴〉。弱者指力量小的人，不指朋友关系。"}, {"text": "这次比赛的弱者很强。", "explanation": "这里应该用〈对手〉。“弱者”与“很强”自相矛盾，应说对手。"}, {"text": "他最大的弱者是粗心。", "explanation": "这里应该用〈缺点〉。弱者指力量小的人，不能指缺点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一群孩子里，他是最明显的弱者的。", "corrected_sentence": "这一群孩子里，他是最明显的弱者。", "error_description": "句末多加了“的”：“最明显的弱者”后不应再加“的”，去掉即正确：他是最明显的弱者。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每次比赛都有很多弱者们被淘汰。", "corrected_sentence": "每次比赛都有很多弱者被淘汰。", "error_description": "“很多”与“们”不能同时用（都表示复数），去掉“们”即可：每次比赛都有很多弱者被淘汰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3b5e0e1-6ffd-4e8b-b80a-5ec13e6e28f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐约", "is_correct": true, "explanation": "“隐约”指模模糊糊、不清楚，与“很容易看出”意义相反，构成反义关系。"}, {"text": "精彩", "is_correct": false, "explanation": "“精彩”形容表演或内容出色，与“明显”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“明显”没有反义关系。"}, {"text": "快乐", "is_correct": false, "explanation": "“快乐”形容心情愉快，与“明显”没有反义关系。"}], "correct_answer": "隐约", "explanations": {"隐约": "“隐约”指模模糊糊、不清楚，与“很容易看出”意义相反，构成反义关系。", "精彩": "“精彩”形容表演或内容出色，与“明显”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“明显”没有反义关系。", "快乐": "“快乐”形容心情愉快，与“明显”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐约", "is_correct": true, "explanation": "“隐约”指模模糊糊、不清楚，与“很容易看出”意义相反，构成反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容范围广大，与“明显”没有反义关系。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容气氛或情绪高涨，与“明显”没有反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "“丰富”形容数量多、内容充实，与“明显”没有反义关系。"}], "correct_answer": "隐约", "explanations": {"隐约": "“隐约”指模模糊糊、不清楚，与“很容易看出”意义相反，构成反义关系。", "辽阔": "“辽阔”形容范围广大，与“明显”没有反义关系。", "热烈": "“热烈”形容气氛或情绪高涨，与“明显”没有反义关系。", "丰富": "“丰富”形容数量多、内容充实，与“明显”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很容易看出来或感觉到。", "primary_collocate": null, "pronunciation": "míng xiǎn", "ipa": "miŋ˧˥ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "屋里的味道很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明显不想说话。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑板上的字很明显，后面也看得见。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口音太明显了。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她明显很累，一直在打哈欠。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，山上的雪明显比城里多。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脸上的伤很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的标志很明显，不会走错。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音的变化不明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的包在人群里很明显。", "target_word": "明显", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不明显", "label": "否定形式"}, {"form": "明显地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "气味、声音、外表等很容易被看出或感觉到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明显", "is_correct": true, "explanation": "“明显”指味道容易被感觉到，与“味道很”搭配，符合句意。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音或场面，不能用来形容味道。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”多形容声音，味道不说“响亮”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能修饰味道。"}], "explanations": {"明显": "“明显”指味道容易被感觉到，与“味道很”搭配，符合句意。", "吵闹": "语义：“吵闹”形容声音或场面，不能用来形容味道。", "响亮": "搭配：“响亮”多形容声音，味道不说“响亮”。", "高大": "体貌：“高大”形容人或物的体型，不能修饰味道。"}, "sentence_index": 0, "correct_answer": "明显"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的操作很明显。", "explanation": "这里应该用〈熟练〉。“明显”指容易看出，形容操作的熟悉程度要用“熟练”。"}, {"text": "他遇事很明显。", "explanation": "这里应该用〈冷静〉。“明显”指容易看出，形容遇事时的镇定要用“冷静”，指不慌乱。"}, {"text": "这台仪器很明显。", "explanation": "这里应该用〈灵敏〉。“明显”指容易看出，形容仪器对变化的反应快要用“灵敏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明显", "is_correct": true, "explanation": "“明显”指伤痕容易被看出，与“伤很”搭配，符合句意。"}, {"text": "清爽", "is_correct": false, "explanation": "搭配：“清爽”多形容空气或感觉，不用来形容伤。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”形容性格、天气或语气，不能用来形容伤。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”需要对象（对…满意）且描述心理，不能用于伤。"}], "explanations": {"明显": "“明显”指伤痕容易被看出，与“伤很”搭配，符合句意。", "清爽": "搭配：“清爽”多形容空气或感觉，不用来形容伤。", "温和": "语义：“温和”形容性格、天气或语气，不能用来形容伤。", "满意": "配价：“满意”需要对象（对…满意）且描述心理，不能用于伤。"}, "sentence_index": 6, "correct_answer": "明显"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语说得很明显。", "explanation": "这里应该用〈流利〉。“明显”指容易看出，形容说外语的顺畅程度要用“流利”，不能用“明显”。"}, {"text": "他的心算很明显。", "explanation": "这里应该用〈快〉。“明显”指容易看出，心算的快慢要用“快”，不能说“明显”。"}, {"text": "他的头脑很明显。", "explanation": "这里应该用〈清晰〉。“明显”指容易看出，形容头脑、思路的条理要用“清晰”，指有条不紊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红色的标志在远处很明显地。", "corrected_sentence": "红色的标志在远处很明显。", "error_description": "“明显”作谓语时句末不能加“地”，应说“很明显”。“地”用于修饰动词，如“明显地增加”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛，他明显的比我们都强。", "corrected_sentence": "这次比赛，他明显比我们都强。", "error_description": "错误：“明显”作状语后不能加“的”，“明显的”变成定语，不能修饰后面的谓语。正确：应说“他明显比我们都强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
