INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用不直接说的话让别人明白。", "primary_collocate": null, "pronunciation": "àn shì", "ipa": "an˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他指了指杯子，暗示我给他倒水。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明暗示妈妈，他想要一只小狗。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友一直看表，暗示我们该走了。", "target_word": "暗示", "complexity_tier": "T3", "furigana": "péng yǒu yì zhí kàn biǎo àn shì wǒ men gāi zǒu le", "sentence_source": "generated"}, {"text": "她笑着暗示我，这件事别告诉别人。", "target_word": "暗示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板暗示大家，明年可能不加工资。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听出来了，他在暗示我帮忙。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用暗示，我明白你的意思。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师暗示学生，答案在第二页。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有直说，只是暗示我该努力了。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拍了拍我的肩，暗示我别紧张。", "target_word": "暗示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗示了", "label": "体标"}, {"form": "暗示着", "label": "体标"}, {"form": "暗示过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不直接说出来，用话或动作让别人自己明白想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指不直接说而用动作让对方明白。“他指了指杯子，暗示我给他倒水”，只有“暗示”符合。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆贺，与指杯子的动作不相关。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：“检查”的对象是事物或工作，不能说“检查我给他倒水”。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”表示不计较过错，与指杯子的动作无关。"}], "explanations": {"暗示": "暗示指不直接说而用动作让对方明白。“他指了指杯子，暗示我给他倒水”，只有“暗示”符合。", "祝贺": "语义：“祝贺”表示庆贺，与指杯子的动作不相关。", "检查": "搭配：“检查”的对象是事物或工作，不能说“检查我给他倒水”。", "原谅": "语义：“原谅”表示不计较过错，与指杯子的动作无关。"}, "sentence_index": 0, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班主任正式暗示同学们，下周要进行期末考试。", "explanation": "这里应该用〈通知〉。暗示是含蓄表达，正式的通知要直接说明，不能用暗示。"}, {"text": "这张表格暗示了每个人的分数，大家都很满意。", "explanation": "这里应该用〈列出〉。暗示是含蓄表达，分数应直接列出，不能用暗示。"}, {"text": "他暗示得很大声，连隔壁的人都听见了。", "explanation": "这里应该用〈喊〉。暗示是含蓄表达，不能与“很大声”这样直接的说法搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗示", "is_correct": true, "explanation": "暗示指含蓄地表达。“你不用暗示，我明白你的意思”说明对方的表达方式含蓄，只有“暗示”符合。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算数，与“明白你的意思”无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品，不能说“洗你的意思”。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：“绘画”指作画，与表达意思的语境不符。"}], "explanations": {"暗示": "暗示指含蓄地表达。“你不用暗示，我明白你的意思”说明对方的表达方式含蓄，只有“暗示”符合。", "计算": "语义：“计算”指算数，与“明白你的意思”无关。", "洗": "搭配：“洗”的对象是物品，不能说“洗你的意思”。", "绘画": "语义：“绘画”指作画，与表达意思的语境不符。"}, "sentence_index": 6, "correct_answer": "暗示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上暗示了所有答案，写得一清二楚。", "explanation": "这里应该用〈写出〉。暗示是含蓄表达，不能与“写得一清二楚”这样明确的说法搭配。"}, {"text": "我在电话里暗示了她的名字，她很高兴。", "explanation": "这里应该用〈告诉〉。暗示是含蓄表达，不能用来直接说出具体的名字。"}, {"text": "这份合同暗示了全部条款，请大家认真阅读。", "explanation": "这里应该用〈写明〉。暗示是含蓄表达，合同条款必须明确写出，不能用暗示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他暗示了过我两次，但我没有听懂。", "corrected_sentence": "他暗示过我两次，但我没有听懂。", "error_description": "“暗示”后面同时加了“了”和“过”。两种体标不能同时使用，应只说“暗示过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有直接说，只是把暗示了我的想法。", "corrected_sentence": "他没有直接说，只是暗示了我的想法。", "error_description": "“把”字结构用错了。“暗示”前面没有需要提前的宾语，不能加“把”，应直接说“暗示了我的想法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
