INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20362, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两件事关系很近。", "primary_collocate": null, "pronunciation": "mì qiè xiāng guān", "ipa": "mi˥˩ tɕʰjɛ˥˩ ɕjaŋ˥ kwan˥", "syllable_count": 4, "sentences": [{"text": "学习好不好和睡觉早不早密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的快乐和家人的健康密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个问题密切相关，要一起解决。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷热和我们穿的衣服密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，读书和写作密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子的钱和工作的好坏密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭的习惯与身体的变化密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两条新闻讲的事密切相关，你可以一起看。", "target_word": "密切相关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学语言和多听多说密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得，心情好坏与天气密切相关。", "target_word": "密切相关", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "密切相關", "label": "繁体"}], "register": "书面", "sense_fingerprint": "两件事之间关系很近、联系很紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密切相关", "is_correct": true, "explanation": "“密切相关”指两件事联系很紧，与“学习好不好和睡觉早不早”的关系相符。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”说距离远，与两件事之间的紧密联系相反。"}, {"text": "陌生", "is_correct": false, "explanation": "配价：“陌生”要用“对……陌生”，不能用“与……陌生”来说两件事的关系。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，不能用来说两件事的关系。"}], "explanations": {"密切相关": "“密切相关”指两件事联系很紧，与“学习好不好和睡觉早不早”的关系相符。", "遥远": "语义：“遥远”说距离远，与两件事之间的紧密联系相反。", "陌生": "配价：“陌生”要用“对……陌生”，不能用“与……陌生”来说两件事的关系。", "高大": "体貌：“高大”形容人或物的形体，不能用来说两件事的关系。"}, "sentence_index": 0, "correct_answer": "密切相关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和她是很密切相关的好朋友。", "explanation": "这里应该用〈亲密〉。“密切相关”说的是两件事之间的联系，不用来形容人与人之间的感情。"}, {"text": "这两个孩子长得很密切相关。", "explanation": "这里应该用〈相似〉。“密切相关”说的是两件事之间的联系，不用来说两个人外貌相像。"}, {"text": "他对这一带的路很密切相关。", "explanation": "这里应该用〈熟悉〉。“密切相关”说的是两件事之间的联系，不用来说一个人对路况了解得多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密切相关", "is_correct": true, "explanation": "“密切相关”指吃饭的习惯与身体的变化之间有紧密联系，与句意一致。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能用来说习惯与变化的关系。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：“笔直”形容形状或姿态，不用于描述习惯与变化之间的关系。"}, {"text": "生硬", "is_correct": false, "explanation": "搭配：“生硬”多用来形容语言或态度，不与“习惯”“变化”搭配。"}], "explanations": {"密切相关": "“密切相关”指吃饭的习惯与身体的变化之间有紧密联系，与句意一致。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能用来说习惯与变化的关系。", "笔直": "体貌：“笔直”形容形状或姿态，不用于描述习惯与变化之间的关系。", "生硬": "搭配：“生硬”多用来形容语言或态度，不与“习惯”“变化”搭配。"}, "sentence_index": 6, "correct_answer": "密切相关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事跟我只是有一点密切相关。", "explanation": "这里应该用〈有关〉。“只是有一点”说明关系较弱，与“密切相关”强调联系紧密不符。"}, {"text": "这家饭馆的服务很密切相关。", "explanation": "这里应该用〈亲切〉。“密切相关”说的是两件事之间的联系，不用来形容服务的态度。"}, {"text": "我家离学校很密切相关。", "explanation": "这里应该用〈近〉。说距离远近要用“近”，“密切相关”不用来描述空间距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的结果被大家的努力密切相关。", "corrected_sentence": "这件事的结果与大家的努力密切相关。", "error_description": "错误：“被”表被动，“密切相关”不能用于被动句。正确：应用“与”引出关联对象，即“与……密切相关”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市的交通把居民的出行密切相关。", "corrected_sentence": "城市的交通与居民的出行密切相关。", "error_description": "错误：“把”字引出“居民的出行”。正确：应用“与”引出关联对象，“密切相关”不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
