INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20364, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度比一般稍高，用在形容词前。", "primary_collocate": null, "pronunciation": "jiào", "ipa": "tɕiaʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "这个房间较大，住三个人没问题。", "target_word": "较", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温较低，要多穿衣服。", "target_word": "较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语水平较高。", "target_word": "较", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的价格较贵。", "target_word": "较", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年雨水较多，河水涨了。", "target_word": "较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上的车较少，走起来很快。", "target_word": "较", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得第二个办法较好。", "target_word": "较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的冬天较冷，南方较暖和。", "target_word": "较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的内容较难，小学生看不懂。", "target_word": "较", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体较弱，不能跑太远。", "target_word": "较", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示程度比一般稍高，用在形容词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f97476-a1c8-44d6-945d-bc65b062c339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "较", "is_correct": true, "explanation": "正确。“较”（jiào，第四声）表示程度稍高，用在形容词前。"}, {"text": "校", "is_correct": false, "explanation": "xiào（第四声）与 jiào 声母不同（x 与 j），意思是学校。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo（第三声）与 jiào（第四声）声调不同，意思是脚。"}, {"text": "教", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是教。"}], "explanations": {"较": "正确。“较”（jiào，第四声）表示程度稍高，用在形容词前。", "校": "xiào（第四声）与 jiào 声母不同（x 与 j），意思是学校。", "脚": "jiǎo（第三声）与 jiào（第四声）声调不同，意思是脚。", "教": "jiāo（第一声）与 jiào（第四声）声调不同，意思是教。"}, "sentence_index": null, "correct_answer": "较"}, "level_3": {"options": [{"text": "较", "is_correct": true, "explanation": "正确。“较”表示程度稍高，用在形容词“大”前，与后文“住三个人没问题”相符。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行，不能修饰形容词“大”。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，句中没有可以对比的语境。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示总括，指一个房间时不能用。"}], "explanations": {"较": "正确。“较”表示程度稍高，用在形容词“大”前，与后文“住三个人没问题”相符。", "正在": "语义：“正在”表示动作进行，不能修饰形容词“大”。", "却": "搭配：“却”表示转折，句中没有可以对比的语境。", "都": "语义：“都”表示总括，指一个房间时不能用。"}, "sentence_index": 0, "correct_answer": "较"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法较唯一，别的方法都行不通。", "explanation": "这里误用了〈较〉修饰绝对性的形容词。“较”表示程度上的相对高低，“唯一”表示绝对，不能比较程度，应去掉“较”。"}, {"text": "这家店的价格比那家较贵。", "explanation": "这里误用了“比”与“较”的叠加。“比”已经表示比较，不能再与“较”连用，应去掉“较”，说“比那家贵”或“比那家更贵”。"}, {"text": "这家店的价格较有点贵。", "explanation": "这里误用了“较”。它表示与他物相比的程度，与表示轻微程度的词叠加，语义重复，应去掉“较”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20364, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "较", "is_correct": true, "explanation": "正确。“较”（jiào，第四声）表示程度稍高，用在形容词前。"}, {"text": "笑", "is_correct": false, "explanation": "xiào（第四声）与 jiào 声母不同（x 与 j），意思是笑。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo（第三声）与 jiào（第四声）声调不同，意思是角落。"}, {"text": "交", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交给。"}], "explanations": {"较": "正确。“较”（jiào，第四声）表示程度稍高，用在形容词前。", "笑": "xiào（第四声）与 jiào 声母不同（x 与 j），意思是笑。", "角": "jiǎo（第三声）与 jiào（第四声）声调不同，意思是角落。", "交": "jiāo（第一声）与 jiào（第四声）声调不同，意思是交给。"}, "sentence_index": null, "correct_answer": "较"}, "level_3": {"options": [{"text": "较", "is_correct": true, "explanation": "正确。“较”表示程度稍高，用在形容词“好”前，与“我觉得”的评价相符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，不表示程度，与评价句不合。"}, {"text": "连", "is_correct": false, "explanation": "搭配：“连”需要与“都”或“也”呼应，句中没有这样的结构。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，不表示程度，无法修饰“好”的程度。"}], "explanations": {"较": "正确。“较”表示程度稍高，用在形容词“好”前，与“我觉得”的评价相符。", "忽然": "语义：“忽然”表示突然，不表示程度，与评价句不合。", "连": "搭配：“连”需要与“都”或“也”呼应，句中没有这样的结构。", "立刻": "语义：“立刻”表示马上，不表示程度，无法修饰“好”的程度。"}, "sentence_index": 6, "correct_answer": "较"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫较唯一，别的猫都不能比。", "explanation": "这里误用了〈较〉修饰绝对性的形容词。“较”表示程度上的相对高低，而“唯一”不能比较程度，应去掉“较”。"}, {"text": "这个房间较非常大，住两个人很舒服。", "explanation": "这里误用了〈较〉与〈非常〉叠加。两者都表示程度，不能同时修饰形容词，应去掉“较”。"}, {"text": "这件事较不应该发生。", "explanation": "这里误用了〈较〉修饰能愿动词。“较”只修饰形容词或部分动词，不修饰表示情理的能愿动词，应去掉“较”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区的房子新较，价格也合适。", "corrected_sentence": "这个小区的房子较新，价格也合适。", "error_description": "“较”要放在形容词前面，应说「较新」，不能说「新较」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试的题目较了难，大家都很紧张。", "corrected_sentence": "这次考试的题目较难，大家都很紧张。", "error_description": "“较难”是一个整体，“了”不能插在“较”和“难”之间。应说「较难」，不能说「较了难」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d296638-cb17-4ff8-a734-32b70dfda79d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
