INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人在一起。", "primary_collocate": null, "pronunciation": "qún tǐ", "ipa": "tɕʰyn˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个群体里有很多年轻人。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一个跳舞的群体。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是一个爱跑步的群体。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家组成了一个群体，一起去旅行。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个群体有二十多个人，都是学生。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我加入了一个学习中文的群体。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路口站着一个群体，大家都在等车。", "target_word": "群体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群体的人都喜欢踢足球。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个很大的群体正在广场上唱歌。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们这个群体每个星期见一次面。", "target_word": "群体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群体性", "label": "复合"}, {"form": "群體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多人聚在一起形成的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083cdca7-e95f-4d69-a9ce-e0c89f00c055') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体", "is_correct": true, "explanation": "“群体”指很多人聚在一起形成的一群人，与“这个……里有很多年轻人”相符。"}, {"text": "个体", "is_correct": false, "explanation": "语义：“个体”指单个的人，与“很多年轻人”的语境不符。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体”是人的躯体，不能装下很多年轻人。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“字体”是字的样式，不能用“这个……里”来指人群。"}], "explanations": {"群体": "“群体”指很多人聚在一起形成的一群人，与“这个……里有很多年轻人”相符。", "个体": "语义：“个体”指单个的人，与“很多年轻人”的语境不符。", "身体": "语义：“身体”是人的躯体，不能装下很多年轻人。", "字体": "搭配：“字体”是字的样式，不能用“这个……里”来指人群。"}, "sentence_index": 0, "correct_answer": "群体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园门口的那棵树是一个群体。", "explanation": "这里应该用〈单个物体〉。“群体”指很多人聚在一起，不能用来指一棵树这样的单个物体。"}, {"text": "他是我们班的一个群体。", "explanation": "这里应该用〈个人〉。“群体”指许多人聚在一起，不能指单个的人。"}, {"text": "群体同学没有来上课。", "explanation": "这里应该用〈全体〉。“全体同学”指班里所有的同学；“群体”强调由许多人组成的整体，不用来修饰“同学”这样的具体人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体", "is_correct": true, "explanation": "“群体”指聚在一起的一群人，与“路口站着……大家都在等车”相符。"}, {"text": "物体", "is_correct": false, "explanation": "语义：“物体”不会等车，与“大家都在等车”的语境矛盾。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：“雕像”是静止的艺术品，不会等车，与句中的语境不符。"}, {"text": "句子", "is_correct": false, "explanation": "语义：“句子”是语言单位，不能站在路口，与“路口站着”矛盾。"}], "explanations": {"群体": "“群体”指聚在一起的一群人，与“路口站着……大家都在等车”相符。", "物体": "语义：“物体”不会等车，与“大家都在等车”的语境矛盾。", "雕像": "语义：“雕像”是静止的艺术品，不会等车，与句中的语境不符。", "句子": "语义：“句子”是语言单位，不能站在路口，与“路口站着”矛盾。"}, "sentence_index": 6, "correct_answer": "群体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个群体是用木头做的。", "explanation": "这里应该用〈物品〉。“群体”指由许多人组成的整体，不是用材料制作的东西。"}, {"text": "这个群体的身份证号码很长。", "explanation": "这里应该用〈个人〉。“群体”指许多人组成的集合，没有自己的身份证号码。"}, {"text": "这个群体的鼻子很大。", "explanation": "这里应该用〈个人〉。“鼻子”是单个人的器官，“群体”指很多人在一起，不能说它有一个鼻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只群体在公园里跳舞。", "corrected_sentence": "一个群体在公园里跳舞。", "error_description": "错误：量词用了“只”。正确：“群体”指由人组成的整体，量词应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个群体们的成员都很热情。", "corrected_sentence": "这个群体的成员都很热情。", "error_description": "错误：“群体”后面加了“们”。正确：“群体”本身已表示集合，不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea446f59-d316-414f-b217-3d6539674177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
