INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "有，在。", "primary_collocate": null, "pronunciation": "cún zài", "ipa": "tsʰuən˧˥ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "地球上存在很多不同的生物。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题一直存在。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说那里不存在危险。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划还存在一些问题。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上不存在完全一样的两片叶子。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动物现在还存在吗？", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里存在几个错误，请改一下。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐龙很早以前就存在了。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家之间存在着很大的不同。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说学习中存在困难是正常的。", "target_word": "存在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在着", "label": "体标"}, {"form": "存在过", "label": "体标"}, {"form": "存在感", "label": "复合"}], "register": "中性", "sense_fingerprint": "存在：事物有、在，实际上有这个东西或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存在", "is_correct": true, "explanation": "正确：“地球上存在很多不同的生物”中，“存在”表示有、在，符合句意。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”后接节日、胜利等，不能说“地球上庆祝很多生物”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是发声歌唱，与地球上有哪些生物无关。"}, {"text": "跑步", "is_correct": false, "explanation": "配价：“跑步”是不及物动词，后面不能直接带宾语“很多不同的生物”。"}], "explanations": {"存在": "正确：“地球上存在很多不同的生物”中，“存在”表示有、在，符合句意。", "庆祝": "搭配：“庆祝”后接节日、胜利等，不能说“地球上庆祝很多生物”。", "唱歌": "语义：唱歌是发声歌唱，与地球上有哪些生物无关。", "跑步": "配价：“跑步”是不及物动词，后面不能直接带宾语“很多不同的生物”。"}, "sentence_index": 0, "correct_answer": "存在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班存在三十个同学。", "explanation": "这里应该用〈有〉。存在多用于事物或情况的存在，清点人数要用有，不用存在。"}, {"text": "他存在一辆新车。", "explanation": "这里应该用〈拥有〉。存在不表示某人拥有东西，说拥有车要用拥有或有。"}, {"text": "我每天存在三顿饭。", "explanation": "这里应该用〈吃〉。“存在”表示事物有、在，不表示吃东西；吃饭要用吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存在", "is_correct": true, "explanation": "正确：“书里存在几个错误”中，“存在”表示有，符合句意。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”后接节目、音乐、视频，不能接“错误”。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是把一种语言换成另一种，与书里有几个错误无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是用水加热食物，与书中的错误不相关，句子不通。"}], "explanations": {"存在": "正确：“书里存在几个错误”中，“存在”表示有，符合句意。", "播放": "搭配：“播放”后接节目、音乐、视频，不能接“错误”。", "翻译": "语义：翻译是把一种语言换成另一种，与书里有几个错误无关。", "煮": "语义：煮是用水加热食物，与书中的错误不相关，句子不通。"}, "sentence_index": 6, "correct_answer": "存在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上存在了我的老师。", "explanation": "这里应该用〈遇到〉。存在指事物有、在，不表示与人相遇，路上碰见老师要用遇到。"}, {"text": "我今天存在了一封信。", "explanation": "这里应该用〈收到〉。存在不表示接受物品，收信要用收到。"}, {"text": "我昨天存在了一台电脑。", "explanation": "这里应该用〈买〉。存在不表示购买，买东西要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
