INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情可能发生的可能性大小。", "primary_collocate": null, "pronunciation": "gài lǜ", "ipa": "kai˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "今天出太阳的概率很大，我们去爬山吧。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到的概率不高，因为他住得很近。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪的概率几乎为零，因为现在是夏天。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店明天开门的概率很小，老板出国了。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想提高成功的概率，就要多练习。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么冷，感冒的概率变大了。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前他很累，赢的概率不大。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上不堵车，早到的概率很高。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事发生的概率虽然低，但我们要小心。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天复习，考好的概率当然更高。", "target_word": "概率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日常说法中，某件事发生的可能性有多大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概率", "is_correct": true, "explanation": "正确：“出太阳的概率很大”说的是出太阳的可能性高，与“我们去爬山吧”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有大小的程度，“出太阳的颜色很大”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，不能用来描述出太阳的情况。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体型特征，“出太阳的身材很大”不成立。"}], "explanations": {"概率": "正确：“出太阳的概率很大”说的是出太阳的可能性高，与“我们去爬山吧”相符。", "颜色": "语义：颜色没有大小的程度，“出太阳的颜色很大”说不通。", "身高": "体貌：身高是人的身体特征，不能用来描述出太阳的情况。", "身材": "体貌：身材是人的体型特征，“出太阳的身材很大”不成立。"}, "sentence_index": 0, "correct_answer": "概率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于得到了一次难得的概率，可以去国外读书。", "explanation": "这里应该用〈机会〉。概率说的是可能性的大小，不说“得到”；获得有利条件要用机会。"}, {"text": "我每天都去跑步，一周的概率有七次。", "explanation": "这里应该用〈次数〉。概率是0到1之间的数值，不能用“有七次”来表示次数。"}, {"text": "来参加活动的概率有四十人。", "explanation": "这里应该用〈人数〉。概率不能用来表示人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概率", "is_correct": true, "explanation": "正确：“赢的概率不大”说的是赢的可能性低，与“比赛前他很累”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，与比赛输赢的可能性无关。"}, {"text": "语气", "is_correct": false, "explanation": "语义：语气不能用“赢的……不大”来说明比赛结果，句意不通。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度与比赛的输赢无关，“赢的长度不大”不成立。"}], "explanations": {"概率": "正确：“赢的概率不大”说的是赢的可能性低，与“比赛前他很累”的语境相符。", "体重": "体貌：体重是人的身体特征，与比赛输赢的可能性无关。", "语气": "语义：语气不能用“赢的……不大”来说明比赛结果，句意不通。", "长度": "语义：长度与比赛的输赢无关，“赢的长度不大”不成立。"}, "sentence_index": 6, "correct_answer": "概率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的概率很快。", "explanation": "这里应该用〈速度〉。概率表示事情发生的可能性大小，不能用来形容运动的快慢。"}, {"text": "这座水池的概率很深。", "explanation": "这里应该用〈深度〉。概率不能用来形容水或物体的深浅。"}, {"text": "这条路的概率很陡。", "explanation": "这里应该用〈坡度〉。概率不能用来形容道路的倾斜程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天准时到的概率很多。", "corrected_sentence": "他明天准时到的概率很大。", "error_description": "错误：“很多”；正确：“很大”。概率的程度只能用“大、小、高、低”等来形容，不能说“很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多吃蔬菜能降低生病地概率。", "corrected_sentence": "多吃蔬菜能降低生病的概率。", "error_description": "错误：“生病地概率”；正确：“生病的概率”。修饰名词“概率”要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
