INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "亲缘就是家人之间的亲戚关系。", "primary_collocate": null, "pronunciation": "qīn yuán", "ipa": "tɕʰin˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我和表哥的亲缘很近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "wǒ hé biǎo gē de qīn yuán hěn jìn.", "sentence_source": "generated"}, {"text": "他们是表兄妹，亲缘很近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "tā men shì biǎo xiōng mèi, qīn yuán hěn jìn.", "sentence_source": "generated"}, {"text": "叔叔和我的亲缘很近。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "shū shu hé wǒ de qīn yuán hěn jìn.", "sentence_source": "generated"}, {"text": "过年时，亲缘近的人都会回家。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的亲缘很近，经常一起吃饭。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "wǒ men jiā de qīn yuán hěn jìn, jīng cháng yì qǐ chī fàn.", "sentence_source": "generated"}, {"text": "爷爷说家人之间的亲缘最要紧。", "target_word": "亲缘", "complexity_tier": "T3", "furigana": "yé ye shuō jiā rén zhī jiān de qīn yuán zuì yào jǐn.", "sentence_source": "generated"}, {"text": "他们没有亲缘，却像一家人。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和我有亲缘，是我的姨妈。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图画出了我们家的亲缘。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "亲缘近的亲戚常常住在一起。", "target_word": "亲缘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲缘关系", "label": "复合"}, {"form": "親緣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家人之间的亲戚关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案，意思是家人之间的亲戚关系。"}, {"text": "情缘", "is_correct": false, "explanation": "qíng yuán 与 qīn yuán 的韵母和声调都不同（ing 与 in，第二声与第一声），意思是感情上的缘分。"}, {"text": "金元", "is_correct": false, "explanation": "jīn yuán 与 qīn yuán 的声母不同（j 与 q），声调相同，意思是金子与货币单位。"}, {"text": "新元", "is_correct": false, "explanation": "xīn yuán 与 qīn yuán 的声母不同（x 与 q），声调相同，意思是新加坡等地的货币单位。"}], "explanations": {"亲缘": "正确答案，意思是家人之间的亲戚关系。", "情缘": "qíng yuán 与 qīn yuán 的韵母和声调都不同（ing 与 in，第二声与第一声），意思是感情上的缘分。", "金元": "jīn yuán 与 qīn yuán 的声母不同（j 与 q），声调相同，意思是金子与货币单位。", "新元": "xīn yuán 与 qīn yuán 的声母不同（x 与 q），声调相同，意思是新加坡等地的货币单位。"}, "sentence_index": null, "correct_answer": "亲缘"}, "level_3": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案。“我和表哥的亲缘很近”指两人的亲戚关系近，与句意相符。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，与人与人之间的亲属关系无关。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能说明亲属关系的远近。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用于商品，不说“我和表哥的价格很近”。"}], "explanations": {"亲缘": "正确答案。“我和表哥的亲缘很近”指两人的亲戚关系近，与句意相符。", "音量": "语义：“音量”指声音的大小，与人与人之间的亲属关系无关。", "脚步": "语义：“脚步”指走路的动作，不能说明亲属关系的远近。", "价格": "搭配：“价格”用于商品，不说“我和表哥的价格很近”。"}, "sentence_index": 0, "correct_answer": "亲缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和小狗的亲缘很近。", "explanation": "这里应该用〈感情〉。亲缘指亲属关系，小狗不是亲属，不能说“亲缘很近”；人与宠物之间是感情，不是亲缘。"}, {"text": "过年的时候，我和亲缘一起包饺子。", "explanation": "这里应该用〈亲戚〉。亲缘指亲戚之间的关系，不指人，不能说“和亲缘一起包饺子”。"}, {"text": "我和他只是点头之交，彼此的亲缘却很深。", "explanation": "这里应该用〈友情〉。亲缘指家人之间的亲戚关系，点头之交的人之间没有血缘或婚姻，不能说“彼此的亲缘很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲缘", "is_correct": true, "explanation": "正确答案。“没有亲缘”指没有亲属关系，与“却像一家人”形成对照。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”用于土地或空间，不与“没有”搭配表示人际关系。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与人际关系无关，“没有颜色”不能说明家人关系。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体外形，不能说明人与人之间的关系。"}], "explanations": {"亲缘": "正确答案。“没有亲缘”指没有亲属关系，与“却像一家人”形成对照。", "面积": "搭配：“面积”用于土地或空间，不与“没有”搭配表示人际关系。", "颜色": "语义：“颜色”与人际关系无关，“没有颜色”不能说明家人关系。", "形状": "语义：“形状”指物体外形，不能说明人与人之间的关系。"}, "sentence_index": 6, "correct_answer": "亲缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的亲缘很温和。", "explanation": "这里应该用〈性格〉。亲缘指亲属关系，不用来形容一个人的性格。"}, {"text": "我和他是同班同学，亲缘很近。", "explanation": "这里应该用〈交情〉。亲缘指家人之间的亲戚关系，同班同学之间没有血缘或婚姻，不能说“亲缘很近”。"}, {"text": "这两家公司的亲缘很好，生意做得很大。", "explanation": "这里应该用〈关系〉。亲缘指家人之间的亲戚关系，两家公司之间的联系要说“关系”，不能说“亲缘很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和堂弟的亲缘很高。", "corrected_sentence": "我和堂弟的亲缘很近。", "error_description": "搭配错误：“亲缘”的程度用“近”或“远”来说，不能用“高”。应说“亲缘很近”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姑姑和我们家的亲缘很大。", "corrected_sentence": "姑姑和我们家的亲缘很远。", "error_description": "搭配错误：“亲缘”的程度用“近”或“远”来说，不能用“大”。应说“亲缘很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
