INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灵长类是动物的一类，包括猴子、猿和人。", "primary_collocate": null, "pronunciation": "líng zhǎng lèi", "ipa": "liŋ˧˥ ʈʂaŋ˨˩˦ lei˥˩", "syllable_count": 3, "sentences": [{"text": "猴子和猿都是灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的灵长类是猩猩。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类动物很聪明。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类的脸有点像人。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了各种灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类喜欢吃水果和叶子。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们哪种动物是灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在电视上看到了灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灵长类的妈妈会抱着孩子。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里住着一群灵长类。", "target_word": "灵长类", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "灵长类动物", "label": "复合"}, {"form": "灵長類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动物的一类，包括猴子、猿和人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75429260-be64-43e8-af1c-c5714e130df6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵长类", "is_correct": true, "explanation": "猴子和猿都属于灵长类，句子成立。"}, {"text": "鸟类", "is_correct": false, "explanation": "语义：猴子和猿不是鸟类，“都是鸟类”与事实及句意相反。"}, {"text": "鱼类", "is_correct": false, "explanation": "语义：猴子和猿不是鱼类，“都是鱼类”与事实相反。"}, {"text": "昆虫", "is_correct": false, "explanation": "体貌：昆虫有六条腿、身体分为三部分，猴子和猿并不具备这些特征。"}], "explanations": {"灵长类": "猴子和猿都属于灵长类，句子成立。", "鸟类": "语义：猴子和猿不是鸟类，“都是鸟类”与事实及句意相反。", "鱼类": "语义：猴子和猿不是鱼类，“都是鱼类”与事实相反。", "昆虫": "体貌：昆虫有六条腿、身体分为三部分，猴子和猿并不具备这些特征。"}, "sentence_index": 0, "correct_answer": "灵长类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在动物园看到了一条灵长类。", "explanation": "这里的量词不对。“条”不能用来数“灵长类”这一类别；灵长类是动物的一类，应说“一种灵长类”。"}, {"text": "图书馆里有一部灵长类，我很想看。", "explanation": "这里的量词不对。“部”用于作品，不能用来数“灵长类”；灵长类是动物的一类，应说“一种灵长类”。"}, {"text": "林子里跑出来一片灵长类。", "explanation": "这里的量词不对。“片”用于薄而平的东西，不能用来数“灵长类”；灵长类是动物的一类，应说“一种灵长类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵长类", "is_correct": true, "explanation": "灵长类指猴子、猿和人等，是动物的一类，符合“哪种动物是……”的问句。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是动物，“哪种动物是植物”自相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不属于动物。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”不是动物，与“哪种动物是……”的问句搭配不通。"}], "explanations": {"灵长类": "灵长类指猴子、猿和人等，是动物的一类，符合“哪种动物是……”的问句。", "植物": "语义：植物不是动物，“哪种动物是植物”自相矛盾。", "石头": "语义：石头是无生命的物体，不属于动物。", "汽车": "搭配：“汽车”不是动物，与“哪种动物是……”的问句搭配不通。"}, "sentence_index": 6, "correct_answer": "灵长类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都喝一杯灵长类。", "explanation": "这里应该用〈牛奶〉。“灵长类”是动物的类别，不能当作饮品。"}, {"text": "妈妈在花园里种了一排灵长类。", "explanation": "这里应该用〈树〉。“灵长类”是动物的类别，不能当作植物种下。"}, {"text": "我用一根灵长类量了量桌子的长度。", "explanation": "这里应该用〈尺子〉。“灵长类”是动物的类别，不能当作测量工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长臂猿也是一种灵长类地动物。", "corrected_sentence": "长臂猿也是一种灵长类动物。", "error_description": "多余的“地”：“灵长类动物”是名词，中间不能插入“地”。正确说法是“长臂猿也是一种灵长类动物。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深山里住着一群灵长类们，它们很怕人。", "corrected_sentence": "深山里住着一群灵长类，它们很怕人。", "error_description": "错误：“灵长类们”；正确：“灵长类”。“灵长类”是类别名词，不能加“们”表示复数，“们”一般用于指人的复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '579b8cea-cd24-4833-b2df-7e0d4b2058ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
