INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20392, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变高。", "primary_collocate": null, "pronunciation": "zēng gāo", "ipa": "tsəŋ˥ kau˥", "syllable_count": 2, "sentences": [{"text": "这张椅子太矮，请你在下面垫书把它增高。", "target_word": "增高", "complexity_tier": "T3", "furigana": "zēng gāo", "sentence_source": "generated"}, {"text": "他在架子下面加了块木板，架子增高了一点。", "target_word": "增高", "complexity_tier": "T3", "furigana": "zēng gāo", "sentence_source": "generated"}, {"text": "工人们正在增高大楼的围栏。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想增高这个书架，放更多的书。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了够到窗户，他把书架的架腿加长，让它增高了。", "target_word": "增高", "complexity_tier": "T3", "furigana": "zēng gāo", "sentence_source": "generated"}, {"text": "爸爸把床腿加长，增高了整张床。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐得太低，我们用垫子把椅子增高就行。", "target_word": "增高", "complexity_tier": "T3", "furigana": "zēng gāo", "sentence_source": "generated"}, {"text": "学校要增高操场边的墙。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把桌子增高以后，他站着写字更舒服。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵矮墙需要增高半米才安全。", "target_word": "增高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增高了", "label": "体标（了）"}, {"form": "增高过", "label": "体标（过）"}, {"form": "增高鞋", "label": "复合词"}, {"form": "增高垫", "label": "复合词"}], "register": "中性", "sense_fingerprint": "通过垫、加等办法让东西的位置或高度变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增高", "is_correct": true, "explanation": "正确：“垫书把它增高”，使椅子变高，符合句意。"}, {"text": "降低", "is_correct": false, "explanation": "语义：降低与“椅子太矮”和“垫书”的做法方向相反。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”只用于人或植物，不能说椅子长高。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除与“在下面垫书”的做法不合，句意矛盾。"}], "explanations": {"增高": "正确：“垫书把它增高”，使椅子变高，符合句意。", "降低": "语义：降低与“椅子太矮”和“垫书”的做法方向相反。", "长高": "搭配：“长高”只用于人或植物，不能说椅子长高。", "拆除": "语义：拆除与“在下面垫书”的做法不合，句意矛盾。"}, "sentence_index": 0, "correct_answer": "增高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的产品质量增高了，客户都很满意。", "explanation": "这里应该用〈提高〉。增高指物体变高，产品质量要用提高。"}, {"text": "这家超市的顾客增高了很多。", "explanation": "这里应该用〈增加〉。增高指高度上升，顾客人数的增多要用增加。"}, {"text": "这个箱子的容量增高了。", "explanation": "这里应该用〈增大〉。容量变大要用增大，增高只用于物体的高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增高", "is_correct": true, "explanation": "正确：“用垫子把椅子增高”正好解决“孩子坐得太低”的问题。"}, {"text": "缩短", "is_correct": false, "explanation": "语义：缩短椅子的高度与“坐得太低”的问题相反，句意矛盾。"}, {"text": "压低", "is_correct": false, "explanation": "语义：压低椅子会让孩子更低，与“用垫子”的做法相矛盾。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：“赠送”需要受赠对象，句中缺少，且与句意不相符。"}], "explanations": {"增高": "正确：“用垫子把椅子增高”正好解决“孩子坐得太低”的问题。", "缩短": "语义：缩短椅子的高度与“坐得太低”的问题相反，句意矛盾。", "压低": "语义：压低椅子会让孩子更低，与“用垫子”的做法相矛盾。", "赠送": "配价：“赠送”需要受赠对象，句中缺少，且与句意不相符。"}, "sentence_index": 6, "correct_answer": "增高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了够到树枝，我们把绳子增高了一米。", "explanation": "这里应该用〈加长〉。增高指使东西变高，绳子变长要用加长，不能说增高。"}, {"text": "这面墙太薄了，工人想把它增高。", "explanation": "这里应该用〈加厚〉。墙太薄要增加厚度，应说加厚，增高只表示变高。"}, {"text": "这条路太窄了，工人想把它增高。", "explanation": "这里应该用〈拓宽〉。路太窄要使路面变宽，应说拓宽，增高只表示变高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个书架比以前增高得一点。", "corrected_sentence": "这个书架比以前增高了一点。", "error_description": "错误：“增高得一点”；正确：“增高了一点”。表示已经发生的变化要用助词“了”，“得”不能用在数量补语前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪堆增高地很快。", "corrected_sentence": "雪堆增高得很快。", "error_description": "错误：“增高地”；正确：“增高得”。“增高”后面的程度补语要用“得”连接，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
