INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20394, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把两个东西接在一起。", "primary_collocate": null, "pronunciation": "lián jié", "ipa": "ljɛn˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "工人用铁链把两根管子联结起来。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥把两个小岛联结在一起。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子联结了两只箱子。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先联结两根电线。", "target_word": "联结", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "铁路把北方和南方联结起来。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两个零件联结好。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路联结了村子和城里。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友用积木联结成一辆长火车。", "target_word": "联结", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把两段木板联结得很结实。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一座长桥联结着河的两岸。", "target_word": "联结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "联结了", "label": "体标"}, {"form": "联结着", "label": "体标"}, {"form": "联结起来", "label": "复合"}, {"form": "聯結", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把两个具体的东西接合在一起，使相连", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20394, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结（lián jié）：把两个东西接在一起，使相连。"}, {"text": "廉价", "is_correct": false, "explanation": "廉价（lián jià）：第二音节韵母 jià 与 jié 不同（ia 与 ie），意思是价格低。"}, {"text": "拦截", "is_correct": false, "explanation": "拦截（lán jié）：第一音节 lán 少了介音 i，与 lián 不同，意思是阻挡。"}, {"text": "两截", "is_correct": false, "explanation": "两截（liǎng jié）：第一音节韵尾 ng 与 n 不同，声调也不同，意思是分成两段。"}], "explanations": {"联结": "联结（lián jié）：把两个东西接在一起，使相连。", "廉价": "廉价（lián jià）：第二音节韵母 jià 与 jié 不同（ia 与 ie），意思是价格低。", "拦截": "拦截（lán jié）：第一音节 lán 少了介音 i，与 lián 不同，意思是阻挡。", "两截": "两截（liǎng jié）：第一音节韵尾 ng 与 n 不同，声调也不同，意思是分成两段。"}, "sentence_index": null, "correct_answer": "联结"}, "level_3": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结：把两根管子接在一起，与“用铁链把……起来”的语境一致。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹饪，与用铁链连接管子的动作不符。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”与“联结”意思相反，句中要的是接上，而不是分开。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”指擦得发亮，与“用铁链把两根管子”的动作搭配不当。"}], "explanations": {"联结": "联结：把两根管子接在一起，与“用铁链把……起来”的语境一致。", "煮": "语义：“煮”指加热烹饪，与用铁链连接管子的动作不符。", "拆开": "语义：“拆开”与“联结”意思相反，句中要的是接上，而不是分开。", "擦亮": "搭配：“擦亮”指擦得发亮，与“用铁链把两根管子”的动作搭配不当。"}, "sentence_index": 0, "correct_answer": "联结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都联结一杯牛奶。", "explanation": "这里应该用〈喝〉。联结表示把两个东西接在一起，喝牛奶要用喝。"}, {"text": "妈妈把桌子联结干净了。", "explanation": "这里应该用〈擦〉。联结表示把两个东西接在一起，把桌面弄干净要用擦。"}, {"text": "老师在课堂上联结了一个有趣的故事。", "explanation": "这里应该用〈讲〉。联结表示把两个东西接在一起，讲故事要用讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联结", "is_correct": true, "explanation": "联结：指道路把两地连接起来，与“这条路……村子和城里”的语境一致。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：路不能“烧毁”村子和城里，与路连接两地的作用不符。"}, {"text": "淹没", "is_correct": false, "explanation": "语义：“淹没”指被水覆盖，与路连接两地的作用不符。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”需要有生命的主体，不能用于路和村子。"}], "explanations": {"联结": "联结：指道路把两地连接起来，与“这条路……村子和城里”的语境一致。", "烧毁": "语义：路不能“烧毁”村子和城里，与路连接两地的作用不符。", "淹没": "语义：“淹没”指被水覆盖，与路连接两地的作用不符。", "拥抱": "搭配：“拥抱”需要有生命的主体，不能用于路和村子。"}, "sentence_index": 6, "correct_answer": "联结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了，就去联结一碗饭。", "explanation": "这里应该用〈吃〉。联结表示把两个东西接在一起，吃饭要用吃。"}, {"text": "他很累，就联结了一会儿觉。", "explanation": "这里应该用〈睡〉。联结表示把两个东西接在一起，睡觉要用睡。"}, {"text": "妈妈在厨房里联结了一碗粥。", "explanation": "这里应该用〈熬〉。联结表示把两个东西接在一起，煮粥要用熬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把两块铁板联结很牢。", "corrected_sentence": "工人把两块铁板联结得很牢。", "error_description": "程度补语前要用“得”。漏掉“得”，应为“联结得很牢”，原句不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这两根电线联结很好。", "corrected_sentence": "请把这两根电线联结得很好。", "error_description": "程度补语前要用“得”。漏掉“得”，“联结很好”应为“联结得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
