INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事在一定时间内发生的次数。", "primary_collocate": null, "pronunciation": "pín lǜ", "ipa": "pʰin˧˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "他去健身房的频率很高。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方地震的频率不高。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要减少犯错的频率。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用手机的频率太高了。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我头疼的频率。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打电话给妈妈的频率是每天一次。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上出事故的频率越来越低。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开会的频率从每周一次变成每月一次。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动的频率比时间长短更重要。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看电影的频率比我高得多。", "target_word": "频率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高频率", "label": "复合"}, {"form": "低频率", "label": "复合"}], "register": "中性", "sense_fingerprint": "单位时间内事情发生的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频率", "is_correct": true, "explanation": "正确：「频率」指单位时间内发生的次数，「很高」说的是次数多。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：「距离」说远近，不说高低，「距离很高」不成立。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「时间」说长短，不说高低，「时间很高」不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体的重量，与去健身房的次数无关。"}], "explanations": {"频率": "正确：「频率」指单位时间内发生的次数，「很高」说的是次数多。", "距离": "搭配：「距离」说远近，不说高低，「距离很高」不成立。", "时间": "搭配：「时间」说长短，不说高低，「时间很高」不成立。", "体重": "语义：「体重」指身体的重量，与去健身房的次数无关。"}, "sentence_index": 0, "correct_answer": "频率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校的频率很远。", "explanation": "这里应该用〈距离〉。频率指单位时间内发生的次数，说空间的远近要用距离。"}, {"text": "这种金属的频率很高。", "explanation": "这里应该用〈密度〉。频率不能描述物质的疏密，说金属的疏密要用密度。"}, {"text": "这条河的频率很快。", "explanation": "这里应该用〈流速〉。频率指次数，说水流的快慢要用流速。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频率", "is_correct": true, "explanation": "正确：「频率」可以“越来越低”，表示事故发生得越来越少。"}, {"text": "温度", "is_correct": false, "explanation": "语义：「温度」指冷热程度，与路上的事故次数无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与事故的发生次数无关，也不能说“越来越低”。"}, {"text": "宽度", "is_correct": false, "explanation": "搭配：「宽度」说宽窄，不说高低，“宽度越来越低”不搭。"}], "explanations": {"频率": "正确：「频率」可以“越来越低”，表示事故发生得越来越少。", "温度": "语义：「温度」指冷热程度，与路上的事故次数无关。", "颜色": "语义：「颜色」与事故的发生次数无关，也不能说“越来越低”。", "宽度": "搭配：「宽度」说宽窄，不说高低，“宽度越来越低”不搭。"}, "sentence_index": 6, "correct_answer": "频率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的频率比我大。", "explanation": "这里应该用〈体积〉。频率指次数，说箱子的大小要用体积。"}, {"text": "这间屋子的频率比那间高。", "explanation": "这里应该用〈温度〉。频率指次数，说房间的冷热要用温度。"}, {"text": "这条河的频率比那条长。", "explanation": "这里应该用〈长度〉。频率指次数，说河的长短要用长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天用电脑频率很高。", "corrected_sentence": "我每天用电脑的频率很高。", "error_description": "错误在“频率”前漏了定语标记“的”。正确说法是“用电脑的频率”，“的”把前面的动词短语连到“频率”上；漏掉后句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子玩手机的频率比他父母高多。", "corrected_sentence": "这个孩子玩手机的频率比他父母高得多。", "error_description": "错误在“高”后漏了补语标记“得”。正确是“高得多”，表示差距大；“高多”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
