INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人知道该怎么做。", "primary_collocate": null, "pronunciation": "tí shì", "ipa": "tʰi˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈提示我出门前要关好窗。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，老师不能提示学生答案。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员忘词时，旁边的人小声提示他。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮着，提示车辆停下来。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直提示我小心，别摔倒。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练提示队员，比赛时要多传球。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闹钟响了，提示我该起床了。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员提示我，进门前要先登记。", "target_word": "提示", "complexity_tier": "T3", "furigana": "gōng zuò rén yuán tí shì wǒ, jìn mén qián yào xiān dēng jì.", "sentence_source": "generated"}, {"text": "请你提示一下新同事怎么用机器。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路牌提示司机前面要慢行。", "target_word": "提示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提示了", "label": "体标（了）"}, {"form": "提示过", "label": "体标（过）"}, {"form": "提示着", "label": "体标（着）"}, {"form": "提示音", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用话、动作或信号让别人知道下一步该怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是让对方知道该做什么，妈妈叮嘱出门前关窗，语境相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是表扬，与“出门前要关好窗”的叮嘱不合。"}, {"text": "回答", "is_correct": false, "explanation": "配价：“回答”的宾语应是问题，不能接叙述性的注意事项。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讽刺，与善意的叮嘱相矛盾。"}], "explanations": {"提示": "正确：“提示”是让对方知道该做什么，妈妈叮嘱出门前关窗，语境相符。", "夸奖": "语义：“夸奖”是表扬，与“出门前要关好窗”的叮嘱不合。", "回答": "配价：“回答”的宾语应是问题，不能接叙述性的注意事项。", "嘲笑": "语义：“嘲笑”带有讽刺，与善意的叮嘱相矛盾。"}, "sentence_index": 0, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常提示你的帮助。", "explanation": "这里应该用〈感谢〉。提示是让对方知道该做什么，不能用来表达对别人帮助的感激。"}, {"text": "经理提示我的请假已经通过了。", "explanation": "这里应该用〈批准〉。提示只是让人知道该做什么，不能表示同意请假。"}, {"text": "她提示我考上了大学。", "explanation": "这里应该用〈告诉〉。提示只用于让对方知道该做什么或注意什么，告知考上大学这类已发生的事要用〈告诉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示", "is_correct": true, "explanation": "正确：“提示”是让人知道该做什么，闹钟提醒起床，语境相符。"}, {"text": "推荐", "is_correct": false, "explanation": "语义：“推荐”是介绍好的东西，闹钟不能“推荐”起床。"}, {"text": "询问", "is_correct": false, "explanation": "配价：“询问”的内容应是问题，不能接“该起床了”这样的陈述。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”是拦住某个行为，与“该起床了”的提醒意思相反。"}], "explanations": {"提示": "正确：“提示”是让人知道该做什么，闹钟提醒起床，语境相符。", "推荐": "语义：“推荐”是介绍好的东西，闹钟不能“推荐”起床。", "询问": "配价：“询问”的内容应是问题，不能接“该起床了”这样的陈述。", "阻止": "语义：“阻止”是拦住某个行为，与“该起床了”的提醒意思相反。"}, "sentence_index": 6, "correct_answer": "提示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提示自己明天要早起。", "explanation": "这里应该用〈提醒〉。提示多用于对别人说明该怎么做；对自己说要早起，一般说〈提醒〉。"}, {"text": "老师提示我的字写得很漂亮。", "explanation": "这里应该用〈夸奖〉。提示是让对方知道该做什么或注意什么，不能用来称赞别人的字写得好。"}, {"text": "裁判提示了比赛的冠军是他。", "explanation": "这里应该用〈宣布〉。提示只是让人知道该做什么，不能用来正式宣布比赛结果，宣布冠军要用〈宣布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈了提示我带伞。", "corrected_sentence": "妈妈提示我带伞。", "error_description": "错误：“了”放在了动词“提示”前面。“了”只能紧跟动词之后，本句不需要“了”，正确写作“妈妈提示我带伞。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师提示很清楚。", "corrected_sentence": "老师提示得很清楚。", "error_description": "错误：补语前缺少结构助词“得”。正确：“提示得很清楚”，“得”紧跟动词，后接补语“很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "融化指固体变为液体，与“硬化”没有反义关系。"}, {"text": "腐烂", "is_correct": false, "explanation": "腐烂指有机物分解变质，与“硬化”没有反义关系。"}, {"text": "发酵", "is_correct": false, "explanation": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "融化": "融化指固体变为液体，与“硬化”没有反义关系。", "腐烂": "腐烂指有机物分解变质，与“硬化”没有反义关系。", "发酵": "发酵指微生物作用使物质发生变化，与“硬化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软化", "is_correct": true, "explanation": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。"}, {"text": "溶解", "is_correct": false, "explanation": "溶解指物质在液体中化开，与“硬化”没有反义关系。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结指液体变为固体，与“硬化”没有反义关系。"}, {"text": "生锈", "is_correct": false, "explanation": "生锈指金属被氧化，与“硬化”没有反义关系。"}], "correct_answer": "软化", "explanations": {"软化": "正确：软化指由硬变软，与“硬化”（由软变硬）互为反义。", "溶解": "溶解指物质在液体中化开，与“硬化”没有反义关系。", "冻结": "冻结指液体变为固体，与“硬化”没有反义关系。", "生锈": "生锈指金属被氧化，与“硬化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变硬了。", "primary_collocate": null, "pronunciation": "yìng huà", "ipa": "iŋ˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "面包放久了，表面会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块湿泥巴放在太阳下晒了一天，就硬化了。", "target_word": "硬化", "complexity_tier": "T3", "furigana": "yìng huà", "sentence_source": "generated"}, {"text": "胶水干了以后，很快就硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮鞋太久没穿，皮已经硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太冷，刚铺的路面要很久才能硬化。", "target_word": "硬化", "complexity_tier": "T3", "furigana": "yìng huà", "sentence_source": "generated"}, {"text": "水泥倒进去以后，会慢慢硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖浆冷了以后会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡烛油滴在桌子上，很快就硬化了。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团不盖起来，表面就会硬化。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种陶泥晒干后会硬化，可以做杯子。", "target_word": "硬化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬化了", "label": "体标"}, {"form": "硬化过", "label": "体标"}, {"form": "硬化症", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西由软变硬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cf24f25-f642-436b-8f52-c0f1aed54812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：放久的面包表面变硬，是由软变硬，符合“表面会硬化”。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体变为液体，放久的面包不会融化。"}, {"text": "汽化", "is_correct": false, "explanation": "语域：“汽化”是科技术语，描述液体变气体，日常语境中不用于面包。"}, {"text": "软化", "is_correct": false, "explanation": "语义：放久的面包会变硬、变干，不会变软，与句意相反。"}], "explanations": {"硬化": "正确：放久的面包表面变硬，是由软变硬，符合“表面会硬化”。", "融化": "语义：融化指固体变为液体，放久的面包不会融化。", "汽化": "语域：“汽化”是科技术语，描述液体变气体，日常语境中不用于面包。", "软化": "语义：放久的面包会变硬、变干，不会变软，与句意相反。"}, "sentence_index": 0, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "铁钉放在潮湿的地方，很快就硬化了。", "explanation": "这里应该用〈生锈〉。铁钉受潮氧化要说生锈，硬化指东西由软变硬。"}, {"text": "雪放在太阳下会硬化。", "explanation": "这里应该用〈融化〉。雪在阳光下变成水要说融化，硬化说的是变硬。"}, {"text": "气球打得太满，会硬化。", "explanation": "这里应该用〈破裂〉。气球打得太满会爆开，应说破裂，硬化不能描述这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬化", "is_correct": true, "explanation": "正确：糖浆冷了以后会变硬，是由软变硬的过程，符合“会硬化”。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾需要加热，糖浆冷了不会沸腾，与句中“冷了”矛盾。"}, {"text": "发热", "is_correct": false, "explanation": "语义：发热指产生热量，糖浆变冷后不会发热，与句意不合。"}, {"text": "加热", "is_correct": false, "explanation": "配价：“加热”是及物动词，要带受事（如“加热糖浆”），不能不带对象自行发生。"}], "explanations": {"硬化": "正确：糖浆冷了以后会变硬，是由软变硬的过程，符合“会硬化”。", "沸腾": "语义：沸腾需要加热，糖浆冷了不会沸腾，与句中“冷了”矛盾。", "发热": "语义：发热指产生热量，糖浆变冷后不会发热，与句意不合。", "加热": "配价：“加热”是及物动词，要带受事（如“加热糖浆”），不能不带对象自行发生。"}, "sentence_index": 6, "correct_answer": "硬化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饼干放在潮湿的地方，很快就硬化了。", "explanation": "这里应该用〈变软〉。饼干受潮会变软，硬化说的是由软变硬，两者方向相反。"}, {"text": "糖放进热水里，会硬化。", "explanation": "这里应该用〈溶解〉。糖遇水化开要说溶解，硬化说的是由软变硬。"}, {"text": "木头放进火里，会硬化。", "explanation": "这里应该用〈燃烧〉。木头放进火里要说燃烧，硬化不能描述这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块泥巴晒干后，硬化的很快。", "corrected_sentence": "这块泥巴晒干后，硬化得很快。", "error_description": "“硬化”作动词，后面的补语要用“得”引出，写成“的”是错误，“的”不能引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块泥巴很快硬化症了。", "corrected_sentence": "这块泥巴很快硬化了。", "error_description": "“硬化症”是疾病名称，是名词；这里“硬化”应作动词，表示东西由软变硬，不能加“症”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '558c092c-fb0e-44d4-81a8-561b89a99cec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
