INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指一件事一次又一次地反复发生，次数很多。", "primary_collocate": null, "pronunciation": "pín fán", "ipa": "/pʰin˧˥ fan˧˥/", "syllable_count": 2, "sentences": [{"text": "他最近出差很频繁，常常不在家。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里最近地震很频繁，大家都很害怕。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的来往越来越频繁。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他频繁地换工作，一直没有稳定下来。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机用得太频繁，电池坏得快。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王频繁地给我打电话。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近事故发生得很频繁，警察一直很忙。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司这个月开会很频繁，大家都很累。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家联系得很频繁。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月下雨很频繁，衣服总是干不了。", "target_word": "频繁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "频繁地", "label": "状语形式（+地）"}], "register": "中性", "sense_fingerprint": "事情一次接一次地反复发生，次数很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频繁", "is_correct": true, "explanation": "正确：「频繁」指次数多，与「出差很……，常常不在家」相合。"}, {"text": "罕见", "is_correct": false, "explanation": "语义：「罕见」指很少见，与「常常不在家」矛盾。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：「稀少」指次数少，与「常常不在家」矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "语义：「安静」描述状态，不能用来形容出差。"}], "explanations": {"频繁": "正确：「频繁」指次数多，与「出差很……，常常不在家」相合。", "罕见": "语义：「罕见」指很少见，与「常常不在家」矛盾。", "稀少": "语义：「稀少」指次数少，与「常常不在家」矛盾。", "安静": "语义：「安静」描述状态，不能用来形容出差。"}, "sentence_index": 0, "correct_answer": "频繁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他频繁地签了一份合同。", "explanation": "这里应该用〈一次〉。「频繁」指一次次地反复发生，只发生一次的事要用「一次」，不能用「频繁」。"}, {"text": "我们的友谊很频繁，一直到现在。", "explanation": "这里应该用〈长久〉。「频繁」说次数，不说友谊持续的时间。"}, {"text": "他买了频繁的书。", "explanation": "这里应该用〈大量〉。「频繁」形容次数，不修饰书这类物体的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频繁", "is_correct": true, "explanation": "正确：「频繁」指一次接一次地发生，与「事故发生得很……，警察一直很忙」相合。"}, {"text": "清闲", "is_correct": false, "explanation": "语义：「清闲」说人或时间的空闲，不说事故的发生，且与「警察很忙」矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：「漂亮」评价外观，不能用来形容事故的发生。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：「整齐」多用于排列，不说事故发生得整齐。"}], "explanations": {"频繁": "正确：「频繁」指一次接一次地发生，与「事故发生得很……，警察一直很忙」相合。", "清闲": "语义：「清闲」说人或时间的空闲，不说事故的发生，且与「警察很忙」矛盾。", "漂亮": "语义：「漂亮」评价外观，不能用来形容事故的发生。", "整齐": "搭配：「整齐」多用于排列，不说事故发生得整齐。"}, "sentence_index": 6, "correct_answer": "频繁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他频繁工作了十个小时，很累。", "explanation": "这里应该用〈连续〉。「频繁」指一次次地发生，不能描述一口气的持续。"}, {"text": "我频繁读完了这本书。", "explanation": "这里应该用〈一口气〉。「频繁」指多次重复，不能描述一次读完。"}, {"text": "他频繁记得你，永远不忘。", "explanation": "这里应该用〈一直〉。「频繁」指同一件事一次次地发生，不能描述「记得」这种持续的状态；持续的状态要用「一直」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司频繁的换办公室。", "corrected_sentence": "我们公司频繁换办公室。", "error_description": "错误形式「频繁的换」：「频繁」修饰动词时是状语，后面不加定语标记「的」，正确形式为「频繁换」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年我们频繁得搬家。", "corrected_sentence": "这几年我们频繁地搬家。", "error_description": "错误形式「频繁得搬家」：修饰动词要用助词「地」，不用「得」，正确形式为「频繁地搬家」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
