INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "天气很好，没有云，亮亮的。", "primary_collocate": null, "pronunciation": "míng lǎng", "ipa": "miŋ˧˥ laŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天的天空很明朗。", "target_word": "明朗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明朗的天气让大家都很高兴。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末天气明朗，公园里有很多人。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上推开窗，外面的天空明朗极了。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天天气明朗，最高气温二十度。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨过天晴，山上的天色格外明朗。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天一直很明朗，没有下雨。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气明朗的时候，可以看到远处的山。", "target_word": "明朗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜间天气明朗，繁星格外多。", "target_word": "明朗", "complexity_tier": "T3", "furigana": "yè jiān tiān qì míng lǎng, fán xīng gé wài duō.", "sentence_source": "generated"}, {"text": "大风把云吹走了，天空变得明朗了。", "target_word": "明朗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "明朗化", "label": "复合词"}, {"form": "不明朗", "label": "否定式"}], "register": "书面", "sense_fingerprint": "明朗|天气晴好无云明亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天气晴好、天色明亮，与“天空”搭配，符合句意。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”说质地，不用来形容天色。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”用于味道，不与“天空”搭配。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”用于味道，不能用来形容天空。"}], "explanations": {"明朗": "明朗：天气晴好、天色明亮，与“天空”搭配，符合句意。", "硬": "语义：“硬”说质地，不用来形容天色。", "咸": "搭配：“咸”用于味道，不与“天空”搭配。", "辣": "搭配：“辣”用于味道，不能用来形容天空。"}, "sentence_index": 0, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的灯很明朗，照得人睁不开眼。", "explanation": "这里应该用〈明亮〉。明朗多形容天气、心情或声音，灯这类发亮的物体要用〈明亮〉。"}, {"text": "山间的溪水很明朗，能看见水底的鱼在游。", "explanation": "这里应该用〈清澈〉。形容水清而透明要用〈清澈〉，明朗不用于形容水。"}, {"text": "这杯茶的味道很明朗，喝起来很清爽。", "explanation": "这里应该用〈醇厚〉。形容茶的滋味要用〈醇厚〉或〈清香〉，明朗不用于描写味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明朗", "is_correct": true, "explanation": "明朗：天气晴好、没有云，与“一直”搭配，符合“没有下雨”的语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不用来形容天气。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”说温度，不用来形容天气的晴好。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚薄，不能用来形容天气。"}], "explanations": {"明朗": "明朗：天气晴好、没有云，与“一直”搭配，符合“没有下雨”的语境。", "甜": "语义：“甜”形容味道，不用来形容天气。", "烫": "语义：“烫”说温度，不用来形容天气的晴好。", "厚": "语义：“厚”形容物体的厚薄，不能用来形容天气。"}, "sentence_index": 6, "correct_answer": "明朗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块金属被打磨得很明朗，闪闪发亮。", "explanation": "这里应该用〈光亮〉。形容金属等物体表面发亮要用〈光亮〉，明朗用于天气、心情，不用于描写物体表面。"}, {"text": "早晨的空气很明朗，让人神清气爽。", "explanation": "这里应该用〈清新〉。形容空气要用〈清新〉，明朗不用于形容空气。"}, {"text": "他对童年的往事记得很明朗，连细节都说得清清楚楚。", "explanation": "这里应该用〈清晰〉。描述记忆、印象清楚要用〈清晰〉，明朗不用于描述记忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，天空明朗地很，远处的山看得清清楚楚。", "corrected_sentence": "雨停以后，天空明朗得很，远处的山看得清清楚楚。", "error_description": "补语标记错误：程度补语“明朗得很”中的“得”误写成“地”。错误形式是“明朗地很”，正确形式是“明朗得很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的天空地明朗，山都看得很清楚。", "corrected_sentence": "今天的天空很明朗，山都看得很清楚。", "error_description": "“明朗”前应用程度副词“很”，不能用结构助词“地”。错误形式是“地明朗”，正确形式是“很明朗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "正确。健康指身体没有疾病，与“疾病”意思相对。"}, {"text": "手机", "is_correct": false, "explanation": "与“疾病”没有反义关系：手机是通讯工具，不涉及身体状况。"}, {"text": "公园", "is_correct": false, "explanation": "与“疾病”没有反义关系：公园是供人游览的场所，与身体无关。"}, {"text": "汽车", "is_correct": false, "explanation": "与“疾病”没有反义关系：汽车是交通工具，不是身体的状态。"}], "correct_answer": "健康", "explanations": {"健康": "正确。健康指身体没有疾病，与“疾病”意思相对。", "手机": "与“疾病”没有反义关系：手机是通讯工具，不涉及身体状况。", "公园": "与“疾病”没有反义关系：公园是供人游览的场所，与身体无关。", "汽车": "与“疾病”没有反义关系：汽车是交通工具，不是身体的状态。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健康", "is_correct": true, "explanation": "正确。健康指身体没有疾病，与“疾病”意思相对。"}, {"text": "窗户", "is_correct": false, "explanation": "与“疾病”没有反义关系：窗户是建筑构件，不是身体状况。"}, {"text": "词典", "is_correct": false, "explanation": "与“疾病”没有反义关系：词典是工具书，和身体无关。"}, {"text": "牛奶", "is_correct": false, "explanation": "与“疾病”没有反义关系：牛奶是饮品，不是身体的状态。"}], "correct_answer": "健康", "explanations": {"健康": "正确。健康指身体没有疾病，与“疾病”意思相对。", "窗户": "与“疾病”没有反义关系：窗户是建筑构件，不是身体状况。", "词典": "与“疾病”没有反义关系：词典是工具书，和身体无关。", "牛奶": "与“疾病”没有反义关系：牛奶是饮品，不是身体的状态。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体不舒服，生病了。", "primary_collocate": null, "pronunciation": "jí bìng", "ipa": "tɕi˧˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他有疾病，今天不能来上课。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师因为疾病请了三天假。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疾病让奶奶很难受，吃不下饭。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的疾病好了，明天可以上学。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她身体有疾病，不能喝冰水。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸很少有疾病，身体很好。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为疾病，他瘦了很多。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子有疾病，妈妈整夜没睡。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "疾病让他一个月没有上班。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想让疾病影响我的生活。", "target_word": "疾病", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢性疾病", "label": "复合"}, {"form": "心脏疾病", "label": "复合"}], "register": "书面", "sense_fingerprint": "身体不舒服、生病的情况（个人的病情）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾病", "is_correct": true, "explanation": "正确。“有疾病”表示患病，是不能来上课的原因。"}, {"text": "课本", "is_correct": false, "explanation": "语义：有课本不是不能来上课的原因，句子逻辑不通。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：有镜子不会导致缺课，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有”后面不能接“颜色”作为缺课的原因，搭配不当。"}], "explanations": {"疾病": "正确。“有疾病”表示患病，是不能来上课的原因。", "课本": "语义：有课本不是不能来上课的原因，句子逻辑不通。", "镜子": "语义：有镜子不会导致缺课，句意不通。", "颜色": "搭配：“有”后面不能接“颜色”作为缺课的原因，搭配不当。"}, "sentence_index": 0, "correct_answer": "疾病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱有疾病，总是不制冷。", "explanation": "这里应该用〈毛病〉。疾病指人或动植物的病，冰箱出了问题要说毛病。"}, {"text": "他的疾病是性格很急。", "explanation": "这里应该用〈缺点〉。缺点指性格或行为上的不足；疾病指身体的病，不能用来说性格。"}, {"text": "这条路的疾病很多，车子很难开。", "explanation": "这里应该用〈问题〉。路况上的毛病或状况要说问题，疾病只指人或动植物的病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疾病", "is_correct": true, "explanation": "正确。疾病会使人消瘦，可以作为瘦的原因。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会让人瘦下来，“因为房子”不能作原因。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典与体重无关，不能作为瘦的原因。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能导致体重下降，句子不通。"}], "explanations": {"疾病": "正确。疾病会使人消瘦，可以作为瘦的原因。", "房子": "语义：房子不会让人瘦下来，“因为房子”不能作原因。", "字典": "语义：字典与体重无关，不能作为瘦的原因。", "身高": "体貌：身高是人的外形特征，不能导致体重下降，句子不通。"}, "sentence_index": 6, "correct_answer": "疾病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府要想办法改善百姓的生活疾病，让大家过得更好。", "explanation": "这里应该用〈疾苦〉。“生活疾苦”指生活中的困难和痛苦，才会说“改善”；疾病指身体的病，不能用来指生活中的困难。"}, {"text": "医院门口来了很多疾病，都在排队挂号。", "explanation": "这里应该用〈病患〉。病患指患病的人，才会排队挂号；疾病指病本身，不能排队挂号。"}, {"text": "这台机器的疾病已经修好了。", "explanation": "这里应该用〈故障〉。故障指机器出了问题；疾病只指生物的病，不能用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅得了一只疾病，需要住院。", "corrected_sentence": "我舅舅得了一种疾病，需要住院。", "error_description": "量词错误：疾病应搭配量词“种”，“只”用于动物等，应说“一种疾病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只慢性疾病让奶奶很难受。", "corrected_sentence": "这种慢性疾病让奶奶很难受。", "error_description": "量词错误：疾病应搭配量词“种”，“只”用于动物等，应说“这种慢性疾病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
