INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发生前的小信号。", "primary_collocate": null, "pronunciation": "qián zhào", "ipa": "tɕʰjɛn˧˥ ʈʂaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "打雷是下雨的前兆。", "target_word": "前兆", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他脸色不好，可能是生病的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚂蚁搬家是下大雨的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "嗓子痒常常是感冒的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地面发抖是地震的前兆，大家要小心。", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早晨的红云，有时是坏天气的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗一直不吃饭，是不是生病的前兆？", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开始整天发脾气，这是压力大的前兆。", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水突然变少了，是干旱的前兆。", "target_word": "前兆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟总打哈欠，这是想睡觉的前兆。", "target_word": "前兆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "前兆|事情发生前的小信号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前兆", "is_correct": true, "explanation": "正确。前兆指事情发生前的小信号。"}, {"text": "千兆", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是千兆（网速单位）。"}, {"text": "前朝", "is_correct": false, "explanation": "cháo 与 zhào 声母不同（ch 与 zh），意思是前一个朝代。"}, {"text": "前者", "is_correct": false, "explanation": "zhě（第三声）与 zhào（第四声）韵母和声调都不同，意思是前面的那个。"}], "explanations": {"前兆": "正确。前兆指事情发生前的小信号。", "千兆": "qiān（第一声）与 qián（第二声）声调不同，意思是千兆（网速单位）。", "前朝": "cháo 与 zhào 声母不同（ch 与 zh），意思是前一个朝代。", "前者": "zhě（第三声）与 zhào（第四声）韵母和声调都不同，意思是前面的那个。"}, "sentence_index": null, "correct_answer": "前兆"}, "level_3": {"options": [{"text": "前兆", "is_correct": true, "explanation": "正确。打雷是下雨前的小信号。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙与下雨没有关系，不能作为下雨的迹象。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不是下雨的迹象，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“下雨的”后不能接家用电器，搭配不当。"}], "explanations": {"前兆": "正确。打雷是下雨前的小信号。", "钥匙": "语义：钥匙与下雨没有关系，不能作为下雨的迹象。", "花朵": "语义：花朵不是下雨的迹象，句子不通。", "冰箱": "搭配：“下雨的”后不能接家用电器，搭配不当。"}, "sentence_index": 0, "correct_answer": "前兆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的前兆很好听。", "explanation": "这里应该用〈前奏〉。前奏指音乐开始的部分；前兆指事情发生前的小信号，不能用于歌曲。"}, {"text": "他是我的前兆，教了我很多东西。", "explanation": "这里应该用〈前辈〉。前辈指经验多、资历深的人；前兆是信号，不指人。"}, {"text": "他的前兆很好，将来一定有出息。", "explanation": "这里应该用〈前途〉。“前途”指将来的发展和成就，才会说有出息；前兆是事情发生前的信号，不指人的将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前兆", "is_correct": true, "explanation": "正确。小狗不吃饭可能是生病的信号。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不会生病，“生病的玩具”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“生病的”修饰人或动物，不能修饰桌子。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“生病的”修饰人或动物，窗帘不能生病，搭配不当。"}], "explanations": {"前兆": "正确。小狗不吃饭可能是生病的信号。", "玩具": "语义：玩具不会生病，“生病的玩具”说不通。", "桌子": "搭配：“生病的”修饰人或动物，不能修饰桌子。", "窗帘": "搭配：“生病的”修饰人或动物，窗帘不能生病，搭配不当。"}, "sentence_index": 6, "correct_answer": "前兆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有前兆，所以很难找到工作。", "explanation": "这里应该用〈前科〉。前科指以前的犯罪记录；前兆是信号，不能用来说明一个人的经历。"}, {"text": "我前兆刚出门，他后脚就到了。", "explanation": "这里应该用〈前脚〉。前脚指先迈出的那只脚，表示刚刚发生的事；前兆不能表示先后动作。"}, {"text": "公司的前兆经理很有能力。", "explanation": "这里应该用〈前任〉。前任指以前担任该职务的人；前兆是信号，不指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上发现鸟儿乱飞，常是要下雨的一只前兆。", "corrected_sentence": "早上发现鸟儿乱飞，常是要下雨的一种前兆。", "error_description": "量词错误：前兆应搭配“种”或“个”，“只”用于动物等，应说“一种前兆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这几天一直不说话，这是心里有事前兆。", "corrected_sentence": "他这几天一直不说话，这是心里有事的前兆。", "error_description": "“的”遗漏：修饰语“心里有事”后要加“的”，应说“心里有事的前兆”，不能说“心里有事前兆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "反义：“死亡”指生命结束，与“生存”的“活着”正相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常行为，与“生存”不构成反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "“学习”与“生存”不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”与“生存”不构成反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "反义：“死亡”指生命结束，与“生存”的“活着”正相反。", "睡觉": "“睡觉”是日常行为，与“生存”不构成反义关系。", "学习": "“学习”与“生存”不构成反义关系。", "旅行": "“旅行”与“生存”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "死亡", "is_correct": true, "explanation": "反义：“死亡”指生命结束，与“生存”的“活着”正相反。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种活动，与“生存”不构成反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "“工作”与“生存”不构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是一种动作，与“生存”不构成反义关系。"}], "correct_answer": "死亡", "explanations": {"死亡": "反义：“死亡”指生命结束，与“生存”的“活着”正相反。", "游泳": "“游泳”是一种活动，与“生存”不构成反义关系。", "工作": "“工作”与“生存”不构成反义关系。", "跑步": "“跑步”是一种动作，与“生存”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "活着，没有死掉。", "primary_collocate": null, "pronunciation": "shēng cún", "ipa": "ʂɤŋ˥ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "鱼离开水就不能生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的动物很会生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人需要水和食物才能生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花在冷的地方也能生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鸟在极寒的地方很难生存。", "target_word": "生存", "complexity_tier": "T3", "furigana": "zhè xiē niǎo zài jí hán de dì fang hěn nán shēng cún.", "sentence_source": "generated"}, {"text": "森林消失了，很多动物无法生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里生存了三天。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带鱼不能在冷水里生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了生存，他每天都去工作。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎需要大片森林来生存。", "target_word": "生存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存了", "label": "体标"}, {"form": "生存着", "label": "体标"}, {"form": "生存过", "label": "体标"}, {"form": "生存环境", "label": "复合"}, {"form": "生存空间", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物或人在环境中活下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生存", "is_correct": true, "explanation": "正确：“生存”指活下去，符合“鱼离开水就不能”的语境。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：鱼不能唱歌，“唱歌”与“离开水”的语境不符。"}, {"text": "读书", "is_correct": false, "explanation": "语义：鱼不会读书，“读书”与句子的语境不符。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”指探讨学问，“鱼离开水就不能研究”语义不通。"}], "explanations": {"生存": "正确：“生存”指活下去，符合“鱼离开水就不能”的语境。", "唱歌": "语义：鱼不能唱歌，“唱歌”与“离开水”的语境不符。", "读书": "语义：鱼不会读书，“读书”与句子的语境不符。", "研究": "语义：“研究”指探讨学问，“鱼离开水就不能研究”语义不通。"}, "sentence_index": 0, "correct_answer": "生存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天的生存很规律。", "explanation": "这里应该用〈生活〉。“生存”强调活下去，不表示日常的起居和作息。"}, {"text": "这棵树生存得很快。", "explanation": "这里应该用〈生长〉。树木长得快要用“生长”；“生存”只表示活着。"}, {"text": "他生存了三个孩子。", "explanation": "这里应该用〈生〉。“生存”只表示活着，不能带“孩子”作宾语表示生育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生存", "is_correct": true, "explanation": "正确：“生存”指活下去，符合“在山里……了三天”的语境。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指成为配偶，不能作为在山里的一段经历。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：“叫醒”需要带宾语，句中没有宾语，不成立。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“在山里三天”的语境不符。"}], "explanations": {"生存": "正确：“生存”指活下去，符合“在山里……了三天”的语境。", "结婚": "语义：“结婚”指成为配偶，不能作为在山里的一段经历。", "叫醒": "配价：“叫醒”需要带宾语，句中没有宾语，不成立。", "退休": "语义：“退休”指离开工作岗位，与“在山里三天”的语境不符。"}, "sentence_index": 6, "correct_answer": "生存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题一直生存。", "explanation": "这里应该用〈存在〉。问题、现象的持续用“存在”；“生存”只用于生物或人活下去。"}, {"text": "这个工厂每天生存很多垃圾。", "explanation": "这里应该用〈产生〉。“生存”指活下去，表示工厂产生垃圾要用“产生”。"}, {"text": "这把椅子生存了三年。", "explanation": "这里不能用“生存”。“生存”的主语必须是生物或人，椅子没有生命，应说“用了三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鸟在冬天也能生存起来。", "corrected_sentence": "这种鸟在冬天也能生存下来。", "error_description": "补语错误：“生存”后接趋向补语应为“下来”（活下来），不说“起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会很生存。", "corrected_sentence": "他很会生存。", "error_description": "状语位置错误：“很”修饰“会”，应放在“会”前，说“很会生存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
