INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西还在，没有消失。", "primary_collocate": null, "pronunciation": "cún", "ipa": "tsʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这座老桥至今还存着。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷写的信我还存着。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古城的城墙只存一小段。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房子都倒了，只有一棵树还存着。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书世上只存两本。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地震以后，这里什么也没存下来。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他心里还存着一点希望。", "target_word": "存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火灾以后，这幅画竟然完整地存了下来。", "target_word": "存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家里还存着我小时候的玩具。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老城区已经拆了，只存几条小巷。", "target_word": "存", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "存了", "label": "完成体"}, {"form": "存着", "label": "持续体"}, {"form": "存留", "label": "复合词"}], "register": "中性", "sense_fingerprint": "存|东西还在没有消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '337469d9-f7c0-4db5-9363-9ea8a285fa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "存", "is_correct": true, "explanation": "cún，意思是东西还在、没有消失。"}, {"text": "村", "is_correct": false, "explanation": "cūn（第一声）与 cún（第二声）声调不同，意思是村庄。"}, {"text": "寸", "is_correct": false, "explanation": "cùn（第四声）与 cún（第二声）声调不同，意思是长度单位寸。"}, {"text": "唇", "is_correct": false, "explanation": "chún 与 cún 声母不同（ch 与 c），意思是嘴唇。"}], "explanations": {"存": "cún，意思是东西还在、没有消失。", "村": "cūn（第一声）与 cún（第二声）声调不同，意思是村庄。", "寸": "cùn（第四声）与 cún（第二声）声调不同，意思是长度单位寸。", "唇": "chún 与 cún 声母不同（ch 与 c），意思是嘴唇。"}, "sentence_index": null, "correct_answer": "存"}, "level_3": {"options": [{"text": "存", "is_correct": true, "explanation": "存：表示事物还在、没有消失，与“至今还……着”搭配，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示发声，不能说老桥“还唱着”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要食物作宾语，不能用于桥。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“老桥”搭配，也不表示持续存在。"}], "explanations": {"存": "存：表示事物还在、没有消失，与“至今还……着”搭配，符合句意。", "唱": "语义：“唱”表示发声，不能说老桥“还唱着”。", "吃": "配价：“吃”需要食物作宾语，不能用于桥。", "洗": "搭配：“洗”不与“老桥”搭配，也不表示持续存在。"}, "sentence_index": 0, "correct_answer": "存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爷爷还存着，身体比以前好多了。", "explanation": "这里应该用〈活〉。说人还活着要用〈活〉，“存”只用于事物的留存。"}, {"text": "他已经存在国外读了三年书。", "explanation": "这里应该用〈留〉。人留在某地学习、工作要说留，“存”只用于东西的留存，不用于人。"}, {"text": "他把盘子里的饭都存完了，肚子饱饱的。", "explanation": "这里应该用〈吃〉。把饭吃光要说吃完；“存”表示东西留下来，不表示把饭吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20426, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "存", "is_correct": true, "explanation": "cún，意思是东西还在、没有消失。"}, {"text": "纯", "is_correct": false, "explanation": "chún 与 cún 声母不同（ch 与 c），意思是纯净。"}, {"text": "春", "is_correct": false, "explanation": "chūn 与 cún 声母和声调都不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn 与 cún 声母和声调不同，意思是愚蠢。"}], "explanations": {"存": "cún，意思是东西还在、没有消失。", "纯": "chún 与 cún 声母不同（ch 与 c），意思是纯净。", "春": "chūn 与 cún 声母和声调都不同，意思是春天。", "蠢": "chǔn 与 cún 声母和声调不同，意思是愚蠢。"}, "sentence_index": null, "correct_answer": "存"}, "level_3": {"options": [{"text": "存", "is_correct": true, "explanation": "存：表示心里还保有希望，与“心里还……着”搭配，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“心里还有希望”的意思相矛盾。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”用于具体的物件，不与“希望”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不与“心里”或“希望”搭配。"}], "explanations": {"存": "存：表示心里还保有希望，与“心里还……着”搭配，符合句意。", "扔": "语义：“扔”表示丢弃，与“心里还有希望”的意思相矛盾。", "切": "搭配：“切”用于具体的物件，不与“希望”搭配。", "煮": "搭配：“煮”用于食物，不与“心里”或“希望”搭配。"}, "sentence_index": 6, "correct_answer": "存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱旧衣服我存进了垃圾桶。", "explanation": "这里应该用〈扔〉。丢弃东西要说扔，“存”不表示丢弃。"}, {"text": "我把钥匙存丢了，找了一下午。", "explanation": "这里应该用〈丢〉。东西遗失要说丢，“存”没有遗失的意思。"}, {"text": "我们在院子里存了一排玫瑰。", "explanation": "这里应该用〈栽〉。把花草、树苗种进土里要说栽，“存”不表示种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老城门至今还存了。", "corrected_sentence": "这座老城门至今还存着。", "error_description": "表示事物“还在、没有消失”的持续状态要用“着”，不能用“了”。错误形式是“存了”，正确形式是“存着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洪水以后，村里什么也没存来下。", "corrected_sentence": "洪水以后，村里什么也没存下来。", "error_description": "趋向补语“下来”要放在动词“存”后面。错误形式是“存来下”，正确形式是“存下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e86882b-21bc-4255-bf2c-34bb06cbec8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
