INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引起某件事发生。", "primary_collocate": null, "pronunciation": "yòu fā", "ipa": "joʊ˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "不好的习惯会诱发很多问题。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海鲜诱发了他的皮肤问题。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨诱发了山上的泥石流。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强光会诱发有些人头疼。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一句话诱发了一场激烈的争论。", "target_word": "诱发", "complexity_tier": "T3", "furigana": "tā de yí jù huà yòufā le yì chǎng jīliè de zhēnglùn", "sentence_source": "generated"}, {"text": "太累会诱发旧病。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟雾诱发了她的咳嗽。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次地震诱发了海啸。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "紧张的比赛诱发了他的胃病。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷风诱发孩子感冒，所以要多穿衣服。", "target_word": "诱发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱发了", "label": "体标"}, {"form": "诱发过", "label": "体标"}], "register": "书面", "sense_fingerprint": "引起某件事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雕刻", "is_correct": false, "explanation": "搭配：「雕刻」的对象是木料、石料等材料，不能用于「问题」。"}, {"text": "诱发", "is_correct": true, "explanation": "诱发：引起某事发生。「习惯引起很多问题」符合句意。"}, {"text": "解决", "is_correct": false, "explanation": "语义：「解决」表示消除问题，与「会……很多问题」所说的引发问题相反。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：「缝补」的对象是衣物等，「问题」不能被缝补。"}], "explanations": {"雕刻": "搭配：「雕刻」的对象是木料、石料等材料，不能用于「问题」。", "诱发": "诱发：引起某事发生。「习惯引起很多问题」符合句意。", "解决": "语义：「解决」表示消除问题，与「会……很多问题」所说的引发问题相反。", "缝补": "搭配：「缝补」的对象是衣物等，「问题」不能被缝补。"}, "sentence_index": 0, "correct_answer": "诱发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家诱发了一颗新星。", "explanation": "这里应该用〈发现〉。新星是本来就存在、被找到的天体，诱发表示引起某种结果，不能用于此。"}, {"text": "妈妈诱发了一件新衣服。", "explanation": "这里应该用〈买〉。衣服是买来的，诱发表示引起某种结果，不能用于购买。"}, {"text": "歌手诱发了一首新歌。", "explanation": "这里应该用〈演唱〉。新歌是唱出来的，诱发不能用于演唱这类行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱发", "is_correct": true, "explanation": "诱发：引起某种情况。「烟雾引起她的咳嗽」符合句意。"}, {"text": "抚养", "is_correct": false, "explanation": "语义：「抚养」指养育人或动物，不能用于「咳嗽」这种症状。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：「点燃」用于火、灯等，不能与「咳嗽」搭配。"}, {"text": "投诉", "is_correct": false, "explanation": "配价：「投诉」需要投诉的主体和对象，「烟雾」不能作为投诉的主体。"}], "explanations": {"诱发": "诱发：引起某种情况。「烟雾引起她的咳嗽」符合句意。", "抚养": "语义：「抚养」指养育人或动物，不能用于「咳嗽」这种症状。", "点燃": "搭配：「点燃」用于火、灯等，不能与「咳嗽」搭配。", "投诉": "配价：「投诉」需要投诉的主体和对象，「烟雾」不能作为投诉的主体。"}, "sentence_index": 6, "correct_answer": "诱发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家诱发了一本小说。", "explanation": "这里应该用〈写〉。小说是写出来的，诱发表示引起某种结果，不能用于写作。"}, {"text": "工人诱发了旧房子。", "explanation": "这里应该用〈拆除〉。旧房子是被拆掉的对象，诱发不能用于拆除。"}, {"text": "师傅诱发了这台机器。", "explanation": "这里应该用〈修复〉。机器坏了要修复，诱发不能用于修理这类行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒风会诱发把他的咳嗽。", "corrected_sentence": "寒风会诱发他的咳嗽。", "error_description": "错误：「诱发把他的咳嗽」在动词和宾语之间多加了「把」。正确：「诱发他的咳嗽」。诱发是及物动词，可直接带宾语，不用「把」字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熬夜会诱发得她的偏头痛。", "corrected_sentence": "熬夜会诱发她的偏头痛。", "error_description": "错误：「诱发得她的偏头痛」在动词后多加了「得」。正确：「诱发她的偏头痛」。诱发直接带宾语，不需要「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
