INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种没有颜色的气体。", "primary_collocate": null, "pronunciation": "yī yǎng huà dàn", "ipa": "i˥ jɑŋ˨˩ xua˥˩ tan˥˩", "syllable_count": 4, "sentences": [{"text": "一氧化氮是一种没有颜色的气体。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一氧化氮看不见，也没有味道。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车排出的气体里有一氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在化学课上讲了一氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一氧化氮遇到空气，会变成别的气体。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的烟里有一氧化氮，对空气不好。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里装着一氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的身体里也有一点一氧化氮。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一氧化氮是气体，不是水。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的一氧化氮要小心用。", "target_word": "一氧化氮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一氧化氮：一种没有颜色的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一氧化氮", "is_correct": true, "explanation": "正确：一氧化氮是一种无色的气体，与句子的描述一致。"}, {"text": "黄金", "is_correct": false, "explanation": "语义：黄金是黄色的金属，不是气体，与“没有颜色的气体”矛盾。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁是金属，不是气体，与“一种……气体”的说法不符。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“一种……的气体”要求主语是气体，“牛奶”是白色液体，不能这样搭配。"}], "explanations": {"一氧化氮": "正确：一氧化氮是一种无色的气体，与句子的描述一致。", "黄金": "语义：黄金是黄色的金属，不是气体，与“没有颜色的气体”矛盾。", "铁": "语义：铁是金属，不是气体，与“一种……气体”的说法不符。", "牛奶": "搭配：“一种……的气体”要求主语是气体，“牛奶”是白色液体，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "一氧化氮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厕所里有一座一氧化氮。", "explanation": "这里量词错了。“座”用于山、楼等大而固定的东西；一氧化氮是气体，应说〈瓶〉。"}, {"text": "煤气罐旁边有一张一氧化氮。", "explanation": "这里量词错了。“张”用于纸、桌子等扁平的东西；一氧化氮是气体，应说〈瓶〉或〈罐〉。"}, {"text": "实验室里有一块一氧化氮。", "explanation": "这里量词应该用〈瓶〉或〈罐〉。一氧化氮是气体，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一氧化氮", "is_correct": true, "explanation": "正确：一氧化氮是气体，可以装在瓶子里，与句子一致。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法装进瓶子，与“瓶子里装着”的常识矛盾。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间比瓶子大得多，不可能装在瓶子里。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“装着”的宾语要能装进容器，“教室”不能说装在瓶子里。"}], "explanations": {"一氧化氮": "正确：一氧化氮是气体，可以装在瓶子里，与句子一致。", "大海": "语义：大海无法装进瓶子，与“瓶子里装着”的常识矛盾。", "房间": "语义：房间比瓶子大得多，不可能装在瓶子里。", "教室": "搭配：“装着”的宾语要能装进容器，“教室”不能说装在瓶子里。"}, "sentence_index": 6, "correct_answer": "一氧化氮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车尾气里有一粒一氧化氮。", "explanation": "这里量词错了。“粒”用于颗粒状的东西；一氧化氮是气体，应说〈瓶〉或〈罐〉。"}, {"text": "游泳池里有一颗一氧化氮。", "explanation": "这里量词错了。“颗”用于颗粒状的东西；一氧化氮是气体，应说〈瓶〉或〈罐〉。"}, {"text": "灭火器里装着一把一氧化氮。", "explanation": "这里量词错了。“把”用于有柄的东西；一氧化氮是气体，应说〈瓶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室里有一片一氧化氮，要小心使用。", "corrected_sentence": "实验室里有一瓶一氧化氮，要小心使用。", "error_description": "量词错误：“一氧化氮”是气体，应说“一瓶”，不能说“一片”（“片”用于薄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂会排放一块一氧化氮，污染空气。", "corrected_sentence": "工厂会排放一氧化氮，污染空气。", "error_description": "量词错误：“一氧化氮”是气体，不能加量词“块”（“块”用于块状固体）。应直接说“排放一氧化氮”，去掉“一块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
