INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里的一种东西，能帮助妈妈生宝宝。", "primary_collocate": null, "pronunciation": "cuī chǎn sù", "ipa": "tsʰuei˥ tʂʰan˨˩ su˥˩", "syllable_count": 3, "sentences": [{"text": "催产素是身体里的一种东西。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "催产素能帮助妈妈生宝宝。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝快出生了，妈妈体内的催产素变多了。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，催产素对生孩子有用。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈抱着宝宝，身体会放出催产素。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士给妈妈打了催产素。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有催产素，妈妈生宝宝会更难。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "催产素还能让妈妈更爱宝宝。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读过催产素这个词。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸抱孩子的时候，身体里也有催产素。", "target_word": "催产素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "催产素：身体里帮助妈妈生宝宝的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "催产素", "is_correct": true, "explanation": "催产素是身体里帮助妈妈生宝宝的物质，与句中的“身体里的一种东西”相符。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不存在于人体内，与“身体里的一种东西”矛盾。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是大气放电现象，不是身体里的物质。"}, {"text": "小玩意", "is_correct": false, "explanation": "语域：“小玩意”口语化，不适合这种说明性的句子。"}], "explanations": {"催产素": "催产素是身体里帮助妈妈生宝宝的物质，与句中的“身体里的一种东西”相符。", "汽油": "语义：汽油是燃料，不存在于人体内，与“身体里的一种东西”矛盾。", "闪电": "语义：闪电是大气放电现象，不是身体里的物质。", "小玩意": "语域：“小玩意”口语化，不适合这种说明性的句子。"}, "sentence_index": 0, "correct_answer": "催产素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消化脂肪时，身体会分泌催产素。", "explanation": "这里应该用〈脂肪酶〉。消化脂肪靠脂肪酶，催产素是促进分娩和哺乳的激素，与消化无关。"}, {"text": "催产素负责把氧气运到全身。", "explanation": "这里应该用〈血红蛋白〉。血红蛋白在红细胞中运输氧气，催产素与氧气运输无关。"}, {"text": "进入青春期后，女孩体内的催产素开始增多，乳房也逐渐发育。", "explanation": "这里应该用〈雌激素〉。雌激素促进女性第二性征发育，包括乳房发育；催产素与分娩和亲子关系有关，不参与青春期的乳房发育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "催产素", "is_correct": true, "explanation": "催产素能帮助分娩，句中说“没有催产素，生宝宝会更难”，语义连贯。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与分娩没有关系，不能作为“没有……生宝宝会更难”的条件。"}, {"text": "鬼东西", "is_correct": false, "explanation": "语域：“鬼东西”是骂人的口语词，与这句平和的叙述语气不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是影响分娩的物质，与句意不合。"}], "explanations": {"催产素": "催产素能帮助分娩，句中说“没有催产素，生宝宝会更难”，语义连贯。", "钢琴": "语义：钢琴与分娩没有关系，不能作为“没有……生宝宝会更难”的条件。", "鬼东西": "语域：“鬼东西”是骂人的口语词，与这句平和的叙述语气不符。", "闹钟": "语义：闹钟不是影响分娩的物质，与句意不合。"}, "sentence_index": 6, "correct_answer": "催产素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人体靠免疫系统产生催产素来防御病原体。", "explanation": "这里应该用〈抗体〉。抗体由免疫系统产生来防御病原体，催产素是脑垂体分泌的激素，不参与这一过程。"}, {"text": "伤口发炎时，医生通常会开催产素。", "explanation": "这里应该用〈抗生素〉。伤口发炎要用抗生素治疗细菌感染，催产素与感染无关。"}, {"text": "缺少催产素容易得坏血病。", "explanation": "这里应该用〈维生素C〉。坏血病由缺乏维生素C引起，催产素不是营养素，不能预防坏血病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在药房拿了一块催产素。", "corrected_sentence": "医生在药房拿了一支催产素。", "error_description": "错误形式：“一块催产素”；正确形式：“一支催产素”。催产素注射液一般按“支”（安瓿）计量；“块”指固体块状的东西，不用于药剂。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈分娩时，体内地催产素会增加。", "corrected_sentence": "妈妈分娩时，体内的催产素会增加。", "error_description": "错误形式：“体内地催产素”；正确形式：“体内的催产素”。“体内的”作名词性定语修饰“催产素”，应用“的”；“地”用于修饰动词，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
