INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神经递质是大脑里帮助信息传递的小东西。", "primary_collocate": null, "pronunciation": "shén jīng dì zhì", "ipa": "ʂən˧˥ tɕiŋ˥ ti˥˩ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "神经递质是大脑里的小东西。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑里有很多神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经递质帮助大脑传递信息。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经递质很小，眼睛看不见。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的身体里都有神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说神经递质能让我们高兴。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑用神经递质来传话。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭和睡觉都会影响神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小东西叫神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的大脑里也有神经递质。", "target_word": "神经递质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "大脑里帮助传递信息的小东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c74b7c6-7d21-4de0-a475-ff9569fa042b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经递质", "is_correct": true, "explanation": "神经递质是大脑里传递信息的小东西，与句中的“大脑里的小东西”相符。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不在大脑里，与句中的描述完全不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是定时发声的器具，不是大脑里的东西。"}, {"text": "鬼东西", "is_correct": false, "explanation": "语域：“鬼东西”是骂人的口语词，与这句的说明语气不合。"}], "explanations": {"神经递质": "神经递质是大脑里传递信息的小东西，与句中的“大脑里的小东西”相符。", "星星": "语义：星星是天体，不在大脑里，与句中的描述完全不符。", "闹钟": "语义：闹钟是定时发声的器具，不是大脑里的东西。", "鬼东西": "语域：“鬼东西”是骂人的口语词，与这句的说明语气不合。"}, "sentence_index": 0, "correct_answer": "神经递质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大脑里有一只神经递质。", "explanation": "这里应该用〈种〉。神经递质是化学物质，应该用“种”计量；“只”用于动物或成对的器官。"}, {"text": "神经递质有细胞体、树突和轴突。", "explanation": "这里应该用〈神经元〉。细胞体、树突和轴突是神经元的结构，神经递质是化学分子，没有这些结构。"}, {"text": "神经递质沿着神经纤维快速传播。", "explanation": "这里应该用〈神经冲动〉。神经冲动沿神经纤维快速传播，神经递质在突触间隙起作用，不沿神经纤维传播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经递质", "is_correct": true, "explanation": "大脑用神经递质在神经细胞之间传话，符合句中“传话”的语境。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是人与人通话的工具，大脑不用它，与句中的“大脑”不合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙用于开锁，大脑不用它来传话，与句意不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟用于定时发声，不传递信息，与“传话”的意思不符。"}], "explanations": {"神经递质": "大脑用神经递质在神经细胞之间传话，符合句中“传话”的语境。", "电话": "语义：电话是人与人通话的工具，大脑不用它，与句中的“大脑”不合。", "钥匙": "语义：钥匙用于开锁，大脑不用它来传话，与句意不符。", "闹钟": "语义：闹钟用于定时发声，不传递信息，与“传话”的意思不符。"}, "sentence_index": 6, "correct_answer": "神经递质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "神经递质通过血液运到全身。", "explanation": "这里应该用〈激素〉。激素通过血液运到全身，神经递质主要在突触间隙起作用，不靠血液长距离运输。"}, {"text": "糖尿病人需要注射神经递质。", "explanation": "这里应该用〈胰岛素〉。糖尿病人注射的是胰岛素来调节血糖，神经递质与血糖调节无关。"}, {"text": "孩子缺乏神经递质容易得佝偻病。", "explanation": "这里应该用〈维生素D〉。佝偻病由缺乏维生素D引起，神经递质不是营养素，不能预防佝偻病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大脑里的每块神经递质都有作用。", "corrected_sentence": "大脑里的每种神经递质都有作用。", "error_description": "错误形式：“每块神经递质”；正确形式：“每种神经递质”。神经递质是化学物质，应该用“种”计量；“块”指成块的实物，不用于这类物质。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "睡眠时，大脑里地神经递质会减少。", "corrected_sentence": "睡眠时，大脑里的神经递质会减少。", "error_description": "错误形式：“大脑里地神经递质”；正确形式：“大脑里的神经递质”。“大脑里的”作名词性定语修饰“神经递质”，应用“的”；“地”用于修饰动词，不能直接修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97f540e7-5032-4250-b823-6ee695372cb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
