INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做事或掌握技能所达到的好坏程度。", "primary_collocate": null, "pronunciation": "shuǐ píng", "ipa": "ʂweɪ˨˩˦ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他做饭的水平很高。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的工作水平我很放心。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明踢球的水平越来越好。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的水平让大家吃惊。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试看出你的真实水平。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打乒乓球的水平不低。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做菜的水平一般。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的画画水平进步了。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的作业水平比以前好。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个医生的水平很让人放心。", "target_word": "水平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "技术水平", "label": "复合"}, {"form": "工作水平", "label": "复合"}], "register": "中性", "sense_fingerprint": "水平：一个人做事做得好坏的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指做饭达到的程度，与“很高”搭配，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的身体高矮，不能说做饭的身高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不能用来说做饭的程度。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很高”不能用来说颜色，颜色不说高低。"}], "explanations": {"水平": "“水平”指做饭达到的程度，与“很高”搭配，句意通顺。", "身高": "语义：“身高”指人的身体高矮，不能说做饭的身高。", "年龄": "语义：“年龄”是人的岁数，不能用来说做饭的程度。", "颜色": "搭配：“很高”不能用来说颜色，颜色不说高低。"}, "sentence_index": 0, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她唱歌的水平很好听。", "explanation": "这里应该用〈声音〉。“好听”描述声音，不能描述能力水平。"}, {"text": "她把乐谱水平放在桌上。", "explanation": "这里的“水平”取“与地面平行”的意思，是另一个义项，与唱歌的能力无关。"}, {"text": "她的水平很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容人的体形，不能用来描述能力水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水平", "is_correct": true, "explanation": "“水平”指做菜达到的程度，与“一般”搭配，用来评价做菜的好坏，句意通顺。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的容貌，不能用来说做菜的情况。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”指人的身体形状，与做菜无关。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”指写的字的样子，做菜不写字，不能用“字迹”来评价。"}], "explanations": {"水平": "“水平”指做菜达到的程度，与“一般”搭配，用来评价做菜的好坏，句意通顺。", "长相": "体貌：“长相”指人的容貌，不能用来说做菜的情况。", "体型": "体貌：“体型”指人的身体形状，与做菜无关。", "字迹": "语义：“字迹”指写的字的样子，做菜不写字，不能用“字迹”来评价。"}, "sentence_index": 6, "correct_answer": "水平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个医生的水平很便宜。", "explanation": "这里应该用〈价格〉。“便宜”描述价格，不能描述能力水平。"}, {"text": "这个医生的水平很温和。", "explanation": "这里应该用〈脾气〉。“温和”形容性格或态度，不能形容能力水平。"}, {"text": "这个医生的水平很红。", "explanation": "这里应该用〈脸色〉。“红”形容颜色，水平没有颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她弹钢琴得水平很高。", "corrected_sentence": "她弹钢琴的水平很高。", "error_description": "“的”误用：“弹钢琴”修饰“水平”时要用“的”，不能用“得”；“得”只用于动词后引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他游泳的水平很的高。", "corrected_sentence": "他游泳的水平很高。", "error_description": "多余成分：“很”与“高”之间不能加“的”，应说“水平很高”，不能说“很的高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远", "is_correct": true, "explanation": "正确：“远”与“近”是反义词，表示距离远。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“近”无反义关系，“快”指速度。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”与“近”无反义关系，“宽”指宽度。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“近”无反义关系，“高”指高度。"}], "correct_answer": "远", "explanations": {"远": "正确：“远”与“近”是反义词，表示距离远。", "快": "“快”与“近”无反义关系，“快”指速度。", "宽": "“宽”与“近”无反义关系，“宽”指宽度。", "高": "“高”与“近”无反义关系，“高”指高度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "远", "is_correct": true, "explanation": "正确：“远”与“近”是反义词，表示距离远。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“近”无反义关系，“厚”指厚度。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“近”无反义关系，“亮”指光线明亮。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“近”无反义关系，“硬”指质地坚硬。"}], "correct_answer": "远", "explanations": {"远": "正确：“远”与“近”是反义词，表示距离远。", "厚": "“厚”与“近”无反义关系，“厚”指厚度。", "亮": "“亮”与“近”无反义关系，“亮”指光线明亮。", "硬": "“硬”与“近”无反义关系，“硬”指质地坚硬。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示两个东西离得不远。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "我家离学校很近。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里离地铁站近，上班很方便。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司离我家不近，我坐车去。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请坐近一点，我听不清。", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住得离我很近，我们常见面。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家离公园很近，走路五分钟。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个离公司近的房子。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆离我们很近，走五分钟就到。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校离家近，他每天走路回家。", "target_word": "近", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你家离海近不近？", "target_word": "近", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "近一点", "label": "复合"}, {"form": "附近", "label": "复合"}], "register": "中性", "sense_fingerprint": "空间上两处距离短，不远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9fe1e84-341e-4afc-b28f-a4b71a6d4ab1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示空间上距离不远。"}, {"text": "紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧密、紧张。"}, {"text": "信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示空间上距离不远。", "紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是紧密、紧张。", "信": "xìn 与 jìn 声母不同（x 与 j），意思是信件、相信。", "静": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是安静。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“离学校很近”表示距离不远，符合语境。"}, {"text": "大", "is_correct": false, "explanation": "搭配：“离……很大”不能用来描述距离。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”形容光线，不能用来形容距离。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”形容质地，与距离无关。"}], "explanations": {"近": "正确：“离学校很近”表示距离不远，符合语境。", "大": "搭配：“离……很大”不能用来描述距离。", "亮": "语义：“亮”形容光线，不能用来形容距离。", "硬": "语义：“硬”形容质地，与距离无关。"}, "sentence_index": 0, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆离我家很近，坐飞机要三个小时才能到。", "explanation": "这里应该用〈远〉。“很近”与“坐飞机要三个小时才能到”矛盾，说明距离远，要用〈远〉。"}, {"text": "他的态度很近，大家都不喜欢他。", "explanation": "这里应该用〈亲切〉。“近”不能形容态度，表示态度友好要用〈亲切〉。"}, {"text": "这家店离我家近，所以我每天要坐两个小时的车去。", "explanation": "这里应该用〈远〉。“近”与“坐两个小时的车”矛盾，需要长时间乘车说明距离远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”读 jìn（第四声），表示空间上距离不远。"}, {"text": "今", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。"}, {"text": "俊", "is_correct": false, "explanation": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。"}, {"text": "敬", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。"}, {"text": "镜", "is_correct": false, "explanation": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}], "explanations": {"近": "正确：“近”读 jìn（第四声），表示空间上距离不远。", "今": "jīn（第一声）与 jìn（第四声）声调不同，意思是今天。", "俊": "jùn 与 jìn 韵母不同（-un 与 -in），意思是英俊。", "敬": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是尊敬。", "镜": "jìng 与 jìn 韵母不同（-ng 与 -n），意思是镜子。"}, "sentence_index": null, "correct_answer": "近"}, "level_3": {"options": [{"text": "近", "is_correct": true, "explanation": "正确：“离公司近的房子”指房子距离公司不远，符合语境。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“离……高”不能用来描述距离。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，与距离无关。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”形容质地，与距离无关。"}], "explanations": {"近": "正确：“离公司近的房子”指房子距离公司不远，符合语境。", "高": "搭配：“离……高”不能用来描述距离。", "白": "语义：“白”指颜色，与距离无关。", "软": "语义：“软”形容质地，与距离无关。"}, "sentence_index": 6, "correct_answer": "近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的房子离学校很近，要走一整天才能到。", "explanation": "这里应该用〈远〉。“很近”与“要走一整天才能到”矛盾，说明距离远，要用〈远〉。"}, {"text": "他的脾气很近，大家都愿意和他玩。", "explanation": "这里应该用〈温和〉。“近”形容距离，不能形容脾气。"}, {"text": "你家离海近，要坐一个月的船才能到。", "explanation": "这里应该用〈远〉。“近”与“坐一个月的船”矛盾，需要长时间航行说明距离远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店离地铁站近很。", "corrected_sentence": "这家书店离地铁站很近。", "error_description": "错误形式“近很”，正确形式“很近”。“很”作状语，应放在形容词“近”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他住的地方离车站近很。", "corrected_sentence": "他住的地方离车站近得很。", "error_description": "错误形式“近很”，“很”作补语时须用“得”连接，应为“近得很”。错误在于缺少“得”，其余部分不变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24c8d861-6dc7-491a-9eaa-4641bca4a885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "下降：与“升高”反义，指位置向下移动，与句中火箭向上移动相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与“升高”没有反义关系，只是普通动词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与“升高”没有反义关系，二者不构成对立。"}, {"text": "写信", "is_correct": false, "explanation": "写信与“升高”没有反义关系，二者不构成对立。"}], "correct_answer": "下降", "explanations": {"下降": "下降：与“升高”反义，指位置向下移动，与句中火箭向上移动相反。", "唱歌": "唱歌与“升高”没有反义关系，只是普通动词。", "睡觉": "睡觉与“升高”没有反义关系，二者不构成对立。", "写信": "写信与“升高”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "下降：与“升高”反义，指位置向下移动，与句中小鸟向上飞相反。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与“升高”没有反义关系，只是普通动词。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与“升高”没有反义关系，二者不构成对立。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡与“升高”没有反义关系，二者不构成对立。"}], "correct_answer": "下降", "explanations": {"下降": "下降：与“升高”反义，指位置向下移动，与句中小鸟向上飞相反。", "跑步": "跑步与“升高”没有反义关系，只是普通动词。", "吃饭": "吃饭与“升高”没有反义关系，二者不构成对立。", "洗澡": "洗澡与“升高”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变高，往上走。", "primary_collocate": null, "pronunciation": "shēng gāo", "ipa": "ʂɤŋ˥ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "气球慢慢升高，飞到了天上。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳升高以后，天气热起来了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机升高以后，云在脚下。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭升高的时候，声音很大。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水位升高了，河边的路不能走了。", "target_word": "升高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "座椅慢慢升高了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮升高了，院子里更亮了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟慢慢升高，最后看不见了。", "target_word": "升高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风筝升高以后，我们就看不清它了。", "target_word": "升高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟升高后停在树上。", "target_word": "升高", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "升高了", "label": "完成体"}, {"form": "升高过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "升高：物体的位置向上移动、变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd209268f-53f6-4de8-8192-9154cf70cf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：气球向上移动、位置变高，符合句意。"}, {"text": "下沉", "is_correct": false, "explanation": "语义：“下沉”与后句“飞到了天上”方向相反，句子不成立。"}, {"text": "长高", "is_correct": false, "explanation": "搭配：“长高”只说人或植物的身高，不能用于气球。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：气球不会唱歌，与句子描写的运动不符。"}], "explanations": {"升高": "升高：气球向上移动、位置变高，符合句意。", "下沉": "语义：“下沉”与后句“飞到了天上”方向相反，句子不成立。", "长高": "搭配：“长高”只说人或植物的身高，不能用于气球。", "唱歌": "语义：气球不会唱歌，与句子描写的运动不符。"}, "sentence_index": 0, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今年又升高了五厘米。", "explanation": "这里应该用〈长高〉。人的身高增加说长高，升高不用于人的身体高度。"}, {"text": "这双鞋能让我升高五厘米。", "explanation": "这里应该用〈增高〉。鞋垫或高跟鞋让人显得更高说增高，升高指物体往上走，不用于人体的高度增加。"}, {"text": "他升高了手，要回答问题。", "explanation": "这里应该用〈举起〉。人用手向上抬起时说举起，升高不用于人的肢体动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升高", "is_correct": true, "explanation": "升高：月亮向上移动、位置变高，符合句意。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：月亮不会跳舞，与“院子里更亮了”的描写不相关。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，不用于天体的位置变化。"}, {"text": "散步", "is_correct": false, "explanation": "语义：月亮不会散步，句子描写的是月亮位置的变化。"}], "explanations": {"升高": "升高：月亮向上移动、位置变高，符合句意。", "跳舞": "语义：月亮不会跳舞，与“院子里更亮了”的描写不相关。", "生长": "搭配：“生长”用于生物，不用于天体的位置变化。", "散步": "语义：月亮不会散步，句子描写的是月亮位置的变化。"}, "sentence_index": 6, "correct_answer": "升高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他升高了脚步，走进了屋子。", "explanation": "这里应该用〈加快〉。升高指物体向上移动，脚步快慢的变化要说加快。"}, {"text": "一阵风升高了窗帘。", "explanation": "这里应该用〈掀起〉。风把窗帘吹起时说掀起，升高不用于这种动作。"}, {"text": "她升高着围巾向我们打招呼。", "explanation": "这里应该用〈挥舞〉。人用手左右或上下摆动物件时说挥舞，升高不用于这种动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "热气球慢慢升高的了。", "corrected_sentence": "热气球慢慢升高了。", "error_description": "错误形式：“升高的了”；正确形式：“升高了”（句中“慢慢”保留不动）。“的”多余，完成体“了”应直接接在动补结构“升高”之后，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "热气球升高的很快。", "corrected_sentence": "热气球升高得很快。", "error_description": "错误形式：“升高的很快”；正确形式：“升高得很快”。表示程度的补语前要用结构助词“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757b3138-a62b-4602-b9a4-bfcdddc9fd8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
