INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体挡住打来、砸下或飞来的东西。", "primary_collocate": null, "pronunciation": "kàng", "ipa": "kʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他抬起手，抗住了飞来的球。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用背抗住了砸下来的树枝。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用胳膊抗了一下，没有受伤。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打过来，我用手抗了一下。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头掉下来，他用肩膀抗住了。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳头打来，他用手臂抗住，没有后退。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石子飞到脸上，她用手抗着。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弯下腰，用背抗住了落下的雪块。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个瓶子飞过来，他侧身用肩膀抗了一下。", "target_word": "抗", "complexity_tier": "T3", "furigana": "nà gè píngzi fēi guòlái, tā cè shēn yòng jiānbǎng kàng le yīxià.", "sentence_source": "generated"}, {"text": "球飞过来，他用身体抗着，把孩子护在后面。", "target_word": "抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗着", "label": "体标"}, {"form": "抗了", "label": "体标"}, {"form": "抗住", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词；用手、背、肩等身体部位挡住打来或飞来的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c35ae327-211b-4fbe-844b-b4c09f23498b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“抗”（kàng）是本词，指用身体挡住打来或飞来的东西。"}, {"text": "扛", "is_correct": false, "explanation": "扛（káng）与抗（kàng）声调不同，意思是用肩膀承担。"}, {"text": "康", "is_correct": false, "explanation": "康（kāng）与抗（kàng）声调不同，意思是健康。"}, {"text": "看", "is_correct": false, "explanation": "看（kàn）与抗（kàng）韵尾不同，一个是 n，一个是 ng，意思是观看。"}, {"text": "糠", "is_correct": false, "explanation": "糠（kāng）与抗（kàng）声调不同，意思是谷物脱下的皮。"}, {"text": "杠", "is_correct": false, "explanation": "杠（gàng）与抗（kàng）声母不同（g 与 k），意思是杠杆。"}], "explanations": {"抗": "正确：“抗”（kàng）是本词，指用身体挡住打来或飞来的东西。", "扛": "扛（káng）与抗（kàng）声调不同，意思是用肩膀承担。", "康": "康（kāng）与抗（kàng）声调不同，意思是健康。", "看": "看（kàn）与抗（kàng）韵尾不同，一个是 n，一个是 ng，意思是观看。", "糠": "糠（kāng）与抗（kàng）声调不同，意思是谷物脱下的皮。", "杠": "杠（gàng）与抗（kàng）声母不同（g 与 k），意思是杠杆。"}, "sentence_index": null, "correct_answer": "抗"}, "level_3": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“抗住了飞来的球”指用身体挡住飞来的球，符合语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛出去，与“抗住”挡住飞来之物的动作正好相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱住了球”不成立，唱歌与挡球的动作毫无关系。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃住了球”不成立，“吃”与挡住飞来物体的动作不搭。"}], "explanations": {"抗": "正确：“抗住了飞来的球”指用身体挡住飞来的球，符合语境。", "扔": "语义：“扔”是抛出去，与“抗住”挡住飞来之物的动作正好相反。", "唱": "搭配：“唱住了球”不成立，唱歌与挡球的动作毫无关系。", "吃": "搭配：“吃住了球”不成立，“吃”与挡住飞来物体的动作不搭。"}, "sentence_index": 0, "correct_answer": "抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一块石头抗进了河里。", "explanation": "这里应该用〈扔〉。抗指用身体挡住飞来的东西，把石头投进河里要用扔。"}, {"text": "他抗了抗脸上的汗。", "explanation": "这里应该用〈擦〉。抗表示用身体挡住飞来的东西，擦去脸上的汗要用擦。"}, {"text": "他伸手抗下了那个开关。", "explanation": "这里应该用〈按〉。抗表示用身体挡住飞来的东西，按下开关要用按。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗", "is_correct": true, "explanation": "正确：“她用手抗着”指用手挡住飞来的石子，符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“她用手写着”指用手写字，与石子飞到脸上的动作无关。"}, {"text": "数", "is_correct": false, "explanation": "语义：“她用手数着”指用手计数，与石子飞到脸上的情境不合。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”要用嘴，“用手吞着”不通。"}], "explanations": {"抗": "正确：“她用手抗着”指用手挡住飞来的石子，符合语境。", "写": "语义：“她用手写着”指用手写字，与石子飞到脸上的动作无关。", "数": "语义：“她用手数着”指用手计数，与石子飞到脸上的情境不合。", "吞": "搭配：“吞”要用嘴，“用手吞着”不通。"}, "sentence_index": 6, "correct_answer": "抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抗了一封长信。", "explanation": "这里应该用〈写〉。抗表示用身体挡住飞来的东西，写信要用写。"}, {"text": "他用力抗开了门，走了出去。", "explanation": "这里应该用〈推〉。抗表示用身体挡住，推开门要用推。"}, {"text": "他一脚抗开了石头。", "explanation": "这里应该用〈踢〉。抗是用身体挡住，用脚把石头踢开要用踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他伸手抗了住那只飞来的石块。", "corrected_sentence": "他伸手抗住了那只飞来的石块。", "error_description": "错误：“了”放在“抗”和“住”之间，位置错误。正确：补语“住”之后加“了”，写作“抗住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用背很抗住了那颗石子。", "corrected_sentence": "他用背抗住了那颗石子。", "error_description": "错误：程度副词“很”插在“用背”和“抗住”之间，不能修饰动补结构，多加了“很”。正确：去掉“很”，写作“他用背抗住了那颗石子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f297c200-563f-485a-b219-c2eccb874135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20458, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生理性", "is_correct": true, "explanation": "生理性指身体正常的功能和反应，与“病理性”相对，符合句中的语境。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与病理性没有反义关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓形容速度慢，与病理性不构成反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "丰富形容数量多或内容多，与病理性无关，不是它的反义词。"}], "correct_answer": "生理性", "explanations": {"生理性": "生理性指身体正常的功能和反应，与“病理性”相对，符合句中的语境。", "明亮": "明亮形容光线或颜色，与病理性没有反义关系。", "迟缓": "迟缓形容速度慢，与病理性不构成反义关系。", "丰富": "丰富形容数量多或内容多，与病理性无关，不是它的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
