INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "药物是能治病的药。", "primary_collocate": null, "pronunciation": "yào wù", "ipa": "iɑʊ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "研究人员研发了一种新药物。", "target_word": "药物", "complexity_tier": "T3", "furigana": "yán jiū rén yuán yán fā le yī zhǒng xīn yào wù", "sentence_source": "generated"}, {"text": "这种药物一天吃两次。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些药物会让人想睡觉。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不能乱用药物。", "target_word": "药物", "complexity_tier": "T3", "furigana": "hái zi bù néng luàn yòng yào wù", "sentence_source": "generated"}, {"text": "使用药物以前，要先看说明书。", "target_word": "药物", "complexity_tier": "T3", "furigana": "shǐ yòng yào wù yǐ qián, yào xiān kàn shuō míng shū", "sentence_source": "generated"}, {"text": "这家医院有很多治感冒的药物。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这种药物过敏。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药物要放在孩子拿不到的地方。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药物的价格不太贵。", "target_word": "药物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天要服用好几种药物。", "target_word": "药物", "complexity_tier": "T3", "furigana": "lǎo rén měi tiān yào fú yòng hǎo jǐ zhǒng yào wù", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种药物", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，用来治病的药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "药物", "is_correct": true, "explanation": "正确：“药物”是可以治病的物质，能够被研发，与“一种新”搭配自然。"}, {"text": "论文", "is_correct": false, "explanation": "语义：“论文”是写出来的文章，不能被研发。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“研发”多用于技术、产品，与“歌曲”搭配不当。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：“房屋”是建造出来的，不能说“研发”。"}], "explanations": {"药物": "正确：“药物”是可以治病的物质，能够被研发，与“一种新”搭配自然。", "论文": "语义：“论文”是写出来的文章，不能被研发。", "歌曲": "搭配：“研发”多用于技术、产品，与“歌曲”搭配不当。", "房屋": "语义：“房屋”是建造出来的，不能说“研发”。"}, "sentence_index": 0, "correct_answer": "药物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药物是用来做饭的。", "explanation": "这里应该用〈调料〉。“药物”指治病的药，不用于做饭的调味品；做饭用的东西要说“调料”。"}, {"text": "他刚买了一片药物。", "explanation": "这里应该用〈种〉。“药物”泛指药用物质，量词用“种”；“片”用于药片，不用于泛指的药物。"}, {"text": "他用药物擦干净了桌子。", "explanation": "这里应该用〈清洁剂〉。擦洗用的东西要说“清洁剂”，“药物”指治病的药，不用于清洁桌面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药物", "is_correct": true, "explanation": "正确：“药物”是药用物质，人可以对它过敏，与“这种”和“过敏”搭配自然。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：这里的“过敏”指对物质的身体反应，不能对“朋友”过敏。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不会引起过敏反应，不能作为过敏的对象。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“过敏”通常与物质、食物搭配，不与“作业”搭配。"}], "explanations": {"药物": "正确：“药物”是药用物质，人可以对它过敏，与“这种”和“过敏”搭配自然。", "朋友": "语义：这里的“过敏”指对物质的身体反应，不能对“朋友”过敏。", "窗户": "语义：“窗户”不会引起过敏反应，不能作为过敏的对象。", "作业": "搭配：“过敏”通常与物质、食物搭配，不与“作业”搭配。"}, "sentence_index": 6, "correct_answer": "药物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家药物监督管理局发布了新规定。", "explanation": "这里应该用〈药品〉。“药品监督管理局”是固定的机构名称，“药物”不用于这一说法。"}, {"text": "妈妈给孩子倒了一小杯药物。", "explanation": "这里应该用〈药水〉。液体药应说“药水”，“药物”泛指药用物质，不用来指杯中的液体。"}, {"text": "他饭后吃了一粒药物。", "explanation": "这里应该用〈药丸〉。做成丸状、可以计数的药说“药丸”，“药物”泛指药用物质，不说“一粒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生开了一片新药物给病人。", "corrected_sentence": "医生开了一种新药物给病人。", "error_description": "错误在于量词：“药物”是泛指的药用物质，量词应用“种”。写成“一片新药物”是错的，正确说法是“一种新药物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈对这些药物们过敏。", "corrected_sentence": "妈妈对这些药物过敏。", "error_description": "错误在于复数词尾：“药物”是泛称，不能加“们”，应说“对这些药物过敏”，不说“对这些药物们过敏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
