INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医生给病人看病。", "primary_collocate": null, "pronunciation": "lín chuáng", "ipa": "lin˧˥ ʈʂʰuaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他是医生，每天都在医院做临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实习医生每天都跟着老师学临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想做研究，只想做临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临床就是医生给病人看病。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大医院做了十年临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临床很忙，医生常常没时间吃饭。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做临床的医生，每天要看很多病人。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起写文章，他更喜欢做临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临床让年轻医生学到了很多东西。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在医院工作，做的是临床。", "target_word": "临床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨床", "label": "繁体"}, {"form": "临床医学", "label": "复合"}, {"form": "临床试验", "label": "复合"}], "register": "中性", "sense_fingerprint": "临床：医生在医院里给病人看病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临床", "is_correct": true, "explanation": "正确。“做临床”指医生在医院给病人看病，符合句子语境。"}, {"text": "农活", "is_correct": false, "explanation": "语义：医生在医院里不做农活，与句子的身份不符。"}, {"text": "木工", "is_correct": false, "explanation": "语义：医生的工作不是木工，“每天都在医院做木工”不合常理。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“做作业”通常指学生的学习任务，不能用于医生的工作。"}], "explanations": {"临床": "正确。“做临床”指医生在医院给病人看病，符合句子语境。", "农活": "语义：医生在医院里不做农活，与句子的身份不符。", "木工": "语义：医生的工作不是木工，“每天都在医院做木工”不合常理。", "作业": "搭配：“做作业”通常指学生的学习任务，不能用于医生的工作。"}, "sentence_index": 0, "correct_answer": "临床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病人每天都在医院做临床，很辛苦。", "explanation": "这里用错了主体。“做临床”指医生给病人看病，主语应是〈医生〉，病人不能“做临床”。"}, {"text": "周末我常去临床看书。", "explanation": "这里用错了词义。临床指看病的工作，不是地点，这里应该用〈图书馆〉。"}, {"text": "他在法院做临床，每天审案子。", "explanation": "这里用错了范围。临床只指医生给病人看病，法院审案不属于临床，应说〈审判〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临床", "is_correct": true, "explanation": "正确。“做临床的医生”指给病人看病的医生，符合“看很多病人”。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：裁缝不会每天看很多病人，与句子的工作内容不合。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：饲养动物与看很多病人的工作内容不合。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“做游戏”指娱乐活动，不能与“做……的医生”搭配。"}], "explanations": {"临床": "正确。“做临床的医生”指给病人看病的医生，符合“看很多病人”。", "裁缝": "语义：裁缝不会每天看很多病人，与句子的工作内容不合。", "饲养": "语义：饲养动物与看很多病人的工作内容不合。", "游戏": "搭配：“做游戏”指娱乐活动，不能与“做……的医生”搭配。"}, "sentence_index": 6, "correct_answer": "临床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐在学校做的是临床，每天上课。", "explanation": "这里用错了地点。临床指在医院给病人看病的工作，在学校上课不属于临床，应说〈教学〉。"}, {"text": "我姐姐得了临床，要住院治疗。", "explanation": "这里用错了类别。临床是工作，不是病名，不能说“得了临床”。"}, {"text": "我姐姐每周三去医院看临床，很忙。", "explanation": "这里用错了词义。临床指医生给病人看病的工作，是“做”的对象，不能“看”，这里应该用〈门诊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还没做过临床了。", "corrected_sentence": "他还没做过临床。", "error_description": "“还没……过”后不能再加“了”，应说“他还没做过临床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐在医院做过一个临床，很辛苦。", "corrected_sentence": "我姐姐在医院做过临床，很辛苦。", "error_description": "“临床”是不可数的医疗实践，不能用量词“个”修饰，应说“做过临床”，不能说“做过一个临床”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
