INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "光碰到东西会弹回来。", "primary_collocate": null, "pronunciation": "fǎn shè", "ipa": "fan˨˩˦ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "光碰到镜子会反射回来。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平静的水面反射出树的影子。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃反射着路灯的光。", "target_word": "反射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属表面反射的光很亮。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白纸能反射大部分光。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手电筒的光在墙上反射了一下。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑色的东西很少反射光。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳照在海面，海水反射出金光。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼镜片反射出窗外的景色。", "target_word": "反射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的路面反射着灯光。", "target_word": "反射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反射了", "label": "体标"}, {"form": "反射着", "label": "体标"}, {"form": "反射过", "label": "体标"}, {"form": "反射镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，光碰到物体后弹回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反射", "is_correct": true, "explanation": "“反射”指光碰到镜子后弹回，与“回来”搭配，只有“反射”能填入。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：“吸收”是把光留在物体里，与“回来”的意思矛盾。"}, {"text": "抛出", "is_correct": false, "explanation": "搭配：“抛出”后接“回来”不合语义，光不是被抛出的物体。"}, {"text": "发出", "is_correct": false, "explanation": "语义：镜子不会发出光，“发出回来”不成立。"}], "explanations": {"反射": "“反射”指光碰到镜子后弹回，与“回来”搭配，只有“反射”能填入。", "吸收": "语义：“吸收”是把光留在物体里，与“回来”的意思矛盾。", "抛出": "搭配：“抛出”后接“回来”不合语义，光不是被抛出的物体。", "发出": "语义：镜子不会发出光，“发出回来”不成立。"}, "sentence_index": 0, "correct_answer": "反射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "光线斜着穿过玻璃砖，会反射，方向变了。", "explanation": "这里应该用〈折射〉。光穿过玻璃砖等介质时方向改变，是折射；反射是光碰到表面弹回。"}, {"text": "导弹成功反射，击中了目标。", "explanation": "这里应该用〈发射〉。导弹是被送出去的，应该用发射；反射指光碰到表面弹回。"}, {"text": "他向目标反射了一枪。", "explanation": "这里应该用〈射击〉。射击指用枪向目标发射子弹；反射指光碰到东西弹回，不能用于开枪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反射", "is_correct": true, "explanation": "“反射”指黑色物体只把少量光弹回，与“很少”相合，只有“反射”能填入。"}, {"text": "照亮", "is_correct": false, "explanation": "搭配：“照亮”的宾语是地方或空间，不能直接接“光”作宾语。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与物体弹回光的意思不符。"}, {"text": "聆听", "is_correct": false, "explanation": "语义：“聆听”指用耳朵听，光不能被聆听。"}], "explanations": {"反射": "“反射”指黑色物体只把少量光弹回，与“很少”相合，只有“反射”能填入。", "照亮": "搭配：“照亮”的宾语是地方或空间，不能直接接“光”作宾语。", "拒绝": "语义：“拒绝”是不接受，与物体弹回光的意思不符。", "聆听": "语义：“聆听”指用耳朵听，光不能被聆听。"}, "sentence_index": 6, "correct_answer": "反射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这枚火箭今天在海南反射。", "explanation": "这里应该用〈发射〉。火箭是被送出去的，应该用发射；反射指光碰到表面弹回。"}, {"text": "妈妈把这个消息反射给了所有朋友。", "explanation": "这里应该用〈转告〉。转告指把消息传给别人；反射指光碰到东西弹回，不能用于传递消息。"}, {"text": "他在辩论中反射了对方的论点，赢得了掌声。", "explanation": "这里应该用〈反驳〉。反驳指用道理否定对方的论点；反射指光碰到东西弹回，不能用于辩论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月光照在河面上，会很反射出一片银光。", "corrected_sentence": "月光照在河面上，会反射出一片银光。", "error_description": "程度副词错误：“反射”是动作动词，不能受“很”修饰，应说“会反射出一片银光”，删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "白色的雪地能反射着大部分阳光。", "corrected_sentence": "白色的雪地能反射大部分阳光。", "error_description": "动态助词错误：“能”表示能力，后面的动词不能再带“着”，应说“能反射大部分阳光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
