INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不是，表示差得很远。", "primary_collocate": null, "pronunciation": "yuǎn fēi", "ipa": "ɥɛn˨˩˦ fei˥", "syllable_count": 2, "sentences": [{"text": "他的汉语水平远非完美。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事远非一天能做完。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的能力远非你说的那么强。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱远非生活的全部。", "target_word": "远非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这远非一个简单的问题。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的收成远非去年可比。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成绩好远非成功的唯一标准。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚远非白天那样安静。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的故事远非这几句话能讲完。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买一张票远非旅行的全部。", "target_word": "远非", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，书面，否定判断，表示与某种情况差得很远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示差得很远，与“完美”的否定语境相符。"}, {"text": "稍微", "is_correct": false, "explanation": "搭配：“完美”是绝对概念，不能用“稍微”修饰，“稍微完美”不通。"}, {"text": "有点", "is_correct": false, "explanation": "搭配：“有点”表示程度轻微，不能与“完美”搭配。"}, {"text": "略", "is_correct": false, "explanation": "语义：“略”表示轻微的程度，与“完美”的绝对意义相冲突。"}], "explanations": {"远非": "正确。“远非”表示差得很远，与“完美”的否定语境相符。", "稍微": "搭配：“完美”是绝对概念，不能用“稍微”修饰，“稍微完美”不通。", "有点": "搭配：“有点”表示程度轻微，不能与“完美”搭配。", "略": "语义：“略”表示轻微的程度，与“完美”的绝对意义相冲突。"}, "sentence_index": 0, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我远非懂英语，还懂法语。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示递进，“远非懂英语”与后文“还懂法语”前后矛盾，应说〈不仅〉。"}, {"text": "我家远非学校，所以我每天坐车上学。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "我的口语远非你，所以每次比赛都是我赢。", "explanation": "这里前后矛盾。“远非你”表示我远不如你，与“所以每次比赛都是我赢”的因果不合，应说〈远远超过你〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远非", "is_correct": true, "explanation": "正确。“远非”表示差得很远，与后文“成功的唯一标准”的否定语境相符。"}, {"text": "正是", "is_correct": false, "explanation": "语义：“正是”肯定“成绩好”就是唯一标准，与句子的否定判断相反。"}, {"text": "只是", "is_correct": false, "explanation": "搭配：“只是”表示仅仅如此，与“唯一标准”的强调意义搭配不通。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示仅仅是，肯定了“成绩好”的作用，与句子结论相反。"}], "explanations": {"远非": "正确。“远非”表示差得很远，与后文“成功的唯一标准”的否定语境相符。", "正是": "语义：“正是”肯定“成绩好”就是唯一标准，与句子的否定判断相反。", "只是": "搭配：“只是”表示仅仅如此，与“唯一标准”的强调意义搭配不通。", "不过": "语义：“不过”表示仅仅是，肯定了“成绩好”的作用，与句子结论相反。"}, "sentence_index": 6, "correct_answer": "远非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张票远非贵，我每次都买不起。", "explanation": "这里前后矛盾。“远非贵”表示不贵，与“我每次都买不起”矛盾，应说〈非常贵〉。"}, {"text": "我家远非机场，所以我们提前一天出发。", "explanation": "这里用错了词义。远非表示程度相差很大，不表示空间距离，这里应该用〈远离〉。"}, {"text": "他远非富有，所以每天都买名牌衣服。", "explanation": "这里前后矛盾。“远非富有”表示不富有，与“所以每天都买名牌衣服”的因果不合，应说〈非常富有〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事很远非简单。", "corrected_sentence": "这件事远非简单。", "error_description": "“远非”本身已表示程度，前面不能再加“很”，应说“远非简单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试远非很容易，我复习了很久。", "corrected_sentence": "这次考试远非容易，我复习了很久。", "error_description": "“远非”本身已表示程度，后面的形容词前不能再加“很”，应说“远非容易”，不能说“远非很容易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
