INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个整体，各部分连在一起。", "primary_collocate": null, "pronunciation": "yì tǐ", "ipa": "i˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这把刀的刀头和刀柄是一体的。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房和客厅连成一体，空间很大。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳舞时，她的动作和音乐融为一体。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的盖和杯身做成一体，不会丢。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和工厂已经合为一体，一起工作。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言要把听说读写看成一体。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天和海在远处连成一体，分不清边在哪里。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床和床头柜是一体的，不能分开买。", "target_word": "一体", "complexity_tier": "T3", "furigana": "yì tǐ", "sentence_source": "generated"}, {"text": "两个小镇的路连成一体，走起来很方便。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家心往一处想，成了真正的一体。", "target_word": "一体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一體", "label": "繁体"}, {"form": "一体化", "label": "复合"}], "register": "通用", "sense_fingerprint": "各部分连在一起成为一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20476, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一体", "is_correct": true, "explanation": "正确：「刀头和刀柄是一体的」表示两者连在一起成为整体。"}, {"text": "一面", "is_correct": false, "explanation": "语义：「一面」指一方、一侧，与刀头和刀柄连成一体的意思不符。"}, {"text": "一阵", "is_correct": false, "explanation": "搭配：“一阵”用于一段时间或一股风、声音等，不能用来说刀的两个部件。"}, {"text": "一地", "is_correct": false, "explanation": "搭配：「是一地的」不能用来说刀的两个部件。"}], "explanations": {"一体": "正确：「刀头和刀柄是一体的」表示两者连在一起成为整体。", "一面": "语义：「一面」指一方、一侧，与刀头和刀柄连成一体的意思不符。", "一阵": "搭配：“一阵”用于一段时间或一股风、声音等，不能用来说刀的两个部件。", "一地": "搭配：「是一地的」不能用来说刀的两个部件。"}, "sentence_index": 0, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们三个人一体去上学。", "explanation": "这里应该用〈一起〉。一体指连成整体的状态，不能作“一起”的副词，应说一起去。"}, {"text": "他的一体很强壮。", "explanation": "这里应该用〈身体〉。一体指连成的整体，不指人的身体。"}, {"text": "这份报告要看一体效果。", "explanation": "这里应该用〈整体〉。“看整体效果”中要说整体，一体不作修饰语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一体", "is_correct": true, "explanation": "正确：「天和海连成一体」表示两者连成一片，分不清边界，与句意相符。"}, {"text": "一格", "is_correct": false, "explanation": "语义：「一格」指一个方格，与天和海连在一起的景象不符。"}, {"text": "一座", "is_correct": false, "explanation": "语义：「一座」指山或建筑，不能用来说天和海。"}, {"text": "一排", "is_correct": false, "explanation": "搭配：「连成一排」指物体排列，不用于说天和海连在一起。"}], "explanations": {"一体": "正确：「天和海连成一体」表示两者连成一片，分不清边界，与句意相符。", "一格": "语义：「一格」指一个方格，与天和海连在一起的景象不符。", "一座": "语义：「一座」指山或建筑，不能用来说天和海。", "一排": "搭配：「连成一排」指物体排列，不用于说天和海连在一起。"}, "sentence_index": 6, "correct_answer": "一体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司已经一体，却互不往来。", "explanation": "这里应该用〈独立〉。一体指连成整体，“互不往来”说明两家公司彼此分开，应说独立。"}, {"text": "这支球队的队员很一体，每人各自为战。", "explanation": "这里应该用〈分散〉。一体指连在一起，“各自为战”说明队员彼此分开，应说分散。"}, {"text": "这两个国家一体，经常打仗。", "explanation": "这里应该用〈对立〉。一体指连成整体，不能用来形容互相对立的两国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把刀的刀头和刀柄连一体。", "corrected_sentence": "这把刀的刀头和刀柄连成一体。", "error_description": "“连成一体”是固定格式，“成”是结果补语，不能省略，应说「连成一体」，写成「连一体」缺少“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两块木板拼成一体地，很结实。", "corrected_sentence": "这两块木板拼成一体，很结实。", "error_description": "“一体”是名词性词语，“拼成一体”后不能加状语标记“地”，应说「拼成一体，很结实」，多出的“地”是误用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
