INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20478, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "效果很好，很有用。", "primary_collocate": null, "pronunciation": "qiáng xiào", "ipa": "tɕʰjɑŋ˧˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我买了一瓶强效保湿霜，用了一周皮肤就变好了。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效止咳糖浆，喝一口就舒服多了。", "target_word": "强效", "complexity_tier": "T3", "furigana": "qiáng xiào", "sentence_source": "generated"}, {"text": "妈妈用强效去污粉洗锅，锅一下子干净了。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖的强效防晒霜，去海边玩时很有用。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个强效办法，能让孩子很快睡着。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效清洁剂，擦桌子特别快。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天蚊子多，我们买了强效驱蚊水。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种强效退烧药，吃下去半个小时就见效了。", "target_word": "强效", "complexity_tier": "T3", "furigana": "qiáng xiào", "sentence_source": "generated"}, {"text": "这瓶强效洗发水对头皮屑很有用。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天手很干，这支强效护手霜马上就管用了。", "target_word": "强效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強效", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日用品或办法效果很好、很管用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强效", "is_correct": true, "explanation": "正确。强效，指效果很好、很管用。"}, {"text": "强笑", "is_correct": false, "explanation": "声调不同：「qiǎng」（第三声）与「qiáng」（第二声）不同，强笑指勉强地笑。"}, {"text": "长效", "is_correct": false, "explanation": "声母不同：「cháng」的 ch 与「qiáng」的 q 不同，长效指作用持久。"}, {"text": "降效", "is_correct": false, "explanation": "声母和声调都不同：「jiàng」的 j 与 q 不同，第四声与第二声也不同，降效指效率下降。"}, {"text": "轻笑", "is_correct": false, "explanation": "韵母不同：「qīng」与「qiáng」的 -ing／-ang 不同，声调也不同，轻笑指轻轻地笑。"}], "explanations": {"强效": "正确。强效，指效果很好、很管用。", "强笑": "声调不同：「qiǎng」（第三声）与「qiáng」（第二声）不同，强笑指勉强地笑。", "长效": "声母不同：「cháng」的 ch 与「qiáng」的 q 不同，长效指作用持久。", "降效": "声母和声调都不同：「jiàng」的 j 与 q 不同，第四声与第二声也不同，降效指效率下降。", "轻笑": "韵母不同：「qīng」与「qiáng」的 -ing／-ang 不同，声调也不同，轻笑指轻轻地笑。"}, "sentence_index": null, "correct_answer": "强效"}, "level_3": {"options": [{"text": "无效", "is_correct": false, "explanation": "语义：“无效”说没有效果，与后半句“皮肤就变好了”相矛盾。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“保湿霜”，指效果很好。"}, {"text": "强烈", "is_correct": false, "explanation": "搭配：“强烈”多修饰感觉、情绪、作用，不说保湿霜的效果。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：“有毒”会伤害皮肤，与“皮肤变好了”相矛盾。"}], "explanations": {"无效": "语义：“无效”说没有效果，与后半句“皮肤就变好了”相矛盾。", "强效": "正确。“强效”修饰“保湿霜”，指效果很好。", "强烈": "搭配：“强烈”多修饰感觉、情绪、作用，不说保湿霜的效果。", "有毒": "语义：“有毒”会伤害皮肤，与“皮肤变好了”相矛盾。"}, "sentence_index": 0, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体很强效，每天都能跑十公里。", "explanation": "这里应该用〈强健〉。身体的健壮要说强健，强效不用来形容人的身体素质。"}, {"text": "这杯茶的味道很强效，我喝不惯。", "explanation": "这里应该用〈浓〉。茶的浓淡、味道的厚薄要说浓；强效说的是药物、方法的效力，不用来形容茶的味道。"}, {"text": "他的表情很强效。", "explanation": "这里应该用〈严肃〉。表情、神态要说严肃，强效不用来形容表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容性情、语气、动作，不用来形容驱蚊水。"}, {"text": "强效", "is_correct": true, "explanation": "正确。“强效”修饰“驱蚊水”，说明驱蚊的效果很强。"}, {"text": "微弱", "is_correct": false, "explanation": "语义：“微弱”说作用小，与“蚊子多”、需要强效驱蚊的用途相矛盾。"}, {"text": "软弱", "is_correct": false, "explanation": "语义：“软弱”说力量不足，不能用来形容驱蚊水的效力。"}], "explanations": {"温柔": "搭配：“温柔”形容性情、语气、动作，不用来形容驱蚊水。", "强效": "正确。“强效”修饰“驱蚊水”，说明驱蚊的效果很强。", "微弱": "语义：“微弱”说作用小，与“蚊子多”、需要强效驱蚊的用途相矛盾。", "软弱": "语义：“软弱”说力量不足，不能用来形容驱蚊水的效力。"}, "sentence_index": 6, "correct_answer": "强效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很强效。", "explanation": "这里应该用〈坚硬〉。物体的硬度要说坚硬，强效不用来形容物体的质地。"}, {"text": "他的声音很强效。", "explanation": "这里应该用〈响亮〉。声音的大小要说响亮，强效不用来形容声音。"}, {"text": "他的脾气很强效。", "explanation": "这里应该用〈暴躁〉。脾气、性情要说暴躁，强效不用来形容人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一瓶强效地洗洁精，油污很快就没了。", "corrected_sentence": "妈妈买了一瓶强效洗洁精，油污很快就没了。", "error_description": "错误：“强效地洗洁精”，多加了“地”。强效直接修饰名词，不加“地”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皮肤过敏时，医生开了一根强效药膏。", "corrected_sentence": "皮肤过敏时，医生开了一管强效药膏。", "error_description": "错误：量词「根」用于细长的条状物，药膏应用量词「管」。正确形式：一管强效药膏。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意识", "is_correct": true, "explanation": "反义词：“有意识”指做事时知道自己在做什么，与“无意识”相对。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容头脑好，与“无意识”没有对应的相对关系。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”形容声音或环境，与“无意识”的意思无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线或颜色，与“无意识”的意思无关。"}], "correct_answer": "有意识", "explanations": {"有意识": "反义词：“有意识”指做事时知道自己在做什么，与“无意识”相对。", "聪明": "无反义关系：“聪明”形容头脑好，与“无意识”没有对应的相对关系。", "安静": "无反义关系：“安静”形容声音或环境，与“无意识”的意思无关。", "明亮": "无反义关系：“明亮”形容光线或颜色，与“无意识”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意识", "is_correct": true, "explanation": "反义词：“有意识”指做事时知道自己在做什么，与“无意识”相对。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：“勇敢”形容不怕困难或危险，与“无意识”无对应关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”形容明白、不模糊，与“无意识”没有相对关系。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”形容场面喧哗，与“无意识”的意思无关。"}], "correct_answer": "有意识", "explanations": {"有意识": "反义词：“有意识”指做事时知道自己在做什么，与“无意识”相对。", "勇敢": "无反义关系：“勇敢”形容不怕困难或危险，与“无意识”无对应关系。", "清楚": "无反义关系：“清楚”形容明白、不模糊，与“无意识”没有相对关系。", "热闹": "无反义关系：“热闹”形容场面喧哗，与“无意识”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情的时候，自己不知道自己在做什么。", "primary_collocate": null, "pronunciation": "wú yì shí", "ipa": "u˧˥ i˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "他一边看手机，一边无意识地吃完了饭。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无意识地走到了老家的门口。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开会时无意识地一直转笔。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时，他无意识地踩了刹车。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎么回事，无意识地就点了头。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想着心事，无意识地走错了路。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电视时，她无意识地吃了一大包薯片。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无意识地把盐当成糖放进了茶里。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐的时候，我无意识地跟着唱起来。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得无意识地一直重复同一句话。", "target_word": "无意识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无意识地", "label": "复合"}, {"form": "無意識", "label": "繁体"}], "register": "通用", "sense_fingerprint": "做事时自己不知道自己在做什么，不自觉地做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "正确。句中“一边看手机”说明他没有留意自己在吃饭，符合“不知道自己在做什么”。"}, {"text": "专心", "is_correct": false, "explanation": "语义：“专心”指注意力集中，与“一边看手机”矛盾。"}, {"text": "仔细", "is_correct": false, "explanation": "语义：“仔细地”说明吃得留心，与边看手机边吃饭的情境不合。"}, {"text": "生动", "is_correct": false, "explanation": "搭配：“生动”形容语言、表情等，不用来修饰吃饭的动作。"}], "explanations": {"无意识": "正确。句中“一边看手机”说明他没有留意自己在吃饭，符合“不知道自己在做什么”。", "专心": "语义：“专心”指注意力集中，与“一边看手机”矛盾。", "仔细": "语义：“仔细地”说明吃得留心，与边看手机边吃饭的情境不合。", "生动": "搭配：“生动”形容语言、表情等，不用来修饰吃饭的动作。"}, "sentence_index": 0, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无意识地制定了一个详细的计划。", "explanation": "这里应该用〈有意识〉。制定计划需要清楚地思考，而“无意识”指做事时自己不知道在做什么。"}, {"text": "她无意识地把门关上，不让我进去。", "explanation": "这里应该用〈故意〉。“不让我进去”说明动作有目的，不能用“无意识”来描述。"}, {"text": "为了考试及格，他无意识地复习了三天。", "explanation": "这里应该用〈故意〉。“为了考试及格”说明复习是有目的的行为，要说“故意”复习，不能用“无意识地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无意识", "is_correct": true, "explanation": "正确。“看电视时”说明她的注意力在电视上，吃薯片是不知不觉的。"}, {"text": "适量", "is_correct": false, "explanation": "语义：“适量”说分量合适，与“一大包”矛盾。"}, {"text": "文雅", "is_correct": false, "explanation": "搭配：“文雅”形容举止，不用来修饰大口吃薯片的动作。"}, {"text": "有节制", "is_correct": false, "explanation": "语义：“有节制”表示克制，与“吃了一大包薯片”矛盾。"}], "explanations": {"无意识": "正确。“看电视时”说明她的注意力在电视上，吃薯片是不知不觉的。", "适量": "语义：“适量”说分量合适，与“一大包”矛盾。", "文雅": "搭配：“文雅”形容举止，不用来修饰大口吃薯片的动作。", "有节制": "语义：“有节制”表示克制，与“吃了一大包薯片”矛盾。"}, "sentence_index": 6, "correct_answer": "无意识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她无意识地准备了一桌好菜。", "explanation": "这里应该用〈精心〉。准备一桌好菜需要有意识地安排，不能说“无意识地”准备。"}, {"text": "她无意识地报名参加了马拉松比赛。", "explanation": "这里应该用〈故意〉。报名是自己有意做出的决定，不能说“无意识地”报名。"}, {"text": "他无意识地写下了一封正式的辞职信。", "explanation": "这里应该用〈有意识〉。写辞职信需要清楚地考虑，应说“有意识地”写；“无意识”指做事时自己不知道在做什么。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她无意识的打开了电视。", "corrected_sentence": "她无意识地打开了电视。", "error_description": "“无意识的打开”应为“无意识地打开”。“无意识”修饰动词“打开”，作状语要用“地”；“的”一般用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无意识的关上了门。", "corrected_sentence": "他无意识地关上了门。", "error_description": "“无意识”修饰动词“关上”，作状语要用“地”，应说“无意识地关上了门”；此处误用“的”，“的”一般用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
