INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "每天都有的、平常的。", "primary_collocate": null, "pronunciation": "rì cháng", "ipa": "ɻ̩˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的日常工作是照顾小孩。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢这种安静的日常生活。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机已经是我们日常生活的一部分。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记是她的日常习惯。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说日常饮食要少吃盐。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些日常用品超市里都有。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语不难，日常对话我已经能听懂了。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天做饭、洗衣服，日常家务都是他做。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们一些日常用语。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用照片记录日常生活。", "target_word": "日常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常生活", "label": "复合"}, {"form": "日常用品", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容每天都有的、平常的事情或生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常”指每天都有的、平常的，即目标义项。"}, {"text": "热肠", "is_correct": false, "explanation": "最小对立：rè 与 rì 仅韵母不同（e/i），声调相同；“热肠”指热心肠，不是同义词。"}, {"text": "时常", "is_correct": false, "explanation": "“时常”（shícháng）第一个音节声母为 sh 且声调不同，意思是经常。"}, {"text": "异常", "is_correct": false, "explanation": "最小对立：yì 与 rì 仅声母不同（零声母与 r），声调相同；“异常”指不正常。"}], "explanations": {"日常": "正确：“日常”指每天都有的、平常的，即目标义项。", "热肠": "最小对立：rè 与 rì 仅韵母不同（e/i），声调相同；“热肠”指热心肠，不是同义词。", "时常": "“时常”（shícháng）第一个音节声母为 sh 且声调不同，意思是经常。", "异常": "最小对立：yì 与 rì 仅声母不同（零声母与 r），声调相同；“异常”指不正常。"}, "sentence_index": null, "correct_answer": "日常"}, "level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常”修饰“工作”，表示每天都做的工作，符合语境。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”说的是形状，不能用来修饰“工作”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不能修饰“工作”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“工作”。"}], "explanations": {"日常": "正确：“日常”修饰“工作”，表示每天都做的工作，符合语境。", "圆形": "语义：“圆形”说的是形状，不能用来修饰“工作”。", "高大": "体貌：“高大”形容人或物的身材，不能修饰“工作”。", "雪白": "搭配：“雪白”形容颜色，不能修饰“工作”。"}, "sentence_index": 0, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日常去图书馆。", "explanation": "这里应该用〈经常〉。“日常”是形容词，修饰名词，不能当副词表示频率。"}, {"text": "这次去海边的旅行是我的日常。", "explanation": "这里误把〈日常〉当作“经历”的意思；“日常”指每天都要做的事，与“这次”的一次性旅行矛盾，应说〈经历〉。"}, {"text": "我买了一瓶日常。", "explanation": "这里应该用〈日常用品〉。“日常”是形容词，不能单独作名词使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日常", "is_correct": true, "explanation": "正确：“日常对话”指日常生活中的交流，符合“学汉语不难”的语境。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”形容距离或时间，与“日常对话”的语境不符。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不能修饰“对话”。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”形容物体表面，不能修饰“对话”。"}], "explanations": {"日常": "正确：“日常对话”指日常生活中的交流，符合“学汉语不难”的语境。", "遥远": "语义：“遥远”形容距离或时间，与“日常对话”的语境不符。", "滚烫": "搭配：“滚烫”形容温度，不能修饰“对话”。", "光滑": "搭配：“光滑”形容物体表面，不能修饰“对话”。"}, "sentence_index": 6, "correct_answer": "日常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他日常很少生病。", "explanation": "这里应该用〈平常〉。“日常”是形容词，不能当副词使用。"}, {"text": "这份合同的日常写错了。", "explanation": "这里应该用〈日期〉。“日常”指每天都要做的事，合同上的时间要用“日期”。"}, {"text": "我日常去超市买东西。", "explanation": "这里应该用〈常常〉。“日常”是形容词，不能当副词表示频率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很重视日常得锻炼。", "corrected_sentence": "他很重视日常锻炼。", "error_description": "结构助词误用：“日常”作定语修饰“锻炼”时不能加“得”，应说“日常锻炼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了几双日常用品。", "corrected_sentence": "我买了几件日常用品。", "error_description": "量词错误：“日常用品”用量词“件”，“双”只用于成对的东西，不能用于“用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
