INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体或身体各个部分的工作情况。", "primary_collocate": null, "pronunciation": "shēng lǐ", "ipa": "ʂɤŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的生理年龄比实际年龄小。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生理健康和心理健康一样重要。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孕妇的生理状况会有变化。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了她的生理指标。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人在紧张时，生理上会出汗。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡眠不足会影响生理节奏。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些生理数据都很正常。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年纪大了，生理功能会变差。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员的生理条件很重要。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的生理状态比昨天好多了。", "target_word": "生理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生理学", "label": "复合"}, {"form": "生理盐水", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指身体或身体各部分的工作状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc079313-b059-4b08-b230-4615d2aa1d74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生理", "is_correct": true, "explanation": "生理：身体或身体各部分的工作情况，就是这里要选的词。"}, {"text": "生梨", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，“生梨”指没有煮过的梨，意思不同。"}, {"text": "升力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，“升力”指使物体向上的力，意思不同。"}, {"text": "省力", "is_correct": false, "explanation": "shěng lì 两个音节的声调都与 shēng lǐ 不同，“省力”指节省力气。"}, {"text": "胜利", "is_correct": false, "explanation": "shèng lì 两个音节的声调都与 shēng lǐ 不同，“胜利”指战胜对手或取得成功。"}], "explanations": {"生理": "生理：身体或身体各部分的工作情况，就是这里要选的词。", "生梨": "lí（第二声）与 lǐ（第三声）声调不同，“生梨”指没有煮过的梨，意思不同。", "升力": "lì（第四声）与 lǐ（第三声）声调不同，“升力”指使物体向上的力，意思不同。", "省力": "shěng lì 两个音节的声调都与 shēng lǐ 不同，“省力”指节省力气。", "胜利": "shèng lì 两个音节的声调都与 shēng lǐ 不同，“胜利”指战胜对手或取得成功。"}, "sentence_index": null, "correct_answer": "生理"}, "level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "“生理年龄”指按身体机能判断的年龄，与“实际年龄”相对，只有“生理”能填入。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能修饰“年龄”，年龄前一般接“生理”“实际”等词。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量与年龄无关，“他的重量年龄”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格年龄”说不通，句子讲的是身体机能与实际年龄的差别。"}], "explanations": {"生理": "“生理年龄”指按身体机能判断的年龄，与“实际年龄”相对，只有“生理”能填入。", "颜色": "搭配：“颜色”不能修饰“年龄”，年龄前一般接“生理”“实际”等词。", "重量": "语义：重量与年龄无关，“他的重量年龄”不成立。", "价格": "语义：“价格年龄”说不通，句子讲的是身体机能与实际年龄的差别。"}, "sentence_index": 0, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的生理很敏感，经常一个人哭。", "explanation": "这里应该用〈心理〉。“敏感”“一个人哭”说的是情绪与心理状态；生理指身体的生命活动规律，不能用来形容情绪。"}, {"text": "这家公司正在研究这款手机的生理。", "explanation": "这里应该用〈性能〉。生理只指生物体的生命活动，手机不是生物，不能用生理；应说性能。"}, {"text": "这盘菜的生理很香，大家都想尝一尝。", "explanation": "这里应该用〈风味〉。风味指食物的味道与口感；生理只用于生物体的生命活动，不能用来形容菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "“生理数据”指身体机能的测量数据，与“都很正常”相合，只有“生理”能填入。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不能被测量，“笑话数据”与身体检查无关。"}, {"text": "香料", "is_correct": false, "explanation": "搭配：“香料”这类物品名词一般不接“数据”，不能用来修饰检查结果。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步数据”与身体检查无关，不能说这些数据都正常。"}], "explanations": {"生理": "“生理数据”指身体机能的测量数据，与“都很正常”相合，只有“生理”能填入。", "笑话": "语义：笑话不能被测量，“笑话数据”与身体检查无关。", "香料": "搭配：“香料”这类物品名词一般不接“数据”，不能用来修饰检查结果。", "脚步": "语义：“脚步数据”与身体检查无关，不能说这些数据都正常。"}, "sentence_index": 6, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书介绍了各种生理的菜谱。", "explanation": "这里应该用〈烹饪〉。生理只指身体的生命活动，不能用来形容菜谱；介绍做菜的方法应说〈烹饪〉。"}, {"text": "这家店的生理很干净，客人很多。", "explanation": "这里应该用〈环境〉。环境指店铺的整体状况；生理只用于生物体，不能用来形容店铺。"}, {"text": "这台冰箱的生理很安静，声音很小。", "explanation": "这里应该用〈运转〉。运转指机器的工作状态；生理只用于生物体，不能用来形容冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动对很生理健康有好处。", "corrected_sentence": "运动对生理健康有好处。", "error_description": "程度副词错误：“生理健康”是名词性短语，不能受“很”修饰，应说“对生理健康有好处”，删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项检查能反映她生理里的状况。", "corrected_sentence": "这项检查能反映她生理上的状况。", "error_description": "方位词错误：“生理”后面应该用“上”，说“生理上的状况”，不能说“生理里的状况”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd619e0a6-6e2f-4104-af08-6961ad371b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
