INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究大脑怎样让人想东西和做事情的学问。", "primary_collocate": null, "pronunciation": "shén jīng kē xué", "ipa": "ʂən˧˥ tɕiŋ˥ kʰɤ˥ ɕɥɛ˧˥", "syllable_count": 4, "sentences": [{"text": "神经科学是研究大脑的学问。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学神经科学，因为他对大脑很好奇。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学能告诉我们人为什么会生气。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在大学里教神经科学。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学让我们知道，大脑怎样指挥身体。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了神经科学以后，我更懂自己了。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学的老师给我们看了大脑的照片。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道什么是神经科学吗？", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经科学帮医生了解病人的想法和行为。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天读一小时神经科学的书。", "target_word": "神经科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神经科学家", "label": "复合"}, {"form": "神經科學", "label": "繁体"}], "register": "通用", "sense_fingerprint": "研究大脑如何让人思考和行动的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bbdbb47-e2ed-40ab-af64-53defd1ba67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经科学", "is_correct": true, "explanation": "正确。“神经科学”就是研究大脑的学问，符合句意。"}, {"text": "地理学", "is_correct": false, "explanation": "语义：“地理学”研究地球表面及其变化，不是研究大脑。"}, {"text": "历史学", "is_correct": false, "explanation": "语义：“历史学”研究过去的人类社会，与研究大脑无关。"}, {"text": "神经", "is_correct": false, "explanation": "搭配：“神经”指人体组织，不是一门学问，不能作主语来下定义。"}], "explanations": {"神经科学": "正确。“神经科学”就是研究大脑的学问，符合句意。", "地理学": "语义：“地理学”研究地球表面及其变化，不是研究大脑。", "历史学": "语义：“历史学”研究过去的人类社会，与研究大脑无关。", "神经": "搭配：“神经”指人体组织，不是一门学问，不能作主语来下定义。"}, "sentence_index": 0, "correct_answer": "神经科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐是一名神经科学，每天在实验室工作。", "explanation": "这里应该用〈研究人员〉。“神经科学”指学科，指人要说“神经科学家”或“研究人员”。"}, {"text": "她因为头痛，去医院挂了神经科学的号。", "explanation": "这里应该用〈神经内科〉。神经科学是研究大脑的学科，不是看病的科室，不能挂它的号。"}, {"text": "她每天神经科学两小时。", "explanation": "这里应该用〈研究〉。神经科学是名词，不能直接当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经科学", "is_correct": true, "explanation": "正确。“神经科学”的老师讲大脑，给学生看大脑照片是合理的。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：“天文学”研究天体，与给大家看大脑的照片无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”是做菜的技术，与大脑的照片没有关系。"}, {"text": "神经病", "is_correct": false, "explanation": "语域：“神经病”是口语、带贬义的说法，不能用于正式的课堂语境。"}], "explanations": {"神经科学": "正确。“神经科学”的老师讲大脑，给学生看大脑照片是合理的。", "天文学": "语义：“天文学”研究天体，与给大家看大脑的照片无关。", "烹饪": "语义：“烹饪”是做菜的技术，与大脑的照片没有关系。", "神经病": "语域：“神经病”是口语、带贬义的说法，不能用于正式的课堂语境。"}, "sentence_index": 6, "correct_answer": "神经科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个团队用了两年时间训练神经科学。", "explanation": "这里应该用〈神经网络〉。神经科学是学科，不能被训练；“神经网络”是可以训练的计算模型。"}, {"text": "他在显微镜下画出了很多神经科学。", "explanation": "这里应该用〈神经元〉。神经科学是学科，不是细胞，不能在显微镜下画出来。"}, {"text": "他最近总是失眠，医生说他得了神经科学。", "explanation": "这里应该用〈神经衰弱〉。神经科学是学科，不是疾病，不能说“得了”它；失眠对应的病症是神经衰弱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥是神经科学。", "corrected_sentence": "我表哥是神经科学家。", "error_description": "“神经科学”指学科，指人要加“家”，应为“神经科学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学了一只神经科学。", "corrected_sentence": "她学了一门神经科学。", "error_description": "“一只神经科学”应为“一门神经科学”。“神经科学”是学科，学科的量词用“门”，“只”多用于动物等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '791ad1d5-0f34-4a6f-8c8b-dc93379aa533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
