INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人告诉你的话或事情。", "primary_collocate": null, "pronunciation": "xìn xī", "ipa": "ɕin˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "我收到了一条重要的信息。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这条信息告诉经理。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有很多有用的信息。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在手机上查找旅游信息。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发来的信息我还没看。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条信息里有会议的时间和地点。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友回了一条信息。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把客人的信息写在本子上吗？", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站每天都会更新一些信息。", "target_word": "信息", "complexity_tier": "T3", "furigana": "xìn xī", "sentence_source": "generated"}, {"text": "他看了信息才知道考试改期了。", "target_word": "信息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条信息", "label": "量词"}, {"form": "信息时代", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人告诉你的消息、内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信息", "is_correct": true, "explanation": "正确答案：信息（xìn xī），指别人告诉你的话或事情。"}, {"text": "信心", "is_correct": false, "explanation": "信心（xìnxīn）与信息（xìnxī）只有第二个音节不同：息（xī）没有韵尾，心（xīn）有 n，意思是对自己的自信。"}, {"text": "欣喜", "is_correct": false, "explanation": "欣喜（xīnxǐ）与信息（xìnxī）两个音节都只是声调不同，意思是高兴、喜悦。"}, {"text": "心细", "is_correct": false, "explanation": "心细（xīnxì）与信息（xìnxī）两个音节都只是声调不同，意思是做事细致。"}], "explanations": {"信息": "正确答案：信息（xìn xī），指别人告诉你的话或事情。", "信心": "信心（xìnxīn）与信息（xìnxī）只有第二个音节不同：息（xī）没有韵尾，心（xīn）有 n，意思是对自己的自信。", "欣喜": "欣喜（xīnxǐ）与信息（xìnxī）两个音节都只是声调不同，意思是高兴、喜悦。", "心细": "心细（xīnxì）与信息（xìnxī）两个音节都只是声调不同，意思是做事细致。"}, "sentence_index": null, "correct_answer": "信息"}, "level_3": {"options": [{"text": "信息", "is_correct": true, "explanation": "正确答案：信息。「收到一条重要的信息」指别人告诉我的内容，与「重要的」相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不是可以被「收到」并且「重要」的内容，「收到了一条重要的鱼」说不通。"}, {"text": "河", "is_correct": false, "explanation": "搭配：「收到」的对象一般是消息、信件、礼物等，不能说收到一条河。"}, {"text": "路", "is_correct": false, "explanation": "语义：路是地点，不能被收到，句中的「重要的」也不能修饰一条路被收到。"}], "explanations": {"信息": "正确答案：信息。「收到一条重要的信息」指别人告诉我的内容，与「重要的」相符。", "鱼": "语义：鱼不是可以被「收到」并且「重要」的内容，「收到了一条重要的鱼」说不通。", "河": "搭配：「收到」的对象一般是消息、信件、礼物等，不能说收到一条河。", "路": "语义：路是地点，不能被收到，句中的「重要的」也不能修饰一条路被收到。"}, "sentence_index": 0, "correct_answer": "信息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每晚给我讲一个信息，我很快就睡着了。", "explanation": "这里应该用〈故事〉。「信息」指别人告诉你的资料或事情，不是有情节的故事，不能说「讲一个信息」。"}, {"text": "这是我的一点小信息，请你笑纳。", "explanation": "这里应该用〈意思〉（指一点心意或礼物）。「请笑纳」和「小意思」是送礼用语，「信息」不能作礼物。"}, {"text": "他是一个信息渊博的人。", "explanation": "这里应该用〈知识〉。「渊博」形容知识和学问，不能用来形容信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息", "is_correct": true, "explanation": "正确答案：信息。「回了一条信息」指回复朋友的消息，与「回」相配。"}, {"text": "蛇", "is_correct": false, "explanation": "语义：蛇不是可以回复的东西，「回了一条蛇」与「给朋友」的语境不符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是地理事物，不能被「回」，「回了一条河」说不通。"}, {"text": "街", "is_correct": false, "explanation": "语义：街是地点，不能被「回」，「回了一条街」与句意不符。"}], "explanations": {"信息": "正确答案：信息。「回了一条信息」指回复朋友的消息，与「回」相配。", "蛇": "语义：蛇不是可以回复的东西，「回了一条蛇」与「给朋友」的语境不符。", "河": "语义：河是地理事物，不能被「回」，「回了一条河」说不通。", "街": "语义：街是地点，不能被「回」，「回了一条街」与句意不符。"}, "sentence_index": 6, "correct_answer": "信息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气吃掉了三条信息。", "explanation": "这个词不这么用。「吃掉」的对象一般是〈食物〉，这里把「信息」误当成食物来用；「信息」指别人告诉你的内容，不能被吃。"}, {"text": "这个人是一条信息。", "explanation": "这个词不这么用。这里误把「信息」当作〈信使〉来用；「信息」指内容，不指送信的人，不能用来说一个人。"}, {"text": "这首歌的信息很好听。", "explanation": "这个词不这么用。这里误把「信息」当作〈旋律〉来用；「好听」形容声音和旋律，「信息」指歌词传达的内容，不能说好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我发了一本很长的信息。", "corrected_sentence": "他给我发了一条很长的信息。", "error_description": "量词错误：「信息」的量词应是「条」，不能用「本」（「本」用于书籍）。正确说法是「一条很长的信息」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在网上找到了很多有用的信息们。", "corrected_sentence": "他在网上找到了很多有用的信息。", "error_description": "词形错误：「信息」不能加复数词尾「们」，应说「很多有用的信息」，删去「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
