INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开始做一件事或研究一个问题时最先进入的地方。", "primary_collocate": null, "pronunciation": "qiē rù diǎn", "ipa": "tɕʰje˥ ɻu˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "学习这门课，先从最基础的概念入手，是个好切入点。", "target_word": "切入点", "complexity_tier": "T3", "furigana": "xué xí zhè mén kè, xiān cóng zuì jīchǔ de gàiniàn rùshǒu, shì gè hǎo qiērùdiǎn。", "sentence_source": "generated"}, {"text": "学汉语时，拼音是很好的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个实验，最好的切入点是什么？", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者从一个小案子找到了调查的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的第一章是理解全书的切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究历史，可以用一件小事做切入点。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目太复杂，大家先讨论选哪个切入点。", "target_word": "切入点", "complexity_tier": "T3", "furigana": "zhè gè xiàngmù tài fùzá, dàjiā xiān tǎolùn xuǎn nǎ gè qiērùdiǎn。", "sentence_source": "generated"}, {"text": "画画时，我先从最亮的地方下笔，那是切入点。", "target_word": "切入点", "complexity_tier": "T3", "furigana": "huà huà shí, wǒ xiān cóng zuì liàng de dìfang xià bǐ, nà shì qiērùdiǎn。", "sentence_source": "generated"}, {"text": "先找个切入点，再开始动手做。", "target_word": "切入点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告太长，结论部分可以作为切入点。", "target_word": "切入点", "complexity_tier": "T3", "furigana": "zhè fèn bàogào tài cháng, jiélùn bùfen kěyǐ zuòwéi qiērùdiǎn。", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "切入點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事或研究时最先进入的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切入点", "is_correct": true, "explanation": "「切入点」指开始做事或研究时最先进入的地方，正好对应「从最基础的概念入手」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是气象状况，不能用来评价一门课的入手方式，「是个好天气」说不通。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：「好身材」形容人的体形，不能用来评价一门课的入手方式。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：「花瓶」是器物，与「学习这门课」的入门方式毫无关系。"}], "explanations": {"切入点": "「切入点」指开始做事或研究时最先进入的地方，正好对应「从最基础的概念入手」。", "天气": "语义：「天气」是气象状况，不能用来评价一门课的入手方式，「是个好天气」说不通。", "身材": "搭配：「好身材」形容人的体形，不能用来评价一门课的入手方式。", "花瓶": "语义：「花瓶」是器物，与「学习这门课」的入门方式毫无关系。"}, "sentence_index": 0, "correct_answer": "切入点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次长跑的切入点在山顶。", "explanation": "这里应该用〈终点〉。切入点是开始时最先进入的地方，不是结束的地方，所以不能说「切入点在山顶」。"}, {"text": "他做这件事的切入点是为了赚钱。", "explanation": "这里应该用〈出发点〉。出发点指动机，说做事的目的或动机要用「出发点」；切入点指做事最先进入的地方，不能用来说动机。"}, {"text": "我们这次旅行的切入点是快乐。", "explanation": "这里应该用〈目标〉。切入点指开始进入的地方，不能指旅行的意图；说旅行的目的要用「目标」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切入点", "is_correct": true, "explanation": "「切入点」指讨论项目时最先着手的选择，与「选哪个」搭配自然。"}, {"text": "星空", "is_correct": false, "explanation": "语义：「星空」是夜空景象，不能作为讨论时挑选的对象，「选哪个星空」说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「心情」不能被「选哪个」挑选，「选哪个心情」不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「体温」是测量的数值，不能作为讨论时挑选的对象。"}], "explanations": {"切入点": "「切入点」指讨论项目时最先着手的选择，与「选哪个」搭配自然。", "星空": "语义：「星空」是夜空景象，不能作为讨论时挑选的对象，「选哪个星空」说不通。", "心情": "搭配：「心情」不能被「选哪个」挑选，「选哪个心情」不通。", "体温": "搭配：「体温」是测量的数值，不能作为讨论时挑选的对象。"}, "sentence_index": 6, "correct_answer": "切入点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们通过实验得出了切入点。", "explanation": "这里应该用〈结论〉。切入点是开始着手的地方，不是实验得出的结果，所以不能说「得出了切入点」。"}, {"text": "这把剪刀的切入点很锋利。", "explanation": "这里应该用〈刀刃〉。切入点指做事最先进入的地方，不指剪刀的锋口；说锋利要用「刀刃」。"}, {"text": "我们制定了一份切入点。", "explanation": "这里应该用〈计划〉。切入点不是可以制定的文件，「制定」和「切入点」搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查，我们找到了一把不错的切入点。", "corrected_sentence": "这次调查，我们找到了一个不错的切入点。", "error_description": "「切入点」的量词应用「个」。「把」多用于有柄的工具，不能修饰抽象的切入点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于想出了一个很好切入点。", "corrected_sentence": "他们终于想出了一个很好的切入点。", "error_description": "「很好」修饰名词「切入点」时，中间须加结构助词「的」，应写作「很好的切入点」；漏掉「的」是常见偏误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
