INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "上课用的书。", "primary_collocate": null, "pronunciation": "jiào kē shū", "ipa": "tɕiɑʊ˥˩ kʰɤ˥ ʂu˥", "syllable_count": 3, "sentences": [{"text": "开学第一天，学生领到了新教科书。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本教科书有十个单元。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把教科书翻到第五页。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语教科书是在北京买的。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教科书里有很多图片。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们每天读教科书。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带数学教科书。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本教科书的练习很简单。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在教科书上画了一只猫。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校免费给孩子发教科书。", "target_word": "教科书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本教科书", "label": "量词"}, {"form": "教科書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，学生上课使用的课本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教科书", "is_correct": true, "explanation": "正确：开学时学生领到的是教科书，“新”修饰教科书，句子成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：学生在开学时不会领到石头，与“领到”的语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“领到”要求可以拿在手里的具体物品作宾语，空气不能。"}, {"text": "树", "is_correct": false, "explanation": "语义：学生领到的不会是一棵树，树不是学习用品。"}], "explanations": {"教科书": "正确：开学时学生领到的是教科书，“新”修饰教科书，句子成立。", "石头": "语义：学生在开学时不会领到石头，与“领到”的语境不合。", "空气": "配价：“领到”要求可以拿在手里的具体物品作宾语，空气不能。", "树": "语义：学生领到的不会是一棵树，树不是学习用品。"}, "sentence_index": 0, "correct_answer": "教科书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只教科书。", "explanation": "这里应该用〈本〉。〈只〉用于动物或成对的物品，书要用〈本〉。"}, {"text": "我每天用教科书洗脸。", "explanation": "这里应该用〈毛巾〉。洗脸要用毛巾，教科书是用来读和学的，不能用来擦脸。"}, {"text": "这块教科书很贵。", "explanation": "这里应该用〈本〉。〈块〉用于块状的东西，书要用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科书", "is_correct": true, "explanation": "正确：“带”的对象是学习用品，数学教科书是上课要用的书，句子成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“数学”修饰的应是学习用品，石头不是，“数学石头”不成立。"}, {"text": "餐具", "is_correct": false, "explanation": "搭配：“数学”修饰的应是学习用品，不能说“数学餐具”。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：不能说“数学雨伞”，“数学”只用来修饰学习用品。"}], "explanations": {"教科书": "正确：“带”的对象是学习用品，数学教科书是上课要用的书，句子成立。", "石头": "语义：“数学”修饰的应是学习用品，石头不是，“数学石头”不成立。", "餐具": "搭配：“数学”修饰的应是学习用品，不能说“数学餐具”。", "雨伞": "搭配：不能说“数学雨伞”，“数学”只用来修饰学习用品。"}, "sentence_index": 6, "correct_answer": "教科书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座教科书很厚。", "explanation": "这里应该用〈本〉。〈座〉用于山、楼等大型固定物，书要用〈本〉。"}, {"text": "我的书架上有一扇教科书。", "explanation": "这里应该用〈本〉。〈扇〉用于门和窗，书要用〈本〉。"}, {"text": "他的桌子上放着一顶教科书。", "explanation": "这里应该用〈本〉。〈顶〉用于帽子、帐篷等，书要用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只教科书的封面是蓝色的。", "corrected_sentence": "这本教科书的封面是蓝色的。", "error_description": "量词错误：书应用〈本〉，不能用动物量词〈只〉。错误形式“这只教科书”，正确形式“这本教科书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两本教科书们。", "corrected_sentence": "我买了两本教科书。", "error_description": "错误在于“教科书”后多加了复数词尾“们”。“两本”已表示数量，名词后不能再加“们”，应说“两本教科书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
