INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让很多人知道或使用。", "primary_collocate": null, "pronunciation": "pǔ jí", "ipa": "pʰu˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "现在手机已经普及了。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想在农村普及网络。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年都会普及安全知识。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法还没有普及。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生来社区普及健康知识。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑在二十年前还没有普及。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想把中文教育普及到每个孩子。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普及汉语需要好老师和好教材。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车在城市里普及得很快。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在街上普及垃圾分类知识。", "target_word": "普及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "普及了", "label": "体标"}, {"form": "普及过", "label": "体标"}, {"form": "普及率", "label": "复合"}], "register": "通用", "sense_fingerprint": "使事物或知识传到大多数人中，让人知道或使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失眠", "is_correct": false, "explanation": "语义：失眠只用于人或动物，手机不会失眠，“手机已经失眠了”文意不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮用于食物，不能用于手机，“手机已经煮了”不成立。"}, {"text": "叹气", "is_correct": false, "explanation": "语义：叹气是人的动作，手机不能叹气，“手机已经叹气了”不通。"}, {"text": "普及", "is_correct": true, "explanation": "普及指让很多人使用或知道，这里指手机已经在大多数人中使用，符合语境。"}], "explanations": {"失眠": "语义：失眠只用于人或动物，手机不会失眠，“手机已经失眠了”文意不通。", "煮": "搭配：煮用于食物，不能用于手机，“手机已经煮了”不成立。", "叹气": "语义：叹气是人的动作，手机不能叹气，“手机已经叹气了”不通。", "普及": "普及指让很多人使用或知道，这里指手机已经在大多数人中使用，符合语境。"}, "sentence_index": 0, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在超市普及了很多水果。", "explanation": "这里应该用〈挑选〉。在超市挑水果要用挑选；普及指让很多人使用或知道，不用于个人买东西。"}, {"text": "我向大家普及了这位新同事。", "explanation": "这里应该用〈介绍〉。介绍的是人或事物的基本情况；普及指让很多人使用或知道某种事物，不用于人。"}, {"text": "他每天普及自己的体重。", "explanation": "这里应该用〈记录〉。记录个人数据要用记录；普及指让很多人使用或知道，不用于个人数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "搭配：烧用于燃烧或加热物体，不能接“教育”，“烧到每个孩子”不通。"}, {"text": "赶", "is_correct": false, "explanation": "语义：赶指追赶或驱赶，不是让教育传播开，“赶到每个孩子”文意不通。"}, {"text": "装", "is_correct": false, "explanation": "语义：装指放进容器或安装，“装到每个孩子”不通。"}, {"text": "普及", "is_correct": true, "explanation": "普及指让很多人使用或掌握，这里指中文教育传播到每个孩子，符合语境。"}], "explanations": {"烧": "搭配：烧用于燃烧或加热物体，不能接“教育”，“烧到每个孩子”不通。", "赶": "语义：赶指追赶或驱赶，不是让教育传播开，“赶到每个孩子”文意不通。", "装": "语义：装指放进容器或安装，“装到每个孩子”不通。", "普及": "普及指让很多人使用或掌握，这里指中文教育传播到每个孩子，符合语境。"}, "sentence_index": 6, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在普及这台电视。", "explanation": "这里应该用〈修理〉。修理的是出了故障的东西；普及指让很多人使用或知道，不用于修理物品。"}, {"text": "我在图书馆普及了很多资料。", "explanation": "这里应该用〈搜索〉。找资料要用搜索；普及指让很多人使用或知道，不指查找。"}, {"text": "妈妈在厨房普及了一个鸡蛋。", "explanation": "这里应该用〈打〉。打鸡蛋是把蛋壳敲开；普及指让很多人使用或知道，不用于对一个鸡蛋的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种技术已经普及在了农村。", "corrected_sentence": "这种技术已经普及到了农村。", "error_description": "介词错误：表示范围要用“到”，不能用“在”，应说“普及到了农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视机在这个时代已经普及了每个家庭。", "corrected_sentence": "电视机在这个时代已经普及到了每个家庭。", "error_description": "介词缺失：“普及”后面表示范围要加“到”，应说“普及到了每个家庭”，不能省略“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
