INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个接一个地。", "primary_collocate": null, "pronunciation": "xiāng jì", "ipa": "ɕiɑŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老人们相继离开了这个小村子。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两年，几家商店相继关门了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相继来到了北京。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花儿相继开了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们相继跑进了教室。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位老师相继发言，大家听得很认真。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的老同事相继退休了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，电和水相继恢复了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子相继长大，离开了家。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们相继来看我，我很高兴。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "多个人或事一个接一个地先后发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确答案：相继（xiāng jì），意思是一个接一个地。"}, {"text": "相机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，“相机”意思是照相机。"}, {"text": "香气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），“香气”意思是香味。"}, {"text": "相似", "is_correct": false, "explanation": "sì 与 jì 声母不同（s 与 j），“相似”意思是像。"}], "explanations": {"相继": "正确答案：相继（xiāng jì），意思是一个接一个地。", "相机": "jī（第一声）与 jì（第四声）声调不同，“相机”意思是照相机。", "香气": "qì 与 jì 声母不同（q 与 j），“香气”意思是香味。", "相似": "sì 与 jì 声母不同（s 与 j），“相似”意思是像。"}, "sentence_index": null, "correct_answer": "相继"}, "level_3": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确：“老人们相继离开”，表示一个接一个地离开。"}, {"text": "相互", "is_correct": false, "explanation": "语义：“相互”表示彼此互动，“老人们相互离开”不成立。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能修饰“离开”这种一次性动作。"}, {"text": "相当", "is_correct": false, "explanation": "语法：“相当”表示程度或相等，不能修饰“离开”这类动作。"}], "explanations": {"相继": "正确：“老人们相继离开”，表示一个接一个地离开。", "相互": "语义：“相互”表示彼此互动，“老人们相互离开”不成立。", "一直": "搭配：“一直”表示持续，不能修饰“离开”这种一次性动作。", "相当": "语法：“相当”表示程度或相等，不能修饰“离开”这类动作。"}, "sentence_index": 0, "correct_answer": "相继"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水相继热了。", "explanation": "这里应该用〈慢慢〉。“相继”表示几件事先后接连发生，不能表示一件事逐渐变化；“这杯水”只有一杯，应说“慢慢热了”。"}, {"text": "我相继离开了教室。", "explanation": "这里应该用〈先〉。“相继”需要几个人或几件事接连发生，一个人一次离开只能用“先”。"}, {"text": "他相继走回家。", "explanation": "这里应该用〈独自〉。“相继”表示接连发生，只有一个人一次走回家时要用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确：“公司的老同事相继退休”，表示一批接一批地退休。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与接连发生的“相继”语义相反。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求动作由人主动亲身完成，不能修饰“退休”。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙行动，不能修饰“退休”这一结果。"}], "explanations": {"相继": "正确：“公司的老同事相继退休”，表示一批接一批地退休。", "偶尔": "语义：“偶尔”表示不常发生，与接连发生的“相继”语义相反。", "亲自": "搭配：“亲自”要求动作由人主动亲身完成，不能修饰“退休”。", "连忙": "语义：“连忙”表示急忙行动，不能修饰“退休”这一结果。"}, "sentence_index": 6, "correct_answer": "相继"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他相继出发了。", "explanation": "这里应该用〈马上〉。“相继”要求多人或多件事接连发生，一个人只出发一次时不能用。"}, {"text": "这扇门相继开了。", "explanation": "这里应该用〈突然〉。“相继”表示几件事接连发生，一扇门只开一次时不能用“相继”，应说“突然开了”。"}, {"text": "他相继在等你。", "explanation": "这里应该用〈一直〉。“相继”表示接连发生，不能表示持续不断地进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们相当来到了北京。", "corrected_sentence": "他们相继来到了北京。", "error_description": "用词错误：“相当”表示程度，不能修饰“来到”这类动作，此处应改为表示接连发生的“相继”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同事们相继的离开了公司。", "corrected_sentence": "同事们相继离开了公司。", "error_description": "错误形式：“相继的离开”；正确形式：“相继离开”。“相继”是副词，后面不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情从开始到结束的经过。", "primary_collocate": null, "pronunciation": "guò chéng", "ipa": "kwo˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学习的过程很长。", "target_word": "过程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做饭的过程很有意思。", "target_word": "过程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢旅行的过程,不只看结果。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我讲了事情的整个过程。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在学习过程中,我认识了很多朋友。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果不重要,过程更重要。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个过程要花三个小时。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们实验的过程是怎么样的。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把做蛋糕的过程拍成了视频。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成长的过程中,他吃过很多苦。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个过程", "label": "量词搭配"}, {"form": "过程中", "label": "方位搭配"}, {"form": "全过程", "label": "复合词"}], "register": "中性", "sense_fingerprint": "过程：事情从开始到结束的经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675cfc97-fbfc-4651-bf94-1c49f7b53f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“长”来描述，“学习的颜色很长”说不通。"}, {"text": "过程", "is_correct": true, "explanation": "“过程”指事情从开始到结束的经过，“学习的过程很长”符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很长”不用来形容“体重”，二者不搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不能说“很长”，与“学习”的时间经过无关，句子说不通。"}], "explanations": {"颜色": "语义：“颜色”不能用“长”来描述，“学习的颜色很长”说不通。", "过程": "“过程”指事情从开始到结束的经过，“学习的过程很长”符合句意。", "体重": "搭配：“很长”不用来形容“体重”，二者不搭配。", "脾气": "语义：“脾气”不能说“很长”，与“学习”的时间经过无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "过程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次选举的过程出来了。", "explanation": "这里应该用〈结果〉。“过程”指事情从开始到结束的经过，选举的最终结果出来要用“结果”，不能说“过程出来了”。"}, {"text": "这个药的过程很好，两天就好了。", "explanation": "这里应该用〈效果〉。“过程”指经过，不指药物作用的结果，应该用“效果”。"}, {"text": "这家公司的过程很大，有很多员工。", "explanation": "这里应该用〈规模〉。“过程”指经过，不指企业的大小，说企业的大小要用“规模”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“要花三个小时”说的是做事所需的时间，“价格”不能用来计算耗时。"}, {"text": "过程", "is_correct": true, "explanation": "“过程”指事情从开始到结束的经过，“这个过程要花三个小时”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以持续耗时的事情，“这个声音要花三个小时”说不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”与“花三个小时”的时间概念无关，句子说不通。"}], "explanations": {"价格": "搭配：“要花三个小时”说的是做事所需的时间，“价格”不能用来计算耗时。", "过程": "“过程”指事情从开始到结束的经过，“这个过程要花三个小时”符合句意。", "声音": "语义：“声音”不是可以持续耗时的事情，“这个声音要花三个小时”说不通。", "性别": "语义：“性别”与“花三个小时”的时间概念无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "过程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的过程很结实。", "explanation": "这里应该用〈质地〉。“过程”指事情的经过，不用来形容物体的结实程度，说物体的质地要用“质地”。"}, {"text": "这顿饭的过程很贵。", "explanation": "这里应该用〈价钱〉。“过程”指事情的经过，不指金钱的多少，说饭菜的价钱要用“价钱”。"}, {"text": "我的过程比他高。", "explanation": "这里应该用〈身高〉。“过程”指事情的经过，不用来比较人的高矮，说人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条过程很复杂，需要一周。", "corrected_sentence": "这个过程很复杂，需要一周。", "error_description": "错误：“过程”前的量词用了“条”。“条”多用于线状物、消息、规定等条目，不用于“过程”这类抽象的经过，应用“个”，说“这个过程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在工作过程的，他学会了很多东西。", "corrected_sentence": "在工作过程中，他学会了很多东西。", "error_description": "“中”误写为“的”：“过程中”是固定的方位结构，“过程的”不成立，应说“在工作过程中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8b32aaa-68bf-436c-bb1a-69d9defbf86c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
