INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "讹误是文字、数字等在抄写或流传中出现的错误。", "primary_collocate": null, "pronunciation": "é wù", "ipa": "ɤ˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这本旧书里有不少讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们改正了文章里的讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书抄来抄去，难免会有讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人抄写时，这个字出现了讹误。", "target_word": "讹误", "complexity_tier": "T3", "furigana": "hòu rén chāo xiě shí zhè gè zì chū xiàn le é wù", "sentence_source": "generated"}, {"text": "他看出了报告中的几处讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你检查一下，看看有没有讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话流传很久，已经出现了讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中的讹误太多，读起来很难受。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们花了很多年才改正这些讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的数字有讹误，应该是五十。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}], "register": "书面", "sense_fingerprint": "文字、数字等在抄写或流传中出现的错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讹误", "is_correct": true, "explanation": "正确：讹误指文字或数字在抄写、流传中出现的错误，旧书里可以有。"}, {"text": "石头", "is_correct": false, "explanation": "语义：书里不会有石头，“有不少石头”与旧书的语境不合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会出现在旧书里，与“有不少”的语境不合。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：“有不少”用于可数或成堆的东西，海水是大片液体，不这样计。"}], "explanations": {"讹误": "正确：讹误指文字或数字在抄写、流传中出现的错误，旧书里可以有。", "石头": "语义：书里不会有石头，“有不少石头”与旧书的语境不合。", "面包": "语义：面包不会出现在旧书里，与“有不少”的语境不合。", "海水": "搭配：“有不少”用于可数或成堆的东西，海水是大片液体，不这样计。"}, "sentence_index": 0, "correct_answer": "讹误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我犯了很多讹误。", "explanation": "这里应该用〈错误〉。讹误多指文字、数字在抄写或流传中的错误，做题的错误要用〈错误〉。"}, {"text": "这里有一颗讹误。", "explanation": "这里应该用〈处〉。〈颗〉用于粒状的东西，讹误应用〈处〉。"}, {"text": "这场比赛他有一次讹误。", "explanation": "这里应该用〈失误〉。讹误指文字或数字的错误，比赛中的差错要用〈失误〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讹误", "is_correct": true, "explanation": "正确：讹误指流传中出现的错误，“已经出现了讹误”成立。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水与句子在流传中出现的错误无关，句子里不会出现雨水。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“出现”指事情或问题在流传中显露，冰箱是具体物件，不能这样出现。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“出现了”后接的是问题或情况，“面积”是度量，不能说“出现了面积”。"}], "explanations": {"讹误": "正确：讹误指流传中出现的错误，“已经出现了讹误”成立。", "雨水": "语义：雨水与句子在流传中出现的错误无关，句子里不会出现雨水。", "冰箱": "语义：“出现”指事情或问题在流传中显露，冰箱是具体物件，不能这样出现。", "面积": "搭配：“出现了”后接的是问题或情况，“面积”是度量，不能说“出现了面积”。"}, "sentence_index": 6, "correct_answer": "讹误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同里有一座讹误。", "explanation": "这里应该用〈处〉。〈座〉用于山、楼等大型固定物，讹误应用〈处〉。"}, {"text": "我和朋友之间有一个讹误。", "explanation": "这里应该用〈误会〉。两人之间的误解要用〈误会〉，讹误指文字或数字的错误。"}, {"text": "他在书里发现了一把讹误。", "explanation": "这里应该用〈处〉。〈把〉用于有柄的器具，讹误不能用“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里有三只讹误。", "corrected_sentence": "书里有三处讹误。", "error_description": "量词错误：讹误应用〈处〉，〈只〉用于动物，不能用于讹误。错误形式“三只讹误”，正确形式“三处讹误”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章里有两讹误。", "corrected_sentence": "这篇文章里有两处讹误。", "error_description": "量词缺失：讹误前的数量词“两”后必须有量词〈处〉，应说“两处讹误”，不能省略为“两讹误”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
