INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物从原有的事物中出现、形成，比如产生兴趣、产生误会。", "primary_collocate": null, "pronunciation": "chǎn shēng", "ipa": "ʈʂʰan˨˩˦ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他对画画产生了兴趣。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人之间产生了误会。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能产生很多热量。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对他产生了很大影响。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的话，我产生了怀疑。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的问题是怎么产生的？", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在一起容易产生矛盾。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器工作时会产生噪音。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法产生于一次旅行。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没有产生任何效果。", "target_word": "产生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产生了", "label": "体标"}, {"form": "产生过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物从原有的事物中出现、形成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965e8b9c-2139-44a0-a62f-27461e03fcbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20550, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "产生", "is_correct": true, "explanation": "正确答案：产生（chǎn shēng），意思是事物从原有事物中出现、形成。"}, {"text": "蝉声", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）只差声调，声母与韵母相同；蝉声指蝉的鸣叫声。"}, {"text": "吵声", "is_correct": false, "explanation": "chǎo（第三声）与 chǎn（第三声）声调相同，韵母 -ao 与 -an 不同，意思是吵闹的声音。"}, {"text": "喘声", "is_correct": false, "explanation": "chuǎn（第三声）比 chǎn 多了介音 u，声调相同，意思是喘息时发出的声音。"}], "explanations": {"产生": "正确答案：产生（chǎn shēng），意思是事物从原有事物中出现、形成。", "蝉声": "chán（第二声）与 chǎn（第三声）只差声调，声母与韵母相同；蝉声指蝉的鸣叫声。", "吵声": "chǎo（第三声）与 chǎn（第三声）声调相同，韵母 -ao 与 -an 不同，意思是吵闹的声音。", "喘声": "chuǎn（第三声）比 chǎn 多了介音 u，声调相同，意思是喘息时发出的声音。"}, "sentence_index": null, "correct_answer": "产生"}, "level_3": {"options": [{"text": "产生", "is_correct": true, "explanation": "正确：「产生」与「兴趣」搭配，表示兴趣出现。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能与「兴趣」搭配，不能说“吃了兴趣”。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：「游泳」是不及物动词，不能带「兴趣」作宾语。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」不能带「兴趣」作宾语，不能说“写了兴趣”。"}], "explanations": {"产生": "正确：「产生」与「兴趣」搭配，表示兴趣出现。", "吃": "搭配：「吃」不能与「兴趣」搭配，不能说“吃了兴趣”。", "游泳": "配价：「游泳」是不及物动词，不能带「兴趣」作宾语。", "写": "搭配：「写」不能带「兴趣」作宾语，不能说“写了兴趣”。"}, "sentence_index": 0, "correct_answer": "产生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每月产生两万台电脑。", "explanation": "这里应该用〈生产〉。产生指事物自然出现或形成，工厂制造产品要说生产。"}, {"text": "他产生了一种新机器。", "explanation": "这里应该用〈发明〉。产生指事物自然出现或形成，人造出新东西要用发明。"}, {"text": "他的举动产生了大家的注意。", "explanation": "这里应该用〈引起〉。“注意”是别人的反应，要说引起注意；产生多用于兴趣、误会、影响等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产生", "is_correct": true, "explanation": "正确：「产生」与「矛盾」搭配，表示矛盾出现。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」不能带「矛盾」作宾语，不能说“穿矛盾”。"}, {"text": "生病", "is_correct": false, "explanation": "配价：「生病」是不及物动词，不能带「矛盾」作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不能与「矛盾」搭配，不能说“洗矛盾”。"}], "explanations": {"产生": "正确：「产生」与「矛盾」搭配，表示矛盾出现。", "穿": "搭配：「穿」不能带「矛盾」作宾语，不能说“穿矛盾”。", "生病": "配价：「生病」是不及物动词，不能带「矛盾」作宾语。", "洗": "搭配：「洗」不能与「矛盾」搭配，不能说“洗矛盾”。"}, "sentence_index": 6, "correct_answer": "产生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们产生了一个聚会。", "explanation": "这里应该用〈办〉。产生指事物从原有事物中出现，组织聚会要说办。"}, {"text": "我产生了一份礼物。", "explanation": "这里应该用〈做〉。产生指事物从原有事物中出现，自己动手制作礼物要说做。"}, {"text": "他产生了比赛。", "explanation": "这里应该用〈参加〉。产生指事物出现，比赛要人去参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前产生了过这个想法。", "corrected_sentence": "我以前产生过这个想法。", "error_description": "错误在“产生”后同时加了“了”和“过”。“产生过”表示曾经出现过，不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种习惯产生童年时期。", "corrected_sentence": "这种习惯产生于童年时期。", "error_description": "错误在漏了介词“于”。书面中“产生于”表示起源，漏掉“于”后，“产生”与后面的时间词之间关系不清，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7eb847-1aab-4ef5-b74e-82cc2264e120') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚", "is_correct": true, "explanation": "正确：“早”与“晚”构成反义，“早”指清晨，“晚”指夜晚。"}, {"text": "午", "is_correct": false, "explanation": "不构成反义：“午”指中午，不是“早”的反义。"}, {"text": "窗", "is_correct": false, "explanation": "不构成反义：“窗”与“早”没有对立关系。"}, {"text": "书", "is_correct": false, "explanation": "不构成反义：“书”与“早”没有对立关系。"}], "correct_answer": "晚", "explanations": {"晚": "正确：“早”与“晚”构成反义，“早”指清晨，“晚”指夜晚。", "午": "不构成反义：“午”指中午，不是“早”的反义。", "窗": "不构成反义：“窗”与“早”没有对立关系。", "书": "不构成反义：“书”与“早”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚", "is_correct": true, "explanation": "正确：“早”与“晚”构成反义，“早”指清晨，“晚”指夜晚。"}, {"text": "桌", "is_correct": false, "explanation": "不构成反义：“桌”与“早”没有对立关系。"}, {"text": "雾", "is_correct": false, "explanation": "不构成反义：“雾”与“早”没有对立关系。"}, {"text": "椅", "is_correct": false, "explanation": "不构成反义：“椅”与“早”没有对立关系。"}], "correct_answer": "晚", "explanations": {"晚": "正确：“早”与“晚”构成反义，“早”指清晨，“晚”指夜晚。", "桌": "不构成反义：“桌”与“早”没有对立关系。", "雾": "不构成反义：“雾”与“早”没有对立关系。", "椅": "不构成反义：“椅”与“早”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "太阳出来的时候。", "primary_collocate": null, "pronunciation": "zǎo", "ipa": "tsɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "他每天从早忙到晚。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一早就出门，很晚才回家，很辛苦。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店从早到晚都有人。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从早到晚，雨一直下着。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从早写到晚，终于写完了。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一早就开始工作，天黑才停。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从早到晚，孩子都在玩。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天我从早到晚都在复习。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生从早到晚看病人。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从早练到晚。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "早晨", "label": "复合"}, {"form": "早上", "label": "复合"}], "register": "中性", "sense_fingerprint": "早·清晨，与晚相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d39713-e02e-4d8c-930e-db2b66dc5d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“早”读 zǎo（第三声），此处指名词“清晨”。"}, {"text": "造", "is_correct": false, "explanation": "zào 与 zǎo 声调不同（第四声与第三声），意思是制造。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 zǎo 声母不同（c 与 z），意思是草。"}, {"text": "好", "is_correct": false, "explanation": "hǎo 与 zǎo 声母不同（h 与 z），意思是好。"}, {"text": "找", "is_correct": false, "explanation": "zhǎo 与 zǎo 声母不同（zh 与 z），意思是寻找。"}], "explanations": {"早": "正确：“早”读 zǎo（第三声），此处指名词“清晨”。", "造": "zào 与 zǎo 声调不同（第四声与第三声），意思是制造。", "草": "cǎo 与 zǎo 声母不同（c 与 z），意思是草。", "好": "hǎo 与 zǎo 声母不同（h 与 z），意思是好。", "找": "zhǎo 与 zǎo 声母不同（zh 与 z），意思是寻找。"}, "sentence_index": null, "correct_answer": "早"}, "level_3": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“从早忙到晚”指从清晨到夜晚，“早”作名词。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不能“忙”，“从灯忙到晚”不成立。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能“忙到晚”。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“从…到晚”需要时间词，不能用“车”。"}], "explanations": {"早": "正确：“从早忙到晚”指从清晨到夜晚，“早”作名词。", "灯": "语义：灯不能“忙”，“从灯忙到晚”不成立。", "花": "语义：花不能“忙到晚”。", "车": "搭配：“从…到晚”需要时间词，不能用“车”。"}, "sentence_index": 0, "correct_answer": "早"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个早很冷，大家都穿厚衣服。", "explanation": "这里应该用〈清晨〉。名词“早”不能直接作“这个…”的修饰成分，要说“这个清晨”。"}, {"text": "早的空气很新鲜。", "explanation": "这里应该用〈清晨〉。名词“早”不能直接修饰“空气”，要说“清晨的空气”。"}, {"text": "他把早放进了包里，准备去上班。", "explanation": "这里应该用〈午饭〉。“早”是时间词，不能装进包里；要带进包里的应是〈午饭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“早”读 zǎo（第三声），此处指名词“清晨”。"}, {"text": "扫", "is_correct": false, "explanation": "sǎo 与 zǎo 声母不同（s 与 z），意思是扫地。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 zǎo 声母不同（l 与 z），意思是年老。"}, {"text": "糟", "is_correct": false, "explanation": "zāo 与 zǎo 声调不同（第一声与第三声），意思是糟糕。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo 与 zǎo 声母不同（ch 与 z），意思是吵闹。"}], "explanations": {"早": "正确：“早”读 zǎo（第三声），此处指名词“清晨”。", "扫": "sǎo 与 zǎo 声母不同（s 与 z），意思是扫地。", "老": "lǎo 与 zǎo 声母不同（l 与 z），意思是年老。", "糟": "zāo 与 zǎo 声调不同（第一声与第三声），意思是糟糕。", "吵": "chǎo 与 zǎo 声母不同（ch 与 z），意思是吵闹。"}, "sentence_index": null, "correct_answer": "早"}, "level_3": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“从早到晚”指从清晨到夜晚，“早”作名词。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能表示一段时间的起点，“从猫到晚”不成立。"}, {"text": "石", "is_correct": false, "explanation": "语义：石头不能表示时间起点，“从石到晚”不成立。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“从…到晚”需要时间词，不能用“纸”。"}], "explanations": {"早": "正确：“从早到晚”指从清晨到夜晚，“早”作名词。", "猫": "语义：猫不能表示一段时间的起点，“从猫到晚”不成立。", "石": "语义：石头不能表示时间起点，“从石到晚”不成立。", "纸": "搭配：“从…到晚”需要时间词，不能用“纸”。"}, "sentence_index": 6, "correct_answer": "早"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼睛很早，看得很清楚。", "explanation": "“早”指时间靠前，不能形容眼睛；此处不是名词“清晨”的意思。"}, {"text": "他的脚很早，走起路来很快。", "explanation": "“早”不能形容脚的状态；此处不是名词“清晨”的意思。"}, {"text": "他的胳膊很早，很有力气。", "explanation": "“早”不能形容胳膊；此处不是名词“清晨”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从晚到早都在工作。", "corrected_sentence": "他从早到晚都在工作。", "error_description": "语序错误：“从早到晚”不能说成“从晚到早”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从早忙晚，很辛苦。", "corrected_sentence": "他们从早忙到晚，很辛苦。", "error_description": "“到”遗漏：“从早到晚”的“到”不能省，应说“从早忙到晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
