INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泥是水和土混在一起，软软的东西。", "primary_collocate": null, "pronunciation": "ní", "ipa": "ni˧˥", "syllable_count": 1, "sentences": [{"text": "小狗跑过水坑，脚上沾满了泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下过雨的地上全是泥，不好走。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢在院子里用泥做小房子。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的裤子上有泥，要换一条。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路一下雨就都是泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泥很软，手一捏就变形了。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河边挖了一堆泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友把泥放在盘子里，说是蛋糕。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，车轮上带着很多泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干了的泥会变硬，湿的泥很软。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "团", "label": "量词"}, {"form": "泥巴", "label": "复合"}, {"form": "泥土", "label": "复合"}], "register": "中性", "sense_fingerprint": "水和土混在一起的软东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d39713-e02e-4d8c-930e-db2b66dc5d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泥", "is_correct": true, "explanation": "正确：「泥」（ní）指水和土混在一起的软东西，是本词。"}, {"text": "你", "is_correct": false, "explanation": "nǐ（第三声）与 ní（第二声）声调不同，意思是「你」。"}, {"text": "离", "is_correct": false, "explanation": "lí 与 ní 声母不同（l 与 n），意思是「离开」。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是「油腻」。"}, {"text": "宁", "is_correct": false, "explanation": "níng 比 ní 多一个韵尾 -ng，意思是「安宁」。"}], "explanations": {"泥": "正确：「泥」（ní）指水和土混在一起的软东西，是本词。", "你": "nǐ（第三声）与 ní（第二声）声调不同，意思是「你」。", "离": "lí 与 ní 声母不同（l 与 n），意思是「离开」。", "腻": "nì（第四声）与 ní（第二声）声调不同，意思是「油腻」。", "宁": "níng 比 ní 多一个韵尾 -ng，意思是「安宁」。"}, "sentence_index": null, "correct_answer": "泥"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能沾在脚上。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能沾满脚。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「沾满」说的是附着在表面的物质，不能说沾满声音。"}, {"text": "泥", "is_correct": true, "explanation": "正确：「脚上沾满了泥」指经过水坑后脚上沾的湿泥，与语境相合。"}], "explanations": {"空气": "语义：空气是看不见的气体，不能沾在脚上。", "时间": "语义：时间是抽象概念，不能沾满脚。", "声音": "搭配：「沾满」说的是附着在表面的物质，不能说沾满声音。", "泥": "正确：「脚上沾满了泥」指经过水坑后脚上沾的湿泥，与语境相合。"}, "sentence_index": 0, "correct_answer": "泥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他往咖啡里加了一勺泥。", "explanation": "这里应该用〈糖〉。泥是水和土混成的软物，不能加进咖啡里；加进咖啡的应是〈糖〉。"}, {"text": "他一吹就飞起了桌上的泥。", "explanation": "这里应该用〈灰尘〉。灰尘是干燥的细粉，一吹就飞；泥是湿的软物，吹不起来。"}, {"text": "他渴极了，把泥倒进杯子里喝。", "explanation": "这里应该用〈水〉。泥是水和土混成的软物，不能倒进杯子里喝；要喝的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20556, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泥", "is_correct": true, "explanation": "正确：「泥」（ní）指水和土混在一起的软东西，是本词。"}, {"text": "拟", "is_correct": false, "explanation": "nǐ（第三声）与 ní（第二声）声调不同，意思是「拟定」。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 ní 声母不同（l 与 n），意思是「梨子」。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是「逆行」。"}, {"text": "凝", "is_correct": false, "explanation": "níng 比 ní 多一个韵尾 -ng，意思是「凝结」。"}], "explanations": {"泥": "正确：「泥」（ní）指水和土混在一起的软东西，是本词。", "拟": "nǐ（第三声）与 ní（第二声）声调不同，意思是「拟定」。", "梨": "lí 与 ní 声母不同（l 与 n），意思是「梨子」。", "逆": "nì（第四声）与 ní（第二声）声调不同，意思是「逆行」。", "凝": "níng 比 ní 多一个韵尾 -ng，意思是「凝结」。"}, "sentence_index": null, "correct_answer": "泥"}, "level_3": {"options": [{"text": "思想", "is_correct": false, "explanation": "语义：思想是抽象的，不能被挖出一堆。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：「挖」的对象是实物，不能说挖一堆笑声。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象的情感，不能被挖出来堆成一堆。"}, {"text": "泥", "is_correct": true, "explanation": "正确：「挖了一堆泥」指在河边挖出的泥土，与语境相合。"}], "explanations": {"思想": "语义：思想是抽象的，不能被挖出一堆。", "笑声": "搭配：「挖」的对象是实物，不能说挖一堆笑声。", "友谊": "语义：友谊是抽象的情感，不能被挖出来堆成一堆。", "泥": "正确：「挖了一堆泥」指在河边挖出的泥土，与语境相合。"}, "sentence_index": 6, "correct_answer": "泥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一支泥，准备做杯子。", "explanation": "这里应该用〈块〉。「支」用于细长的笔、烟等，泥要说块。"}, {"text": "他手里拿着一根泥。", "explanation": "这里应该用〈团〉。「根」用于细长的东西，成团的泥要说团。"}, {"text": "池塘边有一条泥。", "explanation": "这里应该用〈块〉。「条」用于细长或带状的东西，泥要说块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在河边挖了一只泥，准备做陶器。", "corrected_sentence": "他在河边挖了一块泥，准备做陶器。", "error_description": "量词错误：「泥」的量词是「块」或「团」；「只」主要用于动物或成对物件之一，不能修饰泥，应改为「一块泥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的裤子上有一张泥，洗不掉。", "corrected_sentence": "我的裤子上有一块泥，洗不掉。", "error_description": "量词错误：泥应用量词「块」，「张」用于纸、桌子等平面物，不能修饰泥。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
