INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20560, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常贵、特别好的东西。", "primary_collocate": null, "pronunciation": "shē chǐ pǐn", "ipa": "/ʂɤ˥ ʈʂʰɻ̩˨˩˦ pʰin˨˩˦/", "syllable_count": 3, "sentences": [{"text": "这个包太贵了，是有名的奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对很多学生来说，名牌手表是奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一年只买一件奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖奢侈品，东西都很贵。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表几十万元，是真正的奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢买奢侈品，觉得没有必要。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前，汽车对我们家是奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外买了一个奢侈品包。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这座城市，一杯咖啡不是奢侈品。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奢侈品的价格这么高，还是有很多人买。", "target_word": "奢侈品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件奢侈品", "label": "量词：件"}, {"form": "奢侈品店", "label": "复合"}], "register": "中性", "sense_fingerprint": "价格很高、超出一般生活需要的高档物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奢侈品", "is_correct": true, "explanation": "正确：「奢侈品」指价格高的高档物品，与「这个包太贵了，是有名的……」相合。"}, {"text": "必需品", "is_correct": false, "explanation": "语义：「必需品」指生活中不可缺少的东西，与「太贵了」的语境矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：「有名的」一般不修饰玩具，且包不能说成玩具。"}, {"text": "食品", "is_correct": false, "explanation": "语义：包不是食品，「食品」与「包」指称矛盾。"}], "explanations": {"奢侈品": "正确：「奢侈品」指价格高的高档物品，与「这个包太贵了，是有名的……」相合。", "必需品": "语义：「必需品」指生活中不可缺少的东西，与「太贵了」的语境矛盾。", "玩具": "搭配：「有名的」一般不修饰玩具，且包不能说成玩具。", "食品": "语义：包不是食品，「食品」与「包」指称矛盾。"}, "sentence_index": 0, "correct_answer": "奢侈品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一台奢侈品。", "explanation": "这里应该用〈件〉。「台」用于机器、电器等大型器物，不用于这类物品。"}, {"text": "她买了一只奢侈品。", "explanation": "这里应该用〈件〉。「只」用于动物，不能用于奢侈品。"}, {"text": "我收藏了一本奢侈品。", "explanation": "这里应该用〈件〉。「本」用于书籍、册子，不能用于奢侈品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奢侈品", "is_correct": true, "explanation": "正确：「奢侈品」指价格很高的物品，与「十年前，汽车对我们家是……」相合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：「垃圾」含明显贬义，与这句的中性叙述不合。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：汽车不是宠物，与「是……」的陈述矛盾。"}, {"text": "文具", "is_correct": false, "explanation": "语义：「文具」指学习用品，汽车不属于这一类。"}], "explanations": {"奢侈品": "正确：「奢侈品」指价格很高的物品，与「十年前，汽车对我们家是……」相合。", "垃圾": "语域：「垃圾」含明显贬义，与这句的中性叙述不合。", "宠物": "语义：汽车不是宠物，与「是……」的陈述矛盾。", "文具": "语义：「文具」指学习用品，汽车不属于这一类。"}, "sentence_index": 6, "correct_answer": "奢侈品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们应该学会奢侈品。", "explanation": "这里应该用〈节俭〉。「奢侈品」指昂贵的物品，不是可以“学会”的做法；“学会”后面接的是做法或能力，如〈节俭〉。"}, {"text": "这把锤子是修东西的奢侈品。", "explanation": "这里应该用〈工具〉。「奢侈品」指昂贵、非必需的东西，修东西的锤子只是普通工具，不能用「奢侈品」来形容。"}, {"text": "他的性格像奢侈品一样。", "explanation": "「奢侈品」指物品，不用于比喻人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹生日时收到了一只奢侈品。", "corrected_sentence": "我妹妹生日时收到了一件奢侈品。", "error_description": "错误形式「一只奢侈品」：「只」用于动物，奢侈品要用「件」，正确形式为「一件奢侈品」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天买过一件奢侈品。", "corrected_sentence": "她昨天买了一件奢侈品。", "error_description": "错误形式「昨天买过」：「过」表示经历，不能与具体的时间「昨天」连用，正确形式为「买了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
