INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20562, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做同样的事情一次以上。", "primary_collocate": null, "pronunciation": "chóng fù", "ipa": "ʈʂʰʊŋ˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "请你把这句话重复一遍。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师重复了两次这个问题。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要重复同样的错误。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直重复着那个故事。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把同样的动作重复了三遍。", "target_word": "重复", "complexity_tier": "T3", "furigana": "tā bǎ tóngyàng de dòngzuò chóngfù le sān biàn.", "sentence_source": "generated"}, {"text": "他每天重复做同样的练习，觉得很枯燥。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没听清楚，请再重复一次。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢重复听同一首歌。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词在文章里重复了五次。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的错误今天又重复了。", "target_word": "重复", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重复了", "label": "体标"}, {"form": "重复着", "label": "体标"}, {"form": "重复过", "label": "体标"}], "register": "通用", "sense_fingerprint": "同样的话或事再来一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”指把实物弄碎，不能用于“这句话”。"}, {"text": "重复", "is_correct": true, "explanation": "正确。“重复”指把同样的话再说一遍，符合“请你把这句话……一遍”的要求。"}, {"text": "颁布", "is_correct": false, "explanation": "语域：“颁布”是正式的法令用语，用于日常请求很不协调。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”用于纪录、规则等，不能说“打破这句话”。"}], "explanations": {"粉碎": "语义：“粉碎”指把实物弄碎，不能用于“这句话”。", "重复": "正确。“重复”指把同样的话再说一遍，符合“请你把这句话……一遍”的要求。", "颁布": "语域：“颁布”是正式的法令用语，用于日常请求很不协调。", "打破": "搭配：“打破”用于纪录、规则等，不能说“打破这句话”。"}, "sentence_index": 0, "correct_answer": "重复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在街上重复了老朋友。", "explanation": "这里应该用〈碰到〉。“重复”指同样的动作再做一次，不能表示在街上偶然遇见人。"}, {"text": "他把蛋糕重复了一半。", "explanation": "这里应该用〈吃〉。“重复”指同一动作或话语再做一次，不能表示吃掉一部分食物；“吃了一半”才是这个意思。"}, {"text": "这个月的工资我重复了一半。", "explanation": "这里应该用〈花〉。“重复”指同一动作或话语再做一次，不能表示用掉、分掉一部分钱；“花了一半”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不能表示再做一次，与“请再……一次”的请求无法搭配。"}, {"text": "重复", "is_correct": true, "explanation": "正确。“重复”指再说或再做一次，符合“没听清楚，请再……一次”的语境。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量或程度，不说“再增加一次”某个动作。"}, {"text": "失败", "is_correct": false, "explanation": "语义：“失败”指没有成功，请对方“再失败一次”没有意义。"}], "explanations": {"忘记": "语义：“忘记”不能表示再做一次，与“请再……一次”的请求无法搭配。", "重复": "正确。“重复”指再说或再做一次，符合“没听清楚，请再……一次”的语境。", "增加": "搭配：“增加”说数量或程度，不说“再增加一次”某个动作。", "失败": "语义：“失败”指没有成功，请对方“再失败一次”没有意义。"}, "sentence_index": 6, "correct_answer": "重复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的眼睛重复了那张照片。", "explanation": "这里应该用〈看〉。“重复”指同一动作再做一次，不能表示眼睛注视某物。"}, {"text": "这个消息让我重复了很久的惊讶。", "explanation": "这里应该用〈感到〉。“重复”指同一动作再做一次，不能用来表示心里的感受持续很久。"}, {"text": "这座山重复了一遍。", "explanation": "这里应该用〈爬〉，并以人作主语：“我们爬了那座山一遍”。“重复”的主语不能是山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师又把这个问题重复着一遍。", "corrected_sentence": "老师又把这个问题重复了一遍。", "error_description": "错误在“重复着”：“着”表示动作持续，不能用于一次性的重复；应改为“重复了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把这个数字重复了两个。", "corrected_sentence": "我已经把这个数字重复了两遍。", "error_description": "错误在量词“两个”：重复的次数应用“遍”或“次”，“个”用于事物，不能用来计算动作的次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”与“打开”的意思相对，是“开启”（打开）的反义词。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示深入探讨，与“开启”没有反义关系。"}, {"text": "安装", "is_correct": false, "explanation": "“安装”表示把设备装上，与“开启”没有反义关系。"}, {"text": "发现", "is_correct": false, "explanation": "“发现”表示看到或找到原来没注意的事物，与“开启”没有反义关系。"}], "correct_answer": "关闭", "explanations": {"关闭": "“关闭”与“打开”的意思相对，是“开启”（打开）的反义词。", "研究": "“研究”表示深入探讨，与“开启”没有反义关系。", "安装": "“安装”表示把设备装上，与“开启”没有反义关系。", "发现": "“发现”表示看到或找到原来没注意的事物，与“开启”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关闭", "is_correct": true, "explanation": "“关闭”与“打开”的意思相对，是“开启”（打开）的反义词。"}, {"text": "购买", "is_correct": false, "explanation": "“购买”表示付钱取得东西，与“开启”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”表示把东西从一处运到另一处，与“开启”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”表示用脑子想问题，与“开启”没有反义关系。"}], "correct_answer": "关闭", "explanations": {"关闭": "“关闭”与“打开”的意思相对，是“开启”（打开）的反义词。", "购买": "“购买”表示付钱取得东西，与“开启”没有反义关系。", "搬运": "“搬运”表示把东西从一处运到另一处，与“开启”没有反义关系。", "思考": "“思考”表示用脑子想问题，与“开启”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打开或开始做某事。", "primary_collocate": null, "pronunciation": "kāi qǐ", "ipa": "kʰai˥ tɕʰi˨˩", "syllable_count": 2, "sentences": [{"text": "请按这个键开启电视。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用钥匙开启了大门。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的一年开启了我们的新生活。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机可以用指纹开启。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面开启了两国的合作。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师开启了今天的课程。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开启电脑后，请先输入密码。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开启了人生的新阶段。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请开启空调，房间太热了。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门要用两把钥匙才能开启。", "target_word": "开启", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开啟", "label": "繁体"}, {"form": "开启了", "label": "体标"}, {"form": "开启过", "label": "体标"}], "register": "书面", "sense_fingerprint": "打开门、机器，或开始新事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开启", "is_correct": true, "explanation": "“开启”表示打开电器，符合“按这个键让电视启动”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：按键不能修理电视，句意不通。"}, {"text": "搬", "is_correct": false, "explanation": "语义：按键不能把电视搬走，句意不通。"}, {"text": "点", "is_correct": false, "explanation": "搭配：“点”一般说“点火”“点菜”，不说“点电视”。"}], "explanations": {"开启": "“开启”表示打开电器，符合“按这个键让电视启动”的语境。", "修理": "语义：按键不能修理电视，句意不通。", "搬": "语义：按键不能把电视搬走，句意不通。", "点": "搭配：“点”一般说“点火”“点菜”，不说“点电视”。"}, "sentence_index": 0, "correct_answer": "开启"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开启了一本旧书。", "explanation": "这里应该用〈翻开〉。“开启”多用于门、机器、新阶段等，书本要说“翻开”。"}, {"text": "小宝宝刚开启了眼睛。", "explanation": "这里应该用〈睁开〉。“开启”不用于眼睛，眼睛张开要说“睁开”。"}, {"text": "妈妈开启了一根蜡烛。", "explanation": "这里应该用〈点燃〉。“开启”用于打开门、机器等，蜡烛要说“点燃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开启", "is_correct": true, "explanation": "“开启”表示打开电脑，符合“开启电脑后输入密码”的语境。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是破坏，与“之后先输入密码”的正常操作不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“之后输入密码”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面一般接歌曲，不能接“电脑”。"}], "explanations": {"开启": "“开启”表示打开电脑，符合“开启电脑后输入密码”的语境。", "砸": "语义：“砸”是破坏，与“之后先输入密码”的正常操作不符。", "扔": "语义：“扔”是丢弃，与“之后输入密码”的语境不符。", "唱": "搭配：“唱”后面一般接歌曲，不能接“电脑”。"}, "sentence_index": 6, "correct_answer": "开启"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她开启了新衣服，很漂亮。", "explanation": "这里应该用〈穿上〉。“开启”用于门、机器或新阶段，不说“开启衣服”，穿衣服要说“穿上”。"}, {"text": "奶奶开启了老花镜。", "explanation": "这里应该用〈戴上〉。“开启”不能用于眼镜，戴眼镜要说“戴上”。"}, {"text": "他开启了那个绳结。", "explanation": "这里应该用〈解开〉。“开启”用于门、机器等，解开绳结要说“解开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸昨天开启那台老机器。", "corrected_sentence": "爸爸昨天开启了那台老机器。", "error_description": "错误：表示已经完成的动作，“开启”后面要加“了”。有“昨天”这样的过去时间词时，应说“开启了那台老机器”，不能说“开启那台老机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把大门开启。", "corrected_sentence": "他把大门开启了。", "error_description": "错误：“把”字句缺少“了”。“把”字句的动词后面要有“了”等成分，应说“他把大门开启了”，不能说“他把大门开启”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
