INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手抄本是一个人用手写的书。", "primary_collocate": null, "pronunciation": "shǒu chāo běn", "ipa": "ʂoʊ̯˨˩˦ ʈʂʰɑʊ̯˥ pən˨˩˦", "syllable_count": 3, "sentences": [{"text": "这本手抄本有三百年的历史了。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术出现以前，书大多是手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一本很旧的手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一本爷爷留下的手抄本，里面是古诗。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手抄本的字迹保存得很好。", "target_word": "手抄本", "complexity_tier": "T3", "furigana": "zhè běn shǒu chāo běn de zì jì bǎo cún de hěn hǎo", "sentence_source": "generated"}, {"text": "老师给我们看了一本唐代的手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手抄本是人一个字一个字写出来的。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为是手抄本，所以每一本都不一样。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆很小心地保存着这些手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手抄本不是印的，是用笔写的。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "古代手抄本", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手抄写而成的书，不是印刷的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手抄本", "is_correct": true, "explanation": "“手抄本”是手写的书，可以有三百年的历史。"}, {"text": "笔记本", "is_correct": false, "explanation": "语义：“笔记本”是现代的记事本，不可能有三百年的历史。"}, {"text": "电子书", "is_correct": false, "explanation": "语义：“电子书”是电子设备上的书，不可能有三百年的历史。"}, {"text": "练习本", "is_correct": false, "explanation": "搭配：“有……历史”多用于古旧或有来历的物品，“练习本”不与之搭配。"}], "explanations": {"手抄本": "“手抄本”是手写的书，可以有三百年的历史。", "笔记本": "语义：“笔记本”是现代的记事本，不可能有三百年的历史。", "电子书": "语义：“电子书”是电子设备上的书，不可能有三百年的历史。", "练习本": "搭配：“有……历史”多用于古旧或有来历的物品，“练习本”不与之搭配。"}, "sentence_index": 0, "correct_answer": "手抄本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里有一张很旧的手抄本。", "explanation": "这里应该用〈本〉。手抄本是书，量词用“本”，不用“张”。"}, {"text": "这本手抄本是今年刚出版的新书。", "explanation": "“手抄本”是手写的书，不是出版社出版的，与“刚出版”矛盾。"}, {"text": "这本手抄本是机器一分钟印出来的，很快就做好了。", "explanation": "“手抄本”是手写的书，不是机器印刷的，与“机器印出来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手抄本", "is_correct": true, "explanation": "“手抄本”是一个字一个字手写出来的，符合句意。"}, {"text": "印刷品", "is_correct": false, "explanation": "语义：“印刷品”是机器印出来的，不是人手写的。"}, {"text": "复印件", "is_correct": false, "explanation": "语义：“复印件”是复印机做的，不是人手写的。"}, {"text": "打印稿", "is_correct": false, "explanation": "搭配：“一个字一个字写”指手写，与“打印”不搭配。"}], "explanations": {"手抄本": "“手抄本”是一个字一个字手写出来的，符合句意。", "印刷品": "语义：“印刷品”是机器印出来的，不是人手写的。", "复印件": "语义：“复印件”是复印机做的，不是人手写的。", "打印稿": "搭配：“一个字一个字写”指手写，与“打印”不搭配。"}, "sentence_index": 6, "correct_answer": "手抄本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本手抄本是我用键盘一个字一个字打出来的。", "explanation": "“手抄本”指用手写的书，用键盘打出来的不能叫手抄本。"}, {"text": "这本手抄本上的字都是用印章盖上去的。", "explanation": "“手抄”指用手写，用印章盖上的字不算手抄。"}, {"text": "这本手抄本一共印了一万本，全部送给了学生。", "explanation": "“手抄本”每一本都是手写的，不能大量印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把爷爷的一张手抄本借给了朋友。", "corrected_sentence": "他把爷爷的一本手抄本借给了朋友。", "error_description": "“手抄本”是书，量词应用“本”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本手抄本纸已经很旧了。", "corrected_sentence": "这本手抄本的纸已经很旧了。", "error_description": "“手抄本”修饰“纸”时中间要加“的”，应说“这本手抄本的纸”；省去“的”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
