INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西是怎么搭起来的，像积木那样一个搭一个的样子。", "primary_collocate": null, "pronunciation": "jié gòu", "ipa": "tɕjɛ˧˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这座桥的结构很稳，可以通过重型卡车。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的结构有问题，墙上出现了裂缝。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具的结构简单，孩子很快就搭好了。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师检查了大楼的结构，没有发现危险。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的结构是用四根木条搭起来的。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看图，说一说这台机器的结构。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "积木的结构是一块放在另一块上面。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，木头房子的结构比较安全。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架的结构很简单，一个人就能装好。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这座铁塔的结构是怎么搭的。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "結構", "label": "繁体"}, {"form": "结构图", "label": "复合"}], "register": "中性", "sense_fingerprint": "实物各部分搭配连接的方式与样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构", "is_correct": true, "explanation": "“结构”指桥各部分搭配连接的方式，与“很稳，可以通过重型卡车”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“稳”说状态，不说“颜色很稳”。"}, {"text": "速度", "is_correct": false, "explanation": "语义：桥没有速度，“速度很稳”与句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指食物或气味的特点，“这座桥的味道很稳”不成立。"}], "explanations": {"结构": "“结构”指桥各部分搭配连接的方式，与“很稳，可以通过重型卡车”相合。", "颜色": "搭配：“稳”说状态，不说“颜色很稳”。", "速度": "语义：桥没有速度，“速度很稳”与句意不通。", "味道": "语义：味道指食物或气味的特点，“这座桥的味道很稳”不成立。"}, "sentence_index": 0, "correct_answer": "结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人的结构很开朗，每天都笑个不停。", "explanation": "这里应该用〈性格〉。结构指实物各部分搭配连接的方式，不能用来形容人的性格。"}, {"text": "这座大楼的结构很鲜艳，远处都能看见。", "explanation": "这里应该用〈颜色〉。说鲜艳、明亮用“颜色”，“结构”指各部分搭配连接的方式，不能描述颜色。"}, {"text": "工程师检查了大楼的一首结构，没有发现危险。", "explanation": "这里应该用〈种〉。“首”是量词，用于诗、歌、曲子，不用于结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构", "is_correct": true, "explanation": "“结构”指积木各块的搭配方式，“一块放在另一块上面”正是这种搭配。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量不能“放在另一块上面”，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，“积木的颜色是一块放在另一块上面”不通。"}, {"text": "音色", "is_correct": false, "explanation": "搭配：“音色”指声音的特点，不用于描述积木。"}], "explanations": {"结构": "“结构”指积木各块的搭配方式，“一块放在另一块上面”正是这种搭配。", "重量": "语义：重量不能“放在另一块上面”，句意不通。", "颜色": "语义：颜色指色彩，“积木的颜色是一块放在另一块上面”不通。", "音色": "搭配：“音色”指声音的特点，不用于描述积木。"}, "sentence_index": 6, "correct_answer": "结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的结构很活泼，课间总是跑来跑去。", "explanation": "这里应该用〈性格〉。结构指实物各部分搭配连接的方式，不能用来形容人的性格。"}, {"text": "这座铁塔的结构有三百米高。", "explanation": "这里应该用〈高度〉。说高矮用“高度”，“结构”指各部分搭配连接的方式，不说有多高。"}, {"text": "这只结构很稳，能承受很大的风。", "explanation": "这里应该用〈个〉或〈种〉。“只”是用于动物或成对器物的量词，不用于结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看到这座塔的一只结构很特别。", "corrected_sentence": "我看到这座塔的一种结构很特别。", "error_description": "“结构”的量词应用“种”，“只”用于动物或成对的东西，不用于结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座铁塔的很复杂结构，设计师花了很久。", "corrected_sentence": "这座铁塔的很复杂的结构，设计师花了很久。", "error_description": "“很复杂”修饰“结构”时，“很复杂”和名词之间要加“的”，应说“很复杂的结构”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简单", "is_correct": true, "explanation": "正确。简单与复杂互为反义词，指事物的部分少、容易理解。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈形容水等透明，与复杂没有反义关系。"}, {"text": "雪白", "is_correct": false, "explanation": "雪白形容颜色，与复杂没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与复杂没有反义关系。"}], "correct_answer": "简单", "explanations": {"简单": "正确。简单与复杂互为反义词，指事物的部分少、容易理解。", "清澈": "清澈形容水等透明，与复杂没有反义关系。", "雪白": "雪白形容颜色，与复杂没有反义关系。", "柔软": "柔软形容质地，与复杂没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简单", "is_correct": true, "explanation": "正确。简单与复杂互为反义词，指事物的部分少、容易理解。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线，与复杂没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容环境或状态，与复杂没有反义关系。"}, {"text": "冰凉", "is_correct": false, "explanation": "冰凉形容温度，与复杂没有反义关系。"}], "correct_answer": "简单", "explanations": {"简单": "正确。简单与复杂互为反义词，指事物的部分少、容易理解。", "明亮": "明亮形容光线，与复杂没有反义关系。", "安静": "安静形容环境或状态，与复杂没有反义关系。", "冰凉": "冰凉形容温度，与复杂没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多部分，不容易理解或做好的。", "primary_collocate": null, "pronunciation": "fù zá", "ipa": "fu˥˩ tsa˧˥", "syllable_count": 2, "sentences": [{"text": "这道数学题太复杂了，我不会做。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的关系很复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地图看起来很复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把事情想得那么复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的用法不复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天的心情很复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事比你想的复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的交通越来越复杂。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复杂的问题，老师讲得很清楚。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事有点复杂，我看了两遍。", "target_word": "复杂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复杂化", "label": "复合"}, {"form": "复杂性", "label": "复合"}, {"form": "複雜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "部分多、不容易理解或处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb44a393-77f6-42c1-bc0b-0d5ca4c2aee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复杂", "is_correct": true, "explanation": "正确。“这道数学题太……了，我不会做”，说题目难，正合适。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”描述光线，不能形容数学题。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多形容环境或人的状态，不能形容题目。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不能形容数学题。"}], "explanations": {"复杂": "正确。“这道数学题太……了，我不会做”，说题目难，正合适。", "明亮": "语义：“明亮”描述光线，不能形容数学题。", "安静": "搭配：“安静”多形容环境或人的状态，不能形容题目。", "甜": "语义：“甜”描述味道，不能形容数学题。"}, "sentence_index": 0, "correct_answer": "复杂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水很复杂，喝下去很凉快。", "explanation": "这里应该用〈凉〉。复杂指事物的部分多、难以理解，水的凉热不能用复杂来形容。"}, {"text": "这件衣服价格很复杂，只要一块钱。", "explanation": "这里应该用〈便宜〉。复杂指事物的部分多、难以理解，价格低要说便宜，不能用复杂。"}, {"text": "这张纸很复杂，只写了一个字。", "explanation": "这里应该用〈简单〉。复杂指事物的部分多、难以理解，只写了一个字的纸要说简单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复杂", "is_correct": true, "explanation": "正确。“这件事比你想的……”，说事情比预想的难，正合适。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水等透明，不能形容事情。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，不能形容事情。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”形容形状，不能形容事情。"}], "explanations": {"复杂": "正确。“这件事比你想的……”，说事情比预想的难，正合适。", "清澈": "语义：“清澈”形容水等透明，不能形容事情。", "雪白": "体貌：“雪白”形容颜色，不能形容事情。", "圆": "体貌：“圆”形容形状，不能形容事情。"}, "sentence_index": 6, "correct_answer": "复杂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高很复杂，只有一米五。", "explanation": "这里应该用〈矮〉。复杂指事物的部分多、难以理解，身高的高矮要说矮，不能用复杂。"}, {"text": "她的体重很复杂，只有四十公斤。", "explanation": "这里应该用〈轻〉。复杂指事物的部分多、难以理解，体重的轻重要说轻，不能用复杂。"}, {"text": "他的年龄很复杂，今年才十岁。", "explanation": "这里应该用〈小〉。复杂指事物的部分多、难以理解，年龄的大小要说小，不能用复杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题没复杂，我一看就会。", "corrected_sentence": "这道题不复杂，我一看就会。", "error_description": "错误：“没复杂”；正确：“不复杂”。单独作谓语否定形容词时要用“不”，不能用“没”（“没有……那么复杂”是另一类比较句，不是这里的错误）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划有点复杂得，大家得慢慢来。", "corrected_sentence": "这个计划有点复杂，大家得慢慢来。", "error_description": "错误：“复杂得”；正确：“复杂”。“复杂”后面直接停顿，不能加结构助词“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8044f56-a0a3-4482-810e-7650c80647ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
