INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被别人管着，不能自己做主。", "primary_collocate": null, "pronunciation": "shòu zhì yú", "ipa": "ʂoʊ̯˥˩ ʈʂɻ̩˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "他从小受制于父母，什么都不能自己选。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚结婚时，处处受制于婆婆。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子受制于哥哥，不敢说话。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司受制于老板一个人，没人敢提意见。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想一辈子受制于别人。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小国常常受制于大国。", "target_word": "受制于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他欠了很多钱，只好受制于债主。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "员工受制于经理，不能自己决定。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在家里，他总是受制于妻子。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不愿受制于人，所以自己开了店。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受制于", "label": "基本形式"}, {"form": "受制於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人被另一个人或势力管着，失去自主权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2efa2384-c1dd-4c37-a182-92a2f89de8d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独立于", "is_correct": false, "explanation": "语义：“独立于”表示不受约束、自己做主，与“什么都不能自己选”矛盾。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“他从小受制于父母，什么都不能自己选”表示被父母管着，不能自主，与语境一致。"}, {"text": "自立于", "is_correct": false, "explanation": "语义：“自立于”指能够自己站立、自主做事，与“不能自己选”的语境相反。"}, {"text": "受敬于", "is_correct": false, "explanation": "搭配：“受敬”指被人尊敬，不能用来描述父母对孩子的约束关系。"}], "explanations": {"独立于": "语义：“独立于”表示不受约束、自己做主，与“什么都不能自己选”矛盾。", "受制于": "正确：“他从小受制于父母，什么都不能自己选”表示被父母管着，不能自主，与语境一致。", "自立于": "语义：“自立于”指能够自己站立、自主做事，与“不能自己选”的语境相反。", "受敬于": "搭配：“受敬”指被人尊敬，不能用来描述父母对孩子的约束关系。"}, "sentence_index": 0, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他受制于老师的一句话，决定改行。", "explanation": "这里应该用〈受启发〉。受制于表示被约束，含消极意思；老师的一句话带来的是启发，应说〈受启发〉。"}, {"text": "这家公司受制于老板的帮助，业绩越来越好。", "explanation": "〈受制于〉含被管束、不能自主的消极意思，不能用于“帮助”这类正面关系。"}, {"text": "这孩子受制于一只小猫，每天都在院子里玩耍。", "explanation": "这里应该用〈陪伴〉。受制于要求控制者能管束人，小猫不能管束孩子；这里描述的是陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受宠于", "is_correct": false, "explanation": "语义：“受宠”指得到宠爱，与“欠了很多钱，只好……”的窘迫语境不符。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“欠了很多钱，只好受制于债主”表示被债主管着、无法自主，与语境一致。"}, {"text": "受邀于", "is_correct": false, "explanation": "搭配：“受邀”指接受邀请，不能用于欠债者与债主之间的关系。"}, {"text": "受赏于", "is_correct": false, "explanation": "语义：“受赏”指得到奖赏，与“欠钱”的语境相反。"}], "explanations": {"受宠于": "语义：“受宠”指得到宠爱，与“欠了很多钱，只好……”的窘迫语境不符。", "受制于": "正确：“欠了很多钱，只好受制于债主”表示被债主管着、无法自主，与语境一致。", "受邀于": "搭配：“受邀”指接受邀请，不能用于欠债者与债主之间的关系。", "受赏于": "语义：“受赏”指得到奖赏，与“欠钱”的语境相反。"}, "sentence_index": 6, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她受制于朋友的祝福，很激动地哭了起来。", "explanation": "这里应该用〈得到〉。受制于表示被约束，含消极意思；朋友的祝福带来的是支持，应说〈得到〉。"}, {"text": "她受制于朋友的赞美，所以更加努力。", "explanation": "这里应该用〈受鼓舞〉。受制于表示被约束，含消极意思；朋友的赞美带来的是激励，应说〈受鼓舞〉。"}, {"text": "她受制于一份录取通知，立刻去了学校。", "explanation": "这里应该用〈接到〉。受制于表示被约束，含消极意思；录取通知是喜讯，应说〈接到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从小受制于了家里的安排，很少有自己的时间。", "corrected_sentence": "她从小受制于家里的安排，很少有自己的时间。", "error_description": "错误在于在“于”后面多加了“了”。“受制于”是一个固定结构，“于”后面直接接宾语，不能插入“了”；正确说法是“受制于家里的安排”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来不愿被受制于人，独自创业。", "corrected_sentence": "她从来不愿受制于人，独自创业。", "error_description": "错误在于在“受制于”前面多加了“被”。“受制于”本身已表示被动，前面不能再加“被”；正确说法是“不愿受制于人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1868310-7d36-4fb0-bf71-06d69048f60c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拉向", "is_correct": true, "explanation": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。"}, {"text": "收藏", "is_correct": false, "explanation": "无反义关系：“收藏”指妥善保存物品，与物体的移动方向无关。"}, {"text": "朗读", "is_correct": false, "explanation": "无反义关系：“朗读”指大声读出文字，与推动物体无关。"}, {"text": "编写", "is_correct": false, "explanation": "无反义关系：“编写”指编辑、撰写，与物理移动无关。"}], "correct_answer": "拉向", "explanations": {"拉向": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。", "收藏": "无反义关系：“收藏”指妥善保存物品，与物体的移动方向无关。", "朗读": "无反义关系：“朗读”指大声读出文字，与推动物体无关。", "编写": "无反义关系：“编写”指编辑、撰写，与物理移动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拉向", "is_correct": true, "explanation": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原样，与物体的移动方向无关。"}, {"text": "留下", "is_correct": false, "explanation": "无反义关系：“留下”指不离开某处，与“推向”表示的推动义无关。"}, {"text": "挑选", "is_correct": false, "explanation": "无反义关系：“挑选”指选择，与推动物体无关。"}], "correct_answer": "拉向", "explanations": {"拉向": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。", "保持": "无反义关系：“保持”指维持原样，与物体的移动方向无关。", "留下": "无反义关系：“留下”指不离开某处，与“推向”表示的推动义无关。", "挑选": "无反义关系：“挑选”指选择，与推动物体无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具让东西朝一个方向移动。", "primary_collocate": null, "pronunciation": "tuī xiàng", "ipa": "tʰweɪ˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他用力把箱子推向墙边。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把球推向了门口。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小车推向超市的出口。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用棍子把石头推向河边。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把椅子推向桌子。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盘子推向我，说你先吃。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢把轮椅推向公园。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把桌子推向窗边，坐下看书。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子推向桌子中间。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具车推向沙发下面。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或工具把具体物体推到某个方向或地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88dc21c-87f3-4b7c-a129-ff58d71b1ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：推向，用手或工具让东西朝一个方向移动。"}, {"text": "推想", "is_correct": false, "explanation": "推想与推向只有第二个音节声调不同（xiǎng 与 xiàng），意思是推测、推断，不指移动具体物体。"}, {"text": "退向", "is_correct": false, "explanation": "退向与推向只有第一个音节声调不同（tuì 与 tuī），意思是向后退，动作不同。"}, {"text": "吹向", "is_correct": false, "explanation": "吹向与推向只有声母不同（ch 与 t），意思是吹动，动作不同。"}], "explanations": {"推向": "正确：推向，用手或工具让东西朝一个方向移动。", "推想": "推想与推向只有第二个音节声调不同（xiǎng 与 xiàng），意思是推测、推断，不指移动具体物体。", "退向": "退向与推向只有第一个音节声调不同（tuì 与 tuī），意思是向后退，动作不同。", "吹向": "吹向与推向只有声母不同（ch 与 t），意思是吹动，动作不同。"}, "sentence_index": null, "correct_answer": "推向"}, "level_3": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：“他用力把箱子推向墙边”表示用力使箱子朝墙边移动。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”针对距离或时间，不能与“墙边”这样的处所搭配。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”只用于可以吞咽的东西，箱子不能被吞下。"}, {"text": "吐出", "is_correct": false, "explanation": "语义：“吐出”指从口中排出，与用力推箱子的动作不符。"}], "explanations": {"推向": "正确：“他用力把箱子推向墙边”表示用力使箱子朝墙边移动。", "缩短": "搭配：“缩短”针对距离或时间，不能与“墙边”这样的处所搭配。", "吞下": "语义：“吞下”只用于可以吞咽的东西，箱子不能被吞下。", "吐出": "语义：“吐出”指从口中排出，与用力推箱子的动作不符。"}, "sentence_index": 0, "correct_answer": "推向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵笑声推向了屋外。", "explanation": "这里应该用〈传向〉。推向需要外力施加在具体物体上，笑声是声音，不能被推动，应说传向。"}, {"text": "小猫慢慢推向了碗。", "explanation": "这里应该用〈靠近〉。推向需要带一个被推的物体，小猫自己走近碗要用靠近。"}, {"text": "气球推向了天空。", "explanation": "这里应该用〈飘向〉。推向需要外力施加在物体上，气球自己飘动要用飘向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：“老人慢慢把轮椅推向公园”表示老人用手推着轮椅朝公园的方向移动。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指用力使物体破裂，与“慢慢”和正常推动的动作相矛盾。"}, {"text": "举起", "is_correct": false, "explanation": "配价：“举起”要求直接的受事，不能带“公园”这样的处所作宾语。"}, {"text": "折叠", "is_correct": false, "explanation": "配价：“折叠”针对可以折起的物品，不能表示朝处所的移动。"}], "explanations": {"推向": "正确：“老人慢慢把轮椅推向公园”表示老人用手推着轮椅朝公园的方向移动。", "打碎": "语义：“打碎”指用力使物体破裂，与“慢慢”和正常推动的动作相矛盾。", "举起": "配价：“举起”要求直接的受事，不能带“公园”这样的处所作宾语。", "折叠": "配价：“折叠”针对可以折起的物品，不能表示朝处所的移动。"}, "sentence_index": 6, "correct_answer": "推向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推向了一阵花香。", "explanation": "这里应该用〈闻到〉。推向的宾语必须是具体物体，花香是气味，不能被推动，只能说闻到。"}, {"text": "鱼儿推向了深水。", "explanation": "这里应该用〈游向〉。推向需要施力的主体，鱼自己游动要用游向。"}, {"text": "他的脚步推向了门口。", "explanation": "这里应该用〈走向〉。推向需要施力的物体，脚步是人行走的动作，不能被推动，应说走向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷用手把椅子推向了了门边。", "corrected_sentence": "爷爷用手把椅子推向了门边。", "error_description": "错误：“推向”后的“了”重复出现。应只保留一个“了”，写作“推向了门边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小华把一只小车推向了车库。", "corrected_sentence": "小华把一辆小车推向了车库。", "error_description": "错误形式是“一只小车”，正确形式是“一辆小车”。小车是有轮的交通工具，量词应用“辆”，“只”不能用于小车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
