INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "系统就像一个大机器，很多不同的零件一起工作。", "primary_collocate": null, "pronunciation": "xì tǒng", "ipa": "ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个系统太复杂，我不会用。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑系统坏了，今天不能上网。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的新系统可以让学生在网上选课。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个系统由很多小部分组成。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院用一个系统管理所有病人的信息。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的地铁系统很方便。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司换了新的管理系统，大家都要重新学习。", "target_word": "系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，教育系统需要更多好老师。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套系统每天自动记录天气的变化。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机的系统需要经常更新。", "target_word": "系统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "管理系统", "label": "复合"}, {"form": "操作系统", "label": "复合"}, {"form": "系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由许多部分组成、一起运作的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b67ea2c-4f99-4305-8a7b-096353e3f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系统", "is_correct": true, "explanation": "系统：指由许多部分组成、一起运作的整体，既可以“复杂”，也可以“使用”，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是供人观赏的地方，不能用“我不会用”来形容。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“用”不能跟“性格”搭配，“我不会用性格”说不通。"}, {"text": "食品", "is_correct": false, "explanation": "语义：“食品”指可以吃的东西，说它“太复杂”、“我不会用”都不合理。"}], "explanations": {"系统": "系统：指由许多部分组成、一起运作的整体，既可以“复杂”，也可以“使用”，符合句意。", "花园": "语义：“花园”是供人观赏的地方，不能用“我不会用”来形容。", "性格": "搭配：“用”不能跟“性格”搭配，“我不会用性格”说不通。", "食品": "语义：“食品”指可以吃的东西，说它“太复杂”、“我不会用”都不合理。"}, "sentence_index": 0, "correct_answer": "系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司买了一只新系统，大家都很满意。", "explanation": "这里应该用〈套〉。系统用“套”或“个”计量，“只”一般用于动物或成对物品中的一个。"}, {"text": "这个系统由五个人组成，每周都在学校礼堂演出。", "explanation": "这里应该用〈乐队〉。系统指由部件构成、一起运作的整体，不指一群演出的人。"}, {"text": "这支系统由很多部件组成，运转得很稳定。", "explanation": "这里应该用〈套〉。“支”用于队伍、细长的东西，系统不用“支”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系统", "is_correct": true, "explanation": "系统：指由许多部分组成、一起运作的整体，与“管理”搭配，符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：“花瓶”是盛花的器物，与“新的管理”没有关系，句意不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”指可以喝的东西，不能作为“新的管理”的对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“管理”不能跟“天气”搭配，“管理天气”说不通。"}], "explanations": {"系统": "系统：指由许多部分组成、一起运作的整体，与“管理”搭配，符合句意。", "花瓶": "语义：“花瓶”是盛花的器物，与“新的管理”没有关系，句意不通。", "饮料": "语义：“饮料”指可以喝的东西，不能作为“新的管理”的对象。", "天气": "搭配：“管理”不能跟“天气”搭配，“管理天气”说不通。"}, "sentence_index": 6, "correct_answer": "系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上吃一个系统当早餐。", "explanation": "系统指由许多部分组成、一起运作的整体，不是食物，不能吃。"}, {"text": "这个系统是一根细小的螺丝。", "explanation": "系统指由许多部分组成的整体，一根螺丝只是其中的一个零件，不能称为系统。"}, {"text": "这个系统每天要喝三杯水。", "explanation": "系统指由许多部分组成、一起运作的整体，不是生物，不需要喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司换了一条新系统。", "corrected_sentence": "公司换了一套新系统。", "error_description": "错误在量词。“系统”应用“套”或“个”计量，“条”用于细长的东西，不能用来计量系统。应改为“一套新系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些系统们都很好用。", "corrected_sentence": "这些系统都很好用。", "error_description": "错误在“系统”后多加了“们”。“系统”是无生命的名词，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
