INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西很厉害的人。", "primary_collocate": null, "pronunciation": "gōng jiàng", "ipa": "kʊŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他是镇上最好的工匠，什么都会做。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工匠做的桌子又结实又好看。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠用木头做了一只小船。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当工匠，自己做家具。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老工匠的手艺让大家很佩服。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠正在店里修一把旧椅子。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些碗是一位工匠做的。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠做东西很认真，一点也不马虎。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的工匠会打铁，也会做门。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位年轻工匠已经做了三年灯笼。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "工匠精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "做东西很厉害的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88dc21c-87f3-4b7c-a129-ff58d71b1ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工匠", "is_correct": true, "explanation": "正确。“工匠”指做东西很厉害的人，与“什么都会做”的意思一致。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为职业，不是能做各种东西的人，与“什么都会做”不符。"}, {"text": "将军", "is_correct": false, "explanation": "语义：将军是军中职务，与“做东西”没有关系。"}, {"text": "小偷", "is_correct": false, "explanation": "语域：“小偷”含贬义，与“最好的”的赞扬语气不合。"}], "explanations": {"工匠": "正确。“工匠”指做东西很厉害的人，与“什么都会做”的意思一致。", "歌手": "语义：歌手以唱歌为职业，不是能做各种东西的人，与“什么都会做”不符。", "将军": "语义：将军是军中职务，与“做东西”没有关系。", "小偷": "语域：“小偷”含贬义，与“最好的”的赞扬语气不合。"}, "sentence_index": 0, "correct_answer": "工匠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工匠在工地上安排大家的工作。", "explanation": "这里应该用〈工头〉。工匠指凭手艺做东西的人，负责调度和安排工作要用“工头”。"}, {"text": "这位工匠每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。工匠指凭手艺做东西的人，给病人看病的人要说“医生”。"}, {"text": "这位工匠每天在超市里收银。", "explanation": "这里应该用〈收银员〉。工匠指凭手艺做东西的人，收银的人要说“收银员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工匠", "is_correct": true, "explanation": "正确。“工匠”指做东西很厉害的人，与“做”碗的动作相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机以驾驶为职业，不做碗，句中“做”的人不能是司机。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师处理法律事务，与制作碗毫无关系。"}, {"text": "演员", "is_correct": false, "explanation": "配价：“做”要求施事是能制作器物的人，演员不能充当这个角色。"}], "explanations": {"工匠": "正确。“工匠”指做东西很厉害的人，与“做”碗的动作相符。", "司机": "语义：司机以驾驶为职业，不做碗，句中“做”的人不能是司机。", "律师": "语义：律师处理法律事务，与制作碗毫无关系。", "演员": "配价：“做”要求施事是能制作器物的人，演员不能充当这个角色。"}, "sentence_index": 6, "correct_answer": "工匠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的工匠很有耐心。", "explanation": "这里应该用〈老师〉。工匠指凭手艺做东西的人，教书的人要说“老师”。"}, {"text": "这位工匠每天凌晨去火场灭火。", "explanation": "这里应该用〈消防员〉。工匠指凭手艺做东西的人，灭火救人的人要说“消防员”。"}, {"text": "这位工匠在舞台上唱了一首歌。", "explanation": "这里应该用〈歌手〉。工匠指凭手艺做东西的人，舞台上唱歌的人要说“歌手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只工匠帮我修好了门锁。", "corrected_sentence": "那位工匠帮我修好了门锁。", "error_description": "量词错误。工匠指人，应说“那位工匠”；“那只”多用于动物或器物，错误的是量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位工匠做了完一张桌子。", "corrected_sentence": "那位工匠做完了一张桌子。", "error_description": "补语位置错误。“做完”是动补结构，应说“做完了”；“做了完”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
