INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像一圈一圈绕上去的样子，比如螺丝上的纹路。", "primary_collocate": null, "pronunciation": "luó xuán", "ipa": "lwɔ˧˥ ɕɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "螺丝上的螺旋，让它能拧进木头里。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本子上画了一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，这个贝壳的螺旋多漂亮！", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水倒进下水口，转成一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在天上飞出一道螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶盖里面有细细的螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种糖的螺旋是红白两色的。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇睡觉时，身体卷成了螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风的云图像一个大螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用手指在桌上画螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "螺旋桨", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一圈一圈绕上去的样子，如螺丝纹路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c88dc21c-87f3-4b7c-a129-ff58d71b1ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "螺旋", "is_correct": true, "explanation": "正确。“螺旋”指一圈圈绕上去的纹路，螺丝上的螺旋让它能拧进木头。"}, {"text": "水管", "is_correct": false, "explanation": "搭配：螺丝上的纹路不能用“水管”来描述，“螺丝上的水管”搭配不当。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是点燃照明的物品，与螺丝的纹路毫不相关。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是遮挡用的织物，无法让螺丝拧进木头。"}], "explanations": {"螺旋": "正确。“螺旋”指一圈圈绕上去的纹路，螺丝上的螺旋让它能拧进木头。", "水管": "搭配：螺丝上的纹路不能用“水管”来描述，“螺丝上的水管”搭配不当。", "蜡烛": "语义：蜡烛是点燃照明的物品，与螺丝的纹路毫不相关。", "窗帘": "语义：窗帘是遮挡用的织物，无法让螺丝拧进木头。"}, "sentence_index": 0, "correct_answer": "螺旋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手拧紧了一个螺旋。", "explanation": "这里应该用〈螺丝〉。螺旋指一圈圈绕上去的纹路，拧紧的是螺丝这个零件。"}, {"text": "他用螺旋擦了擦脸上的汗。", "explanation": "这里应该用〈毛巾〉。螺旋指一圈圈绕上去的纹路，擦汗的东西要说“毛巾”。"}, {"text": "他用一把螺旋打开了门。", "explanation": "这里应该用〈钥匙〉。螺旋指一圈圈绕上去的纹路，开门的东西要说“钥匙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "螺旋", "is_correct": true, "explanation": "正确。“螺旋”指糖上一圈圈盘绕的纹路，与“红白两色”的外观相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数字，不能用颜色来形容，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "体貌：味道是口感，不是可见的外观，不能说成红白两色。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”一般用轻重或数字来形容，不能用“红白两色”来修饰。"}], "explanations": {"螺旋": "正确。“螺旋”指糖上一圈圈盘绕的纹路，与“红白两色”的外观相符。", "价格": "语义：价格是数字，不能用颜色来形容，句意不通。", "味道": "体貌：味道是口感，不是可见的外观，不能说成红白两色。", "重量": "搭配：“重量”一般用轻重或数字来形容，不能用“红白两色”来修饰。"}, "sentence_index": 6, "correct_answer": "螺旋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "布的螺旋被剪断了。", "explanation": "这里应该用〈线头〉。螺旋指一圈圈绕上去的纹路，布上断掉的线要说“线头”。"}, {"text": "这条围巾的螺旋很暖和。", "explanation": "这里应该用〈厚〉。螺旋指纹路，说围巾保暖要用“厚”，不能用“螺旋”来形容。"}, {"text": "他用螺旋抽了一下马。", "explanation": "这里应该用〈鞭子〉。螺旋指一圈圈绕上去的纹路，抽打用的工具要说“鞭子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在木板上画了一颗螺旋。", "corrected_sentence": "我在木板上画了一道螺旋。", "error_description": "量词错误。螺旋是线状的图形，应说“一道螺旋”；“颗”多用于粒状的小东西，错误的是量词“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根绳子绕了成螺旋。", "corrected_sentence": "这根绳子绕成了螺旋。", "error_description": "补语位置错误。“绕成”是动补结构，应说“绕成了”；“绕了成”把补语拆开，语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a64fff1-a9af-45f5-9e8b-0b850bdcb4ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
