INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具在东西上按一下，留下一个印子。", "primary_collocate": null, "pronunciation": "yā yìn", "ipa": "ia˥ in˥˩", "syllable_count": 2, "sentences": [{"text": "他拿印章在纸上压印了一下。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这张卡的角上压印一下。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用小木章在饼干上压印出花样。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板用这个小章在每张票上压印一下。", "target_word": "压印", "complexity_tier": "T3", "furigana": "lǎobǎn yòng zhè ge xiǎozhāng zài měi zhāng piào shàng yāyìn yíxià", "sentence_source": "generated"}, {"text": "工作人员用印章给文件压印日期。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友用模具在泥上压印小花。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用瓶盖在软泥上压印了一个圆圈。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把铜章用力压印在蜡上。", "target_word": "压印", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员在门票上压印了今天的日期。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先用这个小工具在皮子上压印一下。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "压印了", "label": "完成体"}, {"form": "压印着", "label": "持续体"}, {"form": "压印过", "label": "经历体"}, {"form": "压印机", "label": "复合词"}, {"form": "壓印", "label": "繁体"}], "register": "中性", "sense_fingerprint": "压印|动词|用工具在东西上按一下留下印子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48a0f7c-0a18-4c7c-afd7-fbb2dab8e04e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印 yā yìn，指用工具按压留下印子。"}, {"text": "牙印", "is_correct": false, "explanation": "yá（第二声）与 yā（第一声）声调不同，牙印意思是牙齿咬出的印子。"}, {"text": "押韵", "is_correct": false, "explanation": "押韵 yā yùn，yùn 与 yìn 韵母不同（ün 与 in），意思是诗句末尾韵母相同。"}, {"text": "压抑", "is_correct": false, "explanation": "压抑 yāyì 比 压印 yāyìn 少了韵尾 n，意思是压制、抑制。"}], "explanations": {"压印": "压印 yā yìn，指用工具按压留下印子。", "牙印": "yá（第二声）与 yā（第一声）声调不同，牙印意思是牙齿咬出的印子。", "押韵": "押韵 yā yùn，yùn 与 yìn 韵母不同（ün 与 in），意思是诗句末尾韵母相同。", "压抑": "压抑 yāyì 比 压印 yāyìn 少了韵尾 n，意思是压制、抑制。"}, "sentence_index": null, "correct_answer": "压印"}, "level_3": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印：用印章在纸上按压留下印记，与“拿印章”的动作相符。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是用刀分开，与用印章按压不符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬需要用牙齿，与“拿印章”的动作不符。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：烤的对象一般是食物，不能用于纸张。"}], "explanations": {"压印": "压印：用印章在纸上按压留下印记，与“拿印章”的动作相符。", "切": "语义：切是用刀分开，与用印章按压不符。", "咬": "语义：咬需要用牙齿，与“拿印章”的动作不符。", "烤": "搭配：烤的对象一般是食物，不能用于纸张。"}, "sentence_index": 0, "correct_answer": "压印"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用铅笔在纸上压印了一下。", "explanation": "这里应该用〈点〉。压印要靠印章或模具按压出印子，铅笔只能在纸上点出笔迹，不能说压印。"}, {"text": "他轻轻压印了一下孩子的头。", "explanation": "这里应该用〈摸〉。压印用于物体表面，不用于人的头部，轻轻碰触应说摸。"}, {"text": "妈妈用抹布在桌上压印了一下。", "explanation": "这里应该用〈擦〉。擦是摩擦去污，压印是按压留下印记，两者动作不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印：用瓶盖在软泥上按压留下圆形印记，与句意相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍是用刀斩断，与用瓶盖按压不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮的对象是食物，不能用于软泥。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声，无法在软泥上留下圆圈。"}], "explanations": {"压印": "压印：用瓶盖在软泥上按压留下圆形印记，与句意相符。", "砍": "语义：砍是用刀斩断，与用瓶盖按压不符。", "煮": "搭配：煮的对象是食物，不能用于软泥。", "唱": "语义：唱是发声，无法在软泥上留下圆圈。"}, "sentence_index": 6, "correct_answer": "压印"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用剪刀压印了一张窗花。", "explanation": "这里应该用〈剪〉。剪是用刀切断，压印是用模具按压，剪窗花不能说压印。"}, {"text": "妈妈在锅里压印了一碗面条。", "explanation": "这里应该用〈煮〉。煮是加热烹饪，压印是按压留下印记，二者不能混用。"}, {"text": "他用扫帚压印了一下地面。", "explanation": "这里应该用〈扫〉。扫是清除灰尘，压印是留下印记，两者动作不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用印章在箱子上压印了一张编号。", "corrected_sentence": "工人用印章在箱子上压印了一个编号。", "error_description": "量词错误：“编号”应搭配“个”，“张”用于纸张等平面物，应改为“压印了一个编号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅把日期压印给每个纸箱的侧面。", "corrected_sentence": "师傅把日期压印在每个纸箱的侧面。", "error_description": "介词错误：“压印”后引出处所应用“在”，“给”不能用于此处，应为“压印在每个纸箱的侧面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
