INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墨水是写字或画画时用的黑色或彩色的水。", "primary_collocate": null, "pronunciation": "mò shuǐ", "ipa": "mwo˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "弟弟用黑墨水在本子上写名字。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墨水干得很快，不会弄脏手。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从抽屉里拿出一瓶新墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画的时候，他喜欢用彩色墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墨水用完以后，我再去文具店买。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫碰倒了桌上的墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红墨水在水里慢慢散开了。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔里的墨水是绿色的。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的作业本上有一滴墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把墨水放在孩子拿不到的地方。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "墨水瓶", "label": "复合"}, {"form": "黑墨水", "label": "复合"}], "register": "中性", "sense_fingerprint": "墨水：写字、画画用的黑色或彩色的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48a0f7c-0a18-4c7c-afd7-fbb2dab8e04e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粉笔", "is_correct": false, "explanation": "搭配：粉笔是用于黑板的，不用来在本子上写名字，“用黑粉笔在本子上写名字”搭配不当。"}, {"text": "醋", "is_correct": false, "explanation": "搭配：醋是调味品，不能用来写字，“用黑醋在本子上写名字”不成立。"}, {"text": "墨水", "is_correct": true, "explanation": "墨水：墨水是写字用的黑色液体，此处用黑墨水在本子上写名字，正合语境。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：油漆是用来涂刷物体表面的涂料，不能用来在本子上写字。"}], "explanations": {"粉笔": "搭配：粉笔是用于黑板的，不用来在本子上写名字，“用黑粉笔在本子上写名字”搭配不当。", "醋": "搭配：醋是调味品，不能用来写字，“用黑醋在本子上写名字”不成立。", "墨水": "墨水：墨水是写字用的黑色液体，此处用黑墨水在本子上写名字，正合语境。", "油漆": "语义：油漆是用来涂刷物体表面的涂料，不能用来在本子上写字。"}, "sentence_index": 0, "correct_answer": "墨水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在砚台上磨墨水。", "explanation": "这里应该用〈墨〉。磨墨磨的是固体墨条，墨水是液体，不能在砚台上磨。"}, {"text": "他用墨水煮了一锅汤。", "explanation": "这里是把墨水当作食材来煮的意思。墨水是写字、画画用的液体，不能吃，也不能用来煮汤。"}, {"text": "我买了一块墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“块”用于块状的东西，不能用来计量墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木头", "is_correct": false, "explanation": "语义：木头不溶于水，不会在水里慢慢散开，与“慢慢散开了”不合。"}, {"text": "黄油", "is_correct": false, "explanation": "语义：黄油不溶于水，不会在水里慢慢散开，与“慢慢散开了”不合。"}, {"text": "墨水", "is_correct": true, "explanation": "墨水：红墨水是有颜色的液体，倒进水里会慢慢散开，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不会在水里慢慢散开，与“散开”不合。"}], "explanations": {"木头": "语义：木头不溶于水，不会在水里慢慢散开，与“慢慢散开了”不合。", "黄油": "语义：黄油不溶于水，不会在水里慢慢散开，与“慢慢散开了”不合。", "墨水": "墨水：红墨水是有颜色的液体，倒进水里会慢慢散开，符合语境。", "石头": "语义：石头是固体，不会在水里慢慢散开，与“散开”不合。"}, "sentence_index": 6, "correct_answer": "墨水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把墨水涂在嘴唇上当口红。", "explanation": "这里是把墨水当化妆品来用的意思。墨水是写字、画画用的液体，不能涂在嘴唇上。"}, {"text": "我买了一张墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“张”用于纸、桌子等平面的东西。"}, {"text": "我买了一根墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“根”用于细长的东西，不能用于墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小妹妹用一块彩色墨水画了一幅画。", "corrected_sentence": "小妹妹用一瓶彩色墨水画了一幅画。", "error_description": "错误在于量词：墨水是液体，应用“瓶”计量，“块”用于块状的固体，不能用来数墨水。正确形式是“一瓶彩色墨水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把两根墨水放在了桌上。", "corrected_sentence": "我把两瓶墨水放在了桌上。", "error_description": "错误在于量词：墨水是液体，应用“瓶”计量，“根”用于细长的东西，不能用来数墨水。正确形式是“两瓶墨水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
