INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指含有油的性质，比如油性皮肤容易出油。", "primary_collocate": null, "pronunciation": "yóu xìng", "ipa": "iou˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她是油性皮肤，脸上一到中午就出油。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性的皮肤容易长痘痘。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买洗发水以前，先看看你的头发是不是油性。", "target_word": "油性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气热，油性皮肤的人要多洗脸。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟的头发是油性的，每天都要洗。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是油性笔，写在塑料上不容易擦掉。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性皮肤适合用不含油的护肤品。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的皮肤油性大，所以不用厚厚的面霜。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶油性漆有点臭，要开窗用。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说油性和水性的墨水不能混在一起。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "油性笔", "label": "复合词"}, {"form": "油性漆", "label": "复合词"}], "register": "中性", "sense_fingerprint": "油性|名词|含有油的性质，如油性皮肤容易出油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48a0f7c-0a18-4c7c-afd7-fbb2dab8e04e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性 yóu xìng，指含有油的性质，如油性皮肤容易出油。"}, {"text": "有幸", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。"}, {"text": "游行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。"}, {"text": "优性", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，优性在遗传学中指显性性状，与“劣性”相对。"}], "explanations": {"油性": "油性 yóu xìng，指含有油的性质，如油性皮肤容易出油。", "有幸": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。", "游行": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。", "优性": "yōu（第一声）与 yóu（第二声）声调不同，优性在遗传学中指显性性状，与“劣性”相对。"}, "sentence_index": null, "correct_answer": "油性"}, "level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：描述皮肤的含油性质，与“脸上一到中午就出油”相符。"}, {"text": "干性", "is_correct": false, "explanation": "语义：干性皮肤不容易出油，与“出油”矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥的皮肤缺少油分，与“出油”矛盾。"}, {"text": "冷冻", "is_correct": false, "explanation": "搭配：冷冻是低温处理，不能用来形容皮肤。"}], "explanations": {"油性": "油性：描述皮肤的含油性质，与“脸上一到中午就出油”相符。", "干性": "语义：干性皮肤不容易出油，与“出油”矛盾。", "干燥": "语义：干燥的皮肤缺少油分，与“出油”矛盾。", "冷冻": "搭配：冷冻是低温处理，不能用来形容皮肤。"}, "sentence_index": 0, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很油性，大家都不太喜欢。", "explanation": "这里应该用〈圆滑〉。油性只描述物质或皮肤、头发等含油的性质，不形容人的说话和性格。"}, {"text": "这里的空气很油性，早上散步很舒服。", "explanation": "这里应该用〈清新〉。油性指含油的性质，空气不含油，不能这样形容。"}, {"text": "鸟叫声很油性，听起来很清脆。", "explanation": "这里应该用〈悦耳〉。油性不形容声音，好听的鸟鸣要说悦耳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：指皮肤含油多，正适合用不含油的护肤品，与句意相符。"}, {"text": "干裂", "is_correct": false, "explanation": "语义：干裂皮肤缺油，需要含油的滋润护肤品，与“不含油”矛盾。"}, {"text": "紧绷", "is_correct": false, "explanation": "语义：紧绷感多来自缺油，应选含油的滋润品，与“不含油”矛盾。"}, {"text": "发酵", "is_correct": false, "explanation": "搭配：发酵是微生物作用的过程，不能用来形容皮肤。"}], "explanations": {"油性": "油性：指皮肤含油多，正适合用不含油的护肤品，与句意相符。", "干裂": "语义：干裂皮肤缺油，需要含油的滋润护肤品，与“不含油”矛盾。", "紧绷": "语义：紧绷感多来自缺油，应选含油的滋润品，与“不含油”矛盾。", "发酵": "搭配：发酵是微生物作用的过程，不能用来形容皮肤。"}, "sentence_index": 6, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很油性，我喝不下去。", "explanation": "这里应该用〈油腻〉。油性说的是皮肤、头发或物品含油的性质，形容食物油多要用油腻。"}, {"text": "他的嗓子很油性，说话很费力。", "explanation": "这里应该用〈沙哑〉。油性不形容嗓音，嗓子发不出清亮的声音时要说沙哑。"}, {"text": "这条路很油性，下雨时很危险。", "explanation": "这里应该用〈光滑〉。油性说的是含油的性质，路面湿滑要说光滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油性地皮肤在夏天最容易出油。", "corrected_sentence": "油性的皮肤在夏天最容易出油。", "error_description": "助词错误：修饰名词“皮肤”应用“的”，“地”用于修饰动词，不能用于名词前。应为“油性的皮肤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种皮肤很油性着，要常常洗脸。", "corrected_sentence": "这种皮肤很油性，要常常洗脸。", "error_description": "体标错误：形容词作谓语后不能加“着”，应删去“着”，为“很油性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
