INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着原来的样子再做一份。", "primary_collocate": null, "pronunciation": "fù zhì", "ipa": "fu˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我想复制这张照片，给妈妈一份。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这段文字复制下来。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复制了朋友的音乐，放进手机里。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印店可以复制各种文件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她照着原画复制了一幅。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把钥匙丢了，得再复制一把。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机复制了网页上的地址。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复制前，先看清楚原件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器能复制一模一样的杯子。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复制过好几份旧文件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复制了", "label": "体标"}, {"form": "复制过", "label": "体标"}, {"form": "复制品", "label": "复合"}], "register": "中性", "sense_fingerprint": "复制：照着原样再做一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48a0f7c-0a18-4c7c-afd7-fbb2dab8e04e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。"}, {"text": "副职", "is_correct": false, "explanation": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。"}, {"text": "扶植", "is_correct": false, "explanation": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。"}, {"text": "复试", "is_correct": false, "explanation": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。"}], "explanations": {"复制": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。", "副职": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。", "扶植": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。", "复试": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：依原样再做一份，句中是再做一张照片给妈妈。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除后照片就没有了，无法再给妈妈一份。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁的照片不能再给妈妈，与“给妈妈一份”矛盾。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“照片”搭配，照片不能咬。"}], "explanations": {"复制": "复制：依原样再做一份，句中是再做一张照片给妈妈。", "删除": "语义：删除后照片就没有了，无法再给妈妈一份。", "撕毁": "语义：撕毁的照片不能再给妈妈，与“给妈妈一份”矛盾。", "咬": "搭配：“咬”不能与“照片”搭配，照片不能咬。"}, "sentence_index": 0, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子总喜欢复制大人的心情。", "explanation": "这里应该用〈体会〉。心情不是可以依原样仿制的物件或资料，复制不能用于感受。"}, {"text": "他复制了父亲留下的家业。", "explanation": "这里应该用〈继承〉。家业是人的财产，要用“继承”，不能说“复制”。"}, {"text": "他复制了这段路的长度。", "explanation": "这里应该用〈计算〉。复制指照着原样再做一份，路的长度是数量，要用“计算”，不能说“复制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。"}, {"text": "福祉", "is_correct": false, "explanation": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。"}, {"text": "父子", "is_correct": false, "explanation": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。"}, {"text": "副食", "is_correct": false, "explanation": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。"}], "explanations": {"复制": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。", "福祉": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。", "父子": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。", "副食": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：照着原样再做一份，句中是把网页上的地址再抄下一份。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”只用于音视频，不能与“地址”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只用于歌曲等，不能与“地址”搭配。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞下去的地址就不在网页上了，与句意矛盾。"}], "explanations": {"复制": "复制：照着原样再做一份，句中是把网页上的地址再抄下一份。", "播放": "搭配：“播放”只用于音视频，不能与“地址”搭配。", "唱": "搭配：“唱”只用于歌曲等，不能与“地址”搭配。", "吞": "语义：吞下去的地址就不在网页上了，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子复制了母亲的酒窝。", "explanation": "这里应该用〈遗传〉。复制是依原样仿制物件或资料；酒窝是由父母遗传的，不说复制。"}, {"text": "她复制了刚才那份喜悦。", "explanation": "这里应该用〈回味〉。复制指照着原来的样子再做一份，喜悦这类感受只能回味，不能复制。"}, {"text": "演员复制了那位英雄的一生。", "explanation": "这里应该用〈再现〉。一生的经历不是可以仿制的原件，要用“再现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这首歌复制在了移动硬盘里。", "corrected_sentence": "我把这首歌复制到了移动硬盘里。", "error_description": "补语错误：复制的去向要用介词“到”，应说“复制到移动硬盘里”，不说“复制在移动硬盘里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把合同复制了到电脑里。", "corrected_sentence": "我把合同复制到了电脑里。", "error_description": "体标位置错误：“了”应放在补语“到”之后，说“复制到了电脑里”，不说“复制了到电脑里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd05822-d555-47ea-a413-92af87055a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提高", "is_correct": true, "explanation": "正确：「提高」与「降低」意思相反，指使水平、数量等变高。"}, {"text": "游泳", "is_correct": false, "explanation": "与「降低」没有反义关系，「游泳」指在水里活动。"}, {"text": "观察", "is_correct": false, "explanation": "与「降低」没有反义关系，「观察」指仔细地看。"}, {"text": "制造", "is_correct": false, "explanation": "与「降低」没有反义关系，「制造」指做出东西。"}], "correct_answer": "提高", "explanations": {"提高": "正确：「提高」与「降低」意思相反，指使水平、数量等变高。", "游泳": "与「降低」没有反义关系，「游泳」指在水里活动。", "观察": "与「降低」没有反义关系，「观察」指仔细地看。", "制造": "与「降低」没有反义关系，「制造」指做出东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
